Future<void> _pumpUntilFound(
  WidgetTester tester,
  Finder finder, {
  Duration timeout = const Duration(seconds: 2),
}) async {
  var elapsed = Duration.zero;
  while (elapsed < timeout) {
    await tester.pump(const Duration(milliseconds: 50));
    elapsed += const Duration(milliseconds: 50);
    if (finder.evaluate().isNotEmpty) return;
  }
}

Future<void> _pumpUntilCondition(
  WidgetTester tester,
  FutureOr<bool> Function() condition, {
  Duration timeout = const Duration(seconds: 2),
  String reason = 'condition',
}) async {
  var elapsed = Duration.zero;
  while (elapsed < timeout) {
    await tester.pump(const Duration(milliseconds: 50));
    elapsed += const Duration(milliseconds: 50);
    if (await condition()) {
      await tester.pump(const Duration(milliseconds: 1));
      return;
    }
  }
  fail('Timed out waiting for $reason');
}

Future<bool> _hasCachedStandardReportForPgn(
  MemoryAppPreferencesStore store,
  String pgn,
) async {
  final normalized = pgn.trim();
  final reports = (await store.read()).analysisReports;
  return reports.values.any(
    (entry) => entry.pgn.trim() == normalized && entry.hasStandard,
  );
}

