ChessBoardMove _testMoveFromFen(String fen, String uci) {
  final position = loadDartChessPosition(fen);
  final move = dc.NormalMove.fromUci(uci);
  final (nextPosition, san) = position.makeSan(move);
  return ChessBoardMove(
    from: move.from.name,
    to: move.to.name,
    promotion: move.promotion?.letter,
    san: san,
    fen: nextPosition.fen,
    state: ChessBoardState.fromPosition(
      nextPosition,
      lastMove: [move.from.name, move.to.name],
    ),
  );
}

Offset _boardSquareCenter(WidgetTester tester, String square) {
  final boardRect = tester.getRect(find.byType(InteractiveChessBoard).first);
  final file = ChessBoard.files.indexOf(square[0]);
  final rank = int.parse(square.substring(1));
  final squareSize = boardRect.width / 8;
  return Offset(
    boardRect.left + (file + 0.5) * squareSize,
    boardRect.top + (8 - rank + 0.5) * squareSize,
  );
}

