ChessnutApp _testApp({
  http.Client? httpClient,
  RecaptchaService? recaptchaService,
  PositionAnalyzer? positionAnalyzer = const _NoopPositionAnalyzer(),
  PhysicalBoardGateway? boardGateway,
  AuthService? authService,
  ChessnutSessionStore? sessionStore,
  LoginCredentialStore? credentialStore,
  AppPreferencesStore? appPreferencesStore,
  LocalGameRecordStore? localGameRecordStore,
  BoardBackgroundConnectionService? boardBackgroundConnectionService,
  Evo2UsbPowerService? evo2UsbPowerService,
  Evo2DisplayService? evo2DisplayService,
  ChessClockSwitchService? clockSwitchService,
  DevicePerformanceService? devicePerformanceService,
  NetworkLatencyProbe? networkLatencyProbe,
  TurnstileChallengePresenter? turnstileChallengePresenter,
  LichessAuthorizationPresenter? lichessAuthorizationPresenter,
  ReviewPromptService? reviewPromptService,
  ReportShareService? reportShareService,
  CourseLessonRepository? courseLessonRepository,
  CourseVideoAdapter Function()? courseVideoAdapterFactory,
  AnalysisPgnFileLoader? analysisPgnFileLoader,
  ModelBuildPgnFileLoader? modelBuildPgnFileLoader,
  bool? modelBuildFileImportAvailableOverride,
  Lc0WeightLibraryStore? lc0WeightLibraryStore,
  String? initialScreen,
  WindowsDisplayPowerService? windowsDisplayPowerService,
}) {
  final localStore = localGameRecordStore ?? LocalGameRecordStore.inMemory();
  addTearDown(localStore.close);
  return ChessnutApp(
    httpClient: httpClient ?? _emptyBackendClient(),
    recaptchaService: recaptchaService,
    positionAnalyzer: positionAnalyzer,
    boardGateway: boardGateway ?? MemoryPhysicalBoardGateway(),
    authService: authService,
    sessionStore: sessionStore ?? MemoryChessnutSessionStore(),
    credentialStore: credentialStore ?? MemoryLoginCredentialStore(),
    appPreferencesStore: appPreferencesStore ?? MemoryAppPreferencesStore(),
    localGameRecordStore: localStore,
    boardBackgroundConnectionService:
        boardBackgroundConnectionService ?? _FakeBoardBackgroundService(),
    evo2UsbPowerService:
        evo2UsbPowerService ?? const _InactiveEvo2UsbPowerService(),
    evo2DisplayService:
        evo2DisplayService ?? const _RecordingEvo2DisplayService(),
    clockSwitchService: clockSwitchService,
    devicePerformanceService:
        devicePerformanceService ?? const _EmptyDevicePerformanceService(),
    networkLatencyProbe: networkLatencyProbe,
    courseLessonRepository:
        courseLessonRepository ?? const _FakeCourseLessonRepository(),
    courseVideoAdapterFactory:
        courseVideoAdapterFactory ?? _FakeCourseVideoAdapter.new,
    analysisPgnFileLoader: analysisPgnFileLoader,
    modelBuildPgnFileLoader: modelBuildPgnFileLoader,
    modelBuildFileImportAvailableOverride:
        modelBuildFileImportAvailableOverride,
    lc0WeightLibraryStore: lc0WeightLibraryStore,
    initialScreen: initialScreen,
    windowsDisplayPowerService: windowsDisplayPowerService ??
        const _InactiveWindowsDisplayPowerService(),
    turnstileChallengePresenter:
        turnstileChallengePresenter ?? _fakeTurnstilePresenter,
    lichessAuthorizationPresenter:
        lichessAuthorizationPresenter ?? _fakeLichessAuthorizationPresenter,
    reviewPromptService: reviewPromptService,
    reportShareService: reportShareService,
  );
}

