bool _isMoveLedCommand(List<int> command) {
  return command.length == 34 && command[0] == 0x43 && command[1] == 0x20;
}

bool _moveLedCommandContainsColor(
  List<int> command,
  ChessnutMoveLedColor color,
) {
  if (!_isMoveLedCommand(command)) return false;
  return command.skip(2).any(
        (byte) => (byte >> 4) == color.code || (byte & 0x0f) == color.code,
      );
}

List<int>? _lastMoveLedCommand(List<List<int>> commands) {
  for (final command in commands.reversed) {
    if (_isMoveLedCommand(command)) return command;
  }
  return null;
}

class _EmptyDevicePerformanceService implements DevicePerformanceService {
  const _EmptyDevicePerformanceService();

  @override
  Future<DevicePerformanceProfile?> readProfile() async => null;
}

class _FixedDevicePerformanceService implements DevicePerformanceService {
  const _FixedDevicePerformanceService(this.profile);

  final DevicePerformanceProfile profile;

  @override
  Future<DevicePerformanceProfile?> readProfile() async => profile;
}

class _CompletingDevicePerformanceService implements DevicePerformanceService {
  _CompletingDevicePerformanceService(this.completer);

  final Completer<DevicePerformanceProfile?> completer;

  @override
  Future<DevicePerformanceProfile?> readProfile() => completer.future;
}

class _RecordingEvo2DisplayService implements Evo2DisplayService {
  const _RecordingEvo2DisplayService([this.orientations]);

  final List<Evo2ScreenOrientation>? orientations;

  @override
  Future<bool> setScreenOrientation(
    Evo2ScreenOrientation orientation,
  ) async {
    orientations?.add(orientation);
    return true;
  }
}

class _FakeBoardBackgroundService implements BoardBackgroundConnectionService {
  int keepAliveCalls = 0;
  int disconnectHardwareCalls = 0;
  final keepAliveRequests = <_KeepAliveRequest>[];

  @override
  Future<void> setKeepAlive({
    required bool enabled,
    required bool connected,
    required ChessnutBoardModel boardModel,
  }) async {
    keepAliveCalls += 1;
    keepAliveRequests.add(_KeepAliveRequest(
      enabled: enabled,
      connected: connected,
      boardModel: boardModel,
    ));
  }

  @override
  Future<void> disconnectBoardHardware() async {
    disconnectHardwareCalls += 1;
  }
}

class _InactiveEvo2UsbPowerService implements Evo2UsbPowerService {
  const _InactiveEvo2UsbPowerService();

  @override
  Stream<Evo2ScreenPowerEvent> get screenStateChanges => const Stream.empty();

  @override
  Future<bool> isScreenOff() async => false;

  @override
  Future<bool> setScreenOffPolicy({
    required bool enabled,
    required bool gameActive,
  }) async =>
      true;

  @override
  Future<bool> setUsbPower(bool enabled) async => true;
}

class _InactiveWindowsDisplayPowerService
    implements WindowsDisplayPowerService {
  const _InactiveWindowsDisplayPowerService();

  @override
  bool get isSupported => false;

  @override
  Stream<bool> get displayOffChanges => const Stream.empty();

  @override
  Future<bool> isDisplayOff() async => false;
}

class _FakeWindowsDisplayPowerService implements WindowsDisplayPowerService {
  final StreamController<bool> _controller = StreamController<bool>.broadcast();

  bool displayOff = false;

  @override
  bool get isSupported => true;

  @override
  Stream<bool> get displayOffChanges => _controller.stream;

  @override
  Future<bool> isDisplayOff() async => displayOff;

  void setDisplayOff(bool value) {
    displayOff = value;
    _controller.add(value);
  }

  Future<void> dispose() => _controller.close();
}

class _KeepAliveRequest {
  const _KeepAliveRequest({
    required this.enabled,
    required this.connected,
    required this.boardModel,
  });

  final bool enabled;
  final bool connected;
  final ChessnutBoardModel boardModel;
