class _FakeVoiceMoveRecognitionService extends VoiceMoveRecognitionService {
  _FakeVoiceMoveRecognitionService()
      : super(openAiKeyProvider: () async => 'test-key');

  final _events = StreamController<VoiceMoveRecognitionEvent>.broadcast();
  bool started = false;
  bool stopped = false;
  bool _closed = false;

  @override
  Stream<VoiceMoveRecognitionEvent> get events => _events.stream;

  @override
  Future<bool> start({
    required VoiceMoveRecognitionMode mode,
    required AppLanguagePreference language,
    Locale? systemLocale,
  }) async {
    started = true;
    _events.add(const VoiceMoveRecognitionEvent.listening());
    return true;
  }

  @override
  Future<void> stop() async {
    stopped = true;
    if (!_closed) _events.add(const VoiceMoveRecognitionEvent.ended());
  }

  void addResult(String text) {
    if (_closed) return;
    _events.add(VoiceMoveRecognitionEvent.result(text));
  }

  @override
  Future<void> dispose() async {
    if (_closed) return;
    _closed = true;
    await _events.close();
  }
}

