List<int> _courseLedAt(int index) {
  return List<int>.generate(64, (square) => square == index ? 0xff0000 : 0);
}

List<int> _courseLedForSquares(Set<String> squares) {
  final led = List<int>.filled(64, 0);
  for (final square in squares) {
    final file = square.codeUnitAt(0) - 'a'.codeUnitAt(0);
    final rank = int.parse(square[1]);
    led[(8 - rank) * 8 + file] = 0xff0000;
  }
  return led;
}

