class _RecordingPositionAnalyzer implements PositionAnalyzer {
  _RecordingPositionAnalyzer();

  final calls = <String>[];
  final depths = <int>[];

  @override
  Future<PositionEngineAnalysis?> analyzeFen(
    String fen, {
    int depth = 12,
    int multiPv = 1,
  }) async {
    calls.add(fen);
    depths.add(depth);
    final position = loadDartChessPosition(fen);
    final firstLegalMove = dc
        .makeLegalMoves(position)
        .entries
        .expand(
          (entry) => entry.value.map(
            (to) => dc.NormalMove(from: entry.key, to: to).uci,
          ),
        )
        .firstOrNull;
    return PositionEngineAnalysis(
      fen: fen,
      depth: depth,
      whiteEval: calls.length == 1 ? 0.24 : 0.48,
      bestMoveUci: firstLegalMove,
      pv: firstLegalMove == null ? const [] : [firstLegalMove],
      isEngineBacked: true,
      candidateMoves: firstLegalMove == null
          ? const []
          : [
              EngineMoveCandidate(
                moveUci: firstLegalMove,
                scoreCentipawns: calls.length == 1 ? 24 : 48,
              ),
            ],
    );
  }
}

class _DelayedPositionAnalyzer implements PositionAnalyzer {
  _DelayedPositionAnalyzer(this.completer);

  final Completer<void> completer;
  int calls = 0;

  @override
  Future<PositionEngineAnalysis?> analyzeFen(
    String fen, {
    int depth = 12,
    int multiPv = 1,
  }) async {
    calls++;
    await completer.future;
    return PositionEngineAnalysis(
      fen: fen,
      depth: depth,
      whiteEval: calls.isOdd ? 0.35 : -0.15,
      bestMoveUci: 'e2e4',
      pv: const ['e2e4', 'e7e5'],
      isEngineBacked: true,
      candidateMoves: const [
        EngineMoveCandidate(moveUci: 'e2e4', scoreCentipawns: 30),
        EngineMoveCandidate(moveUci: 'd2d4', scoreCentipawns: 10),
      ],
    );
  }
}

