class _SequencePositionAnalyzer implements PositionAnalyzer {
  _SequencePositionAnalyzer(this.evals, {this.mates = const []});

  final List<double?> evals;
  final List<int?> mates;
  final calls = <String>[];

  @override
  Future<PositionEngineAnalysis?> analyzeFen(
    String fen, {
    int depth = 12,
    int multiPv = 1,
  }) async {
    calls.add(fen);
    final index = (calls.length - 1).clamp(0, evals.length - 1);
    final eval = evals[index];
    if (eval == null) return null;
    return PositionEngineAnalysis(
      fen: fen,
      depth: depth,
      whiteEval: eval,
      whiteMate: index < mates.length ? mates[index] : null,
      bestMoveUci: null,
      pv: const [],
      isEngineBacked: true,
    );
  }
}

class _ScriptedBotEngineAdapter extends BotEngineAdapter {
  const _ScriptedBotEngineAdapter(this.moves);

  final List<String> moves;

  @override
  Future<BotMoveResult?> bestMove({
    required String fen,
    required BotGameConfig config,
    List<String> moveHistory = const [],
  }) async {
    final position = loadDartChessPosition(fen);
    if (position.isGameOver) return null;
    final index = position.ply - 1;
    if (index < 0 || index >= moves.length) return null;
    final move = dc.NormalMove.fromUci(moves[index]);
    if (!position.isLegal(move)) return null;
    final (nextPosition, san) = position.makeSan(move);
    return BotMoveResult(move: move, san: san, fen: nextPosition.fen);
  }
}

