class _DelayedBotEngineAdapter extends BotEngineAdapter {
  const _DelayedBotEngineAdapter({
    required this.uci,
    required this.delay,
  }) : moves = null;

  const _DelayedBotEngineAdapter.scripted({
    required this.moves,
    required this.delay,
  }) : uci = null;

  final String? uci;
  final List<String>? moves;
  final Duration delay;

  @override
  Future<BotMoveResult?> bestMove({
    required String fen,
    required BotGameConfig config,
    List<String> moveHistory = const [],
  }) async {
    await Future<void>.delayed(delay);
    final position = loadDartChessPosition(fen);
    final sequence = moves;
    final moveIndex = moveHistory.length ~/ 2;
    final moveUci = sequence == null
        ? uci
        : moveIndex < sequence.length
            ? sequence[moveIndex]
            : null;
    if (moveUci == null) return null;
    final move = dc.NormalMove.fromUci(moveUci);
    if (!position.isLegal(move)) return null;
    final (nextPosition, san) = position.makeSan(move);
    return BotMoveResult(move: move, san: san, fen: nextPosition.fen);
  }
}

