class _RecordingClockSwitchService extends ChessClockSwitchService {
  _RecordingClockSwitchService({
    this.emitProgrammaticSwitchEvents = false,
  }) : super(enableUsbButtons: false);

  final bool emitProgrammaticSwitchEvents;

  final _events = StreamController<int>.broadcast();
  final switchedSides = <ChessClockSide>[];
  int oppositeSwitches = 0;
  int enableUsbButtonsCalls = 0;
  ChessClockSide? lastSide;

  @override
  Stream<int> get switchEvents => _events.stream;

  void emitSwitch([ChessClockSide side = ChessClockSide.left]) {
    lastSide = side;
    _events.add(side.value);
  }

  @override
  void initialize() {}

  @override
  void enableUsbButtons() {
    enableUsbButtonsCalls += 1;
  }

  @override
  Future<bool> switchTo(ChessClockSide side) async {
    lastSide = side;
    switchedSides.add(side);
    if (emitProgrammaticSwitchEvents) {
      _events.add(side.value);
    }
    return true;
  }

  @override
  Future<bool> switchToOpposite() async {
    oppositeSwitches += 1;
    final side = (lastSide ?? ChessClockSide.left).opposite;
    lastSide = side;
    if (emitProgrammaticSwitchEvents) {
      _events.add(side.value);
    }
    return true;
  }

  @override
  Future<ChessClockSide?> readLastSide() async => lastSide;

  @override
  Future<void> dispose() async {
    await _events.close();
  }
}

class _MutableChessComWebViewAdapter implements ChessComWebViewAdapter {
  _MutableChessComWebViewAdapter(
    this.currentFen, {
    this.players,
    this.resultToken,
    this.localPlayerIsWhite = true,
    this.timeControl,
    this.gameSite,
  });

  String currentFen;
  Map<String, String>? players;
  String? resultToken;
  String? timeControl;
  String? gameSite;
  Map<String, Object?>? completeRecord;
  final List<String> _sanMoves = [];
  bool? localPlayerIsWhite;
  Uri? loadedUrl;
  bool ready = false;
  final scripts = <String>[];
  int reloads = 0;
  VoidCallback? recoverCallback;

  @override
  bool get isReady => ready;

  @override
  Future<void> initialize({
    required Uri initialUrl,
    required VoidCallback onPageStarted,
    required Future<void> Function() onPageFinished,
    required VoidCallback onRecoverRequested,
  }) async {
    loadedUrl = initialUrl;
    recoverCallback = onRecoverRequested;
    ready = true;
    onPageStarted();
    await onPageFinished();
  }

  @override
  Future<Object?> runJavaScript(String script) async {
    scripts.add(script);
    if (script == 'window.getCurrentFEN()') {
      return currentFen;
    }
    if (script == 'window.getCurrentPGN()') {
      final completePgn = completeRecord?['pgn']?.toString().trim();
      if (completePgn != null && completePgn.isNotEmpty) return completePgn;
      final white = players?['white']?.trim();
      final black = players?['black']?.trim();
      if (white == null || white.isEmpty || black == null || black.isEmpty) {
        return null;
      }
      final result =
          resultToken?.trim().isNotEmpty == true ? resultToken! : '*';
      final rawTimeControl = timeControl?.trim() ?? '';
      final timeControlSeconds = RegExp(r'^\d+\+\d+$').hasMatch(rawTimeControl)
          ? '${(int.parse(rawTimeControl.split('+').first) * 60)}+'
              '${rawTimeControl.split('+').last}'
          : rawTimeControl;
      final moves = _sanMoves.isEmpty
          ? result
          : '${_sanMoves.asMap().entries.map((entry) {
              final ply = entry.key;
              return ply.isEven
                  ? '${ply ~/ 2 + 1}. ${entry.value}'
                  : entry.value;
            }).join(' ')} $result';
      return '''
[Event "Live Chess"]
[Site "${gameSite ?? 'https://www.chess.com/game/live/${identityHashCode(this)}'}"]
[Date "2026.08.26"]
[UTCDate "2026.08.26"]
[UTCTime "12:00:00"]
[White "$white"]
[Black "$black"]
[Result "$result"]
[TimeControl "$timeControlSeconds"]

$moves
''';
    }
    if (script.startsWith('window.makeUCIMove(')) {
      final encoded = script.substring(
        'window.makeUCIMove('.length,
        script.length - 1,
      );
      final uci = jsonDecode(encoded).toString();
      final position = loadDartChessPosition(currentFen);
      final move = dc.NormalMove.fromUci(uci);
      if (!position.isLegal(move)) return false;
      final (nextPosition, san) = position.makeSan(move);
      currentFen = nextPosition.fen;
      _sanMoves.add(san);
      return true;
    }
    if (script == 'window.getCurrentPlayers()') {
      return jsonEncode({
        if (players != null) ...players!,
        if (localPlayerIsWhite != null)
          'localPlayerIsWhite': localPlayerIsWhite,
      });
    }
    if (script == 'window.getCurrentResult()') {
      return resultToken;
    }
    if (script == 'window.getCurrentCompletePGN()') {
      return completeRecord == null ? null : jsonEncode(completeRecord);
    }
    if (script == 'window.getCurrentTimeControl()') {
      return timeControl;
    }
    return true;
  }

  @override
  Future<void> injectTextScaleGuard() async {}

  @override
  Future<void> reload() async {
    reloads += 1;
  }

  @override
  Widget build() {
    return const SizedBox(key: ValueKey('fake-chesscom-webview'));
  }

  @override
  Future<void> dispose() async {}
}

