class _BlockingMoveSoundService extends AppSoundService {
  final moveStarted = Completer<void>();
  final releaseMove = Completer<void>();

  @override
  Future<void> play(AppSoundEvent event) async {}

  @override
  Future<void> playMove(AppMoveSound move) async {
    if (!moveStarted.isCompleted) moveStarted.complete();
    await releaseMove.future;
  }
}

class _FakeRecaptchaService implements RecaptchaService {
  const _FakeRecaptchaService.success()
      : token = 'turnstile-token',
        message = null;

  const _FakeRecaptchaService.failure(this.message) : token = null;

  final String? token;
  final String? message;

  @override
  Future<RecaptchaResult> verify({required RecaptchaActionKind action}) async {
    final verifiedToken = token;
    if (verifiedToken == null) {
      return RecaptchaResult.failed(message ?? 'Turnstile failed.');
    }
    return RecaptchaResult.verified(
      token: verifiedToken,
      provider: RecaptchaProvider.cloudflareTurnstile,
    );
  }
}

