    return verifyHandler();
  }
}

class _FailingBoardGateway extends MemoryPhysicalBoardGateway {
  @override
  Future<bool> connect() async => false;
}

class _ReconnectFailingBoardGateway extends MemoryPhysicalBoardGateway {
  int connectAttempts = 0;

  @override
  Future<bool> connect() async {
    connectAttempts += 1;
    if (connectAttempts == 1) {
      return super.connect();
    }
    await disconnect();
    return false;
  }
}

class _RealtimeModeBoardGateway extends MemoryPhysicalBoardGateway {
  bool realtimeFenEnabled = false;
  final modeEvents = <String>[];

  @override
  Future<bool> setMoveBoardFen(
    String fen, {
    bool strictMode = false,
    bool isReverse = false,
  }) async {
    modeEvents.add('set');
    realtimeFenEnabled = false;
    return super.setMoveBoardFen(
      fen,
      strictMode: strictMode,
      isReverse: isReverse,
    );
  }

  @override
  Future<bool> enableRealtimeFen() async {
    modeEvents.add('enable');
    final enabled = await super.enableRealtimeFen();
    realtimeFenEnabled = enabled;
    return enabled;
  }

  void addRealtimeBoardFen(String boardOnlyFen) {
    if (realtimeFenEnabled) addBoardFen(boardOnlyFen);
  }

  void seedLatestBoardFen(String boardOnlyFen) {
    addBoardFen(boardOnlyFen);
  }
}

bool _isGeneralLedCommand(List<int> command) {
  return command.length == 10 && command[0] == 0x0a && command[1] == 0x08;
}

bool _isClearGeneralLedCommand(List<int> command) {
  return _isGeneralLedCommand(command) &&
      command.skip(2).every((value) => value == 0);
}

class _BlockingGeneralLedGateway extends MemoryPhysicalBoardGateway {
  _BlockingGeneralLedGateway() : super(boardModel: PhysicalBoardModel.air);

  final firstSetLedWriteStarted = Completer<void>();
  final releaseFirstSetLedWrite = Completer<void>();
  bool _blockedFirstSetLedWrite = false;

  @override
  Future<bool> write(
    List<int> command, {
    bool withoutResponse = false,
  }) async {
    if (!_blockedFirstSetLedWrite &&
        _isGeneralLedCommand(command) &&
        !_isClearGeneralLedCommand(command)) {
      _blockedFirstSetLedWrite = true;
      firstSetLedWriteStarted.complete();
      await releaseFirstSetLedWrite.future;
    }
    return super.write(command, withoutResponse: withoutResponse);
  }
}

class _HoldGeneralLedGateway extends MemoryPhysicalBoardGateway {
  _HoldGeneralLedGateway() : super(boardModel: PhysicalBoardModel.air);

  bool allowLedWrites = false;
  int setLedAttempts = 0;

  @override
  Future<bool> write(
    List<int> command, {
    bool withoutResponse = false,
  }) async {
    if (_isGeneralLedCommand(command) && !_isClearGeneralLedCommand(command)) {
      setLedAttempts += 1;
      if (!allowLedWrites) return false;
    }
    return super.write(command, withoutResponse: withoutResponse);
  }
}

