String _lichessPgnGames({
  required int start,
  required int count,
  String player = 'storm123',
  String event = 'Lichess Rated Rapid',
  String opponentPrefix = 'lichessOpponent',
}) {
  return [
    for (var offset = 0; offset < count; offset += 1)
      () {
        final game = start + offset;
        final day = math.max(1, 28 - game).toString().padLeft(2, '0');
        return '[Event "$event"]\n'
            '[Site "https://lichess.org/sample$game"]\n'
            '[Date "2026.06.$day"]\n'
            '[UTCDate "2026.06.$day"]\n'
            '[UTCTime "12:00:00"]\n'
            '[White "$player"]\n'
            '[Black "$opponentPrefix$game"]\n'
            '[TimeControl "10+5"]\n\n'
            '1. e4 e5 2. Nf3 Nc6 *';
      }(),
  ].join('\n\n\n');
}

