void main() {
  setUp(() async {
    SharedPreferences.setMockInitialValues({
      AppSettingKeys.moduleGuideSeenIds:
          moduleGuideDefinitions.map((definition) => definition.id).toList(),
    });
    AppSharedPreferences.useInstanceForTesting(
      await SharedPreferences.getInstance(),
    );
  });

  testWidgets(
      'Vision notification follows the app language setting immediately',
      (tester) async {
    tester.view.physicalSize = const Size(1920, 1080);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    tester.binding.platformDispatcher.localeTestValue = const Locale('ja');
    tester.binding.platformDispatcher.localesTestValue = const [Locale('ja')];
    addTearDown(tester.binding.platformDispatcher.clearLocaleTestValue);
    addTearDown(tester.binding.platformDispatcher.clearLocalesTestValue);
    AppSharedPreferences.set(AppSettingKeys.language, 'fr');
    const widgetChannel = MethodChannel('chessnut/home_widget');
    const visionChannel = MethodChannel('chessnut/accessibility_vision');
    final messenger = tester.binding.defaultBinaryMessenger;
    final statuses = <Map<dynamic, dynamic>>[];
    messenger.setMockMethodCallHandler(widgetChannel, (call) async {
      if (call.method == 'readVisionEnabled') return true;
      return null;
    });
    messenger.setMockMethodCallHandler(visionChannel, (call) async {
      if (call.method == 'isAccessibilityRunning') return true;
      if (call.method == 'setRecognitionStatus') {
        statuses.add(call.arguments as Map);
      }
      return null;
    });
    addTearDown(() {
      messenger.setMockMethodCallHandler(widgetChannel, null);
      messenger.setMockMethodCallHandler(visionChannel, null);
    });
    await tester.pumpWidget(_testApp(initialScreen: 'Settings'));
    await tester.pumpAndSettle();
    expect(statuses.last['languageTag'], 'fr');
    for (final preference in [
      AppLanguagePreference.en,
      AppLanguagePreference.zhHans,
      AppLanguagePreference.zhHant,
      AppLanguagePreference.ar,
      AppLanguagePreference.system,
    ]) {
      tester
          .widget<AppShell>(find.byType(AppShell))
          .onLanguagePreferenceChanged(preference);
      await tester.pumpAndSettle();
      expect(statuses.last['languageTag'], preference.tag);
      expect(statuses.last['enabled'], isTrue);
    }
    expect(Localizations.localeOf(tester.element(find.byType(AppShell))),
        const Locale('ja'));
    await tester.pumpWidget(const SizedBox.shrink());
    await tester.pumpAndSettle();
  });

  for (final availability in ['denied', 'unavailable', 'granted']) {
    testWidgets('Vision startup validates accessibility: $availability',
        (tester) async {
      AppSharedPreferences.set(AppSettingKeys.widgetVisionEnabled, true);
      const widgetChannel = MethodChannel('chessnut/home_widget');
      const visionChannel = MethodChannel('chessnut/accessibility_vision');
      final messenger = tester.binding.defaultBinaryMessenger;
      var nativeEnabled = true;
      var accessibilityRunning = availability == 'granted';
      final notifications = <bool>[];
      messenger.setMockMethodCallHandler(widgetChannel, (call) async {
        if (call.method == 'readVisionEnabled') return nativeEnabled;
        if (call.method == 'setVisionEnabled') {
          nativeEnabled = (call.arguments as Map)['enabled'] == true;
        }
        return null;
      });
      messenger.setMockMethodCallHandler(visionChannel, (call) async {
        if (call.method == 'isAccessibilityRunning') {
          if (availability == 'unavailable') {
            throw PlatformException(code: 'unavailable');
          }
          return accessibilityRunning;
        }
        if (call.method == 'setRecognitionStatus') {
          notifications.add((call.arguments as Map)['enabled'] == true);
        }
        return null;
      });
      addTearDown(() {
        messenger.setMockMethodCallHandler(widgetChannel, null);
        messenger.setMockMethodCallHandler(visionChannel, null);
      });
      await tester.pumpWidget(_testApp(initialScreen: 'Home'));
      await tester.pumpAndSettle();
      expect(tester.widget<HomeScreen>(find.byType(HomeScreen)).visionEnabled,
          accessibilityRunning);
      expect(nativeEnabled, accessibilityRunning);
      expect(AppSharedPreferences.get<bool>(AppSettingKeys.widgetVisionEnabled),
          accessibilityRunning);
      if (!accessibilityRunning) {
        expect(notifications, isNot(contains(true)));
      } else {
        accessibilityRunning = false;
        tester.binding
            .handleAppLifecycleStateChanged(AppLifecycleState.inactive);
        tester.binding
            .handleAppLifecycleStateChanged(AppLifecycleState.resumed);
        await tester.pumpAndSettle();
        expect(tester.widget<HomeScreen>(find.byType(HomeScreen)).visionEnabled,
            isFalse);
        expect(nativeEnabled, isFalse);
        expect(notifications.last, isFalse);
        expect(
            AppSharedPreferences.get<bool>(AppSettingKeys.widgetVisionEnabled),
            isFalse);
        accessibilityRunning = true;
        tester.binding
            .handleAppLifecycleStateChanged(AppLifecycleState.inactive);
        tester.binding
            .handleAppLifecycleStateChanged(AppLifecycleState.resumed);
        await tester.pumpAndSettle();
        expect(tester.widget<HomeScreen>(find.byType(HomeScreen)).visionEnabled,
            isFalse,
            reason: 'Restoring permission must not turn Vision back on.');
      }
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpAndSettle();
    });
  }

  testWidgets(
      'Vision widget enable action cannot bypass accessibility permission',
      (tester) async {
    const widgetChannel = MethodChannel('chessnut/home_widget');
    const visionChannel = MethodChannel('chessnut/accessibility_vision');
    final messenger = tester.binding.defaultBinaryMessenger;
    var actionPending = true;
    final savedStates = <bool>[];
    messenger.setMockMethodCallHandler(widgetChannel, (call) async {
      if (call.method == 'readVisionEnabled') return false;
      if (call.method == 'setVisionEnabled') {
        savedStates.add((call.arguments as Map)['enabled'] == true);
      }
      if (call.method == 'consumeLaunchAction' && actionPending) {
        actionPending = false;
        return {'action': 'toggleVision', 'visionEnabled': true};
      }
      return null;
    });
    messenger.setMockMethodCallHandler(visionChannel, (call) async {
      if (call.method == 'isAccessibilityRunning') return false;
      return null;
    });
    addTearDown(() {
      messenger.setMockMethodCallHandler(widgetChannel, null);
      messenger.setMockMethodCallHandler(visionChannel, null);
    });
    await tester.pumpWidget(_testApp(initialScreen: 'Home'));
    await tester.pumpAndSettle();
    expect(actionPending, isFalse);
    expect(tester.widget<HomeScreen>(find.byType(HomeScreen)).visionEnabled,
        isFalse);
    expect(savedStates, isNotEmpty);
    expect(savedStates, isNot(contains(true)));
    expect(AppSharedPreferences.get<bool>(AppSettingKeys.widgetVisionEnabled),
        isFalse);
    await tester.pumpWidget(const SizedBox.shrink());
    await tester.pumpAndSettle();
  });

  testWidgets(
      'Vision delayed startup permission cannot undo an explicit disable',
      (tester) async {
    const widgetChannel = MethodChannel('chessnut/home_widget');
    const visionChannel = MethodChannel('chessnut/accessibility_vision');
    final messenger = tester.binding.defaultBinaryMessenger;
    final permission = Completer<bool>();
    var nativeEnabled = true;
    messenger.setMockMethodCallHandler(widgetChannel, (call) async {
      if (call.method == 'readVisionEnabled') return nativeEnabled;
      if (call.method == 'setVisionEnabled') {
        nativeEnabled = (call.arguments as Map)['enabled'] == true;
      }
      return null;
    });
    messenger.setMockMethodCallHandler(visionChannel, (call) async {
      if (call.method == 'isAccessibilityRunning') return permission.future;
      return null;
    });
    addTearDown(() {
      messenger.setMockMethodCallHandler(widgetChannel, null);
      messenger.setMockMethodCallHandler(visionChannel, null);
    });
    await tester.pumpWidget(_testApp(initialScreen: 'Home'));
    await tester.pump();
    await tester
        .widget<HomeScreen>(find.byType(HomeScreen))
        .onVisionEnabledChanged!(false);
    permission.complete(true);
