      expect(practiceRect.top, moreOrLessEquals(recordsRect.top));
      expect(recordsRect.top, moreOrLessEquals(engineRect.top));
      expect(playRect.left, lessThan(careerRect.left));
      expect(careerRect.left, lessThan(analysisRect.left));
      expect(practiceRect.left, lessThan(recordsRect.left));
      expect(recordsRect.left, lessThan(engineRect.left));
