      final viewport = Offset.zero & tester.view.physicalSize;

      expect(viewport.contains(spotlightRect.topLeft), isTrue);
      expect(viewport.contains(spotlightRect.bottomRight), isTrue);
      expect(
        (spotlightRect.center.dy - targetRect.center.dy).abs(),
        lessThan(12),
        reason: 'spotlight=$spotlightRect target=$targetRect',
      );
      expect(
        (spotlightRect.center.dx - targetRect.center.dx).abs(),
        lessThan(12),
        reason: 'spotlight=$spotlightRect target=$targetRect',
      );
      expect(calloutRect.top, greaterThanOrEqualTo(47));
      expect(calloutRect.bottom, lessThanOrEqualTo(844 - 34));
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

  testWidgets('iOS module guide first steps align across entry pages', (
    WidgetTester tester,
  ) async {
    AppSharedPreferences.set<List<String>>(
      AppSettingKeys.moduleGuideSeenIds,
      const [],
    );
