      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(top: 47, bottom: 34);
      tester.view.viewPadding = const FakeViewPadding(top: 47, bottom: 34);
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      addTearDown(tester.view.resetPadding);
      addTearDown(tester.view.resetViewPadding);

      const routeLabels = {
        'Home',
        'Setup',
        'Bot',
        'OtbSetup',
        'Clock',
        'Records',
        'Settings',
        'BoardSettings',
        'Training',
        'PuzzleThemes',
        'MistakeBook',
        'Engine',
        'Analysis',
        'Career',
        'Editor',
      };

      for (final routeLabel in routeLabels) {
        await tester.pumpWidget(const SizedBox.shrink());
        await tester.pump();
        await tester.pumpWidget(
          _testApp(
            appPreferencesStore: MemoryAppPreferencesStore(),
            initialScreen: routeLabel,
          ),
        );
        await _pumpUntilFound(
          tester,
          find.byKey(const ValueKey('module-guide-dialog')),
        );
        await tester.pump(const Duration(milliseconds: 300));

        final definition = moduleGuideDefinitionForRoute(routeLabel);
        final targetKey = definition?.steps.first.targetKey;
        expect(targetKey, isNotNull, reason: routeLabel);
        final targetFinder = find.byKey(targetKey!);
        if (targetFinder.evaluate().isEmpty) {
          final fallbackKey = definition?.steps.first.fallbackTargetKey;
          expect(fallbackKey, isNotNull, reason: routeLabel);
          await _pumpUntilFound(tester, find.byKey(fallbackKey!));
        }
        final effectiveTargetFinder = targetFinder.evaluate().isNotEmpty
            ? targetFinder
            : find.byKey(definition!.steps.first.fallbackTargetKey!);
        final spotlightFinder =
            find.byKey(const ValueKey('module-guide-spotlight'));
        final calloutFinder =
            find.byKey(const ValueKey('module-guide-callout'));

        await _pumpUntilCondition(
          tester,
          () {
            final spotlightRect = tester.getRect(spotlightFinder);
            final targetRect = tester.getRect(effectiveTargetFinder.first);
            return spotlightRect.overlaps(targetRect.inflate(18));
          },
          timeout: const Duration(seconds: 2),
          reason: '$routeLabel iOS guide target',
        );

        final spotlightRect = tester.getRect(spotlightFinder);
        final targetRect = tester.getRect(effectiveTargetFinder.first);
        final calloutRect = tester.getRect(calloutFinder);
        final viewport = Offset.zero & tester.view.physicalSize;
        expect(spotlightRect.left, greaterThanOrEqualTo(viewport.left),
            reason: routeLabel);
        expect(spotlightRect.top, greaterThanOrEqualTo(viewport.top),
            reason: routeLabel);
        expect(spotlightRect.right, lessThanOrEqualTo(viewport.right),
            reason: routeLabel);
        expect(spotlightRect.bottom, lessThanOrEqualTo(viewport.bottom),
            reason: routeLabel);
        expect(
          (spotlightRect.center - targetRect.center).distance,
          lessThan(24),
          reason: '$routeLabel spotlight=$spotlightRect target=$targetRect',
        );
        expect(calloutRect.top, greaterThanOrEqualTo(47), reason: routeLabel);
        expect(calloutRect.bottom, lessThanOrEqualTo(844 - 34),
            reason: routeLabel);
      }
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

  testWidgets('Module guide spotlights whole modules on clock landscape', (
    WidgetTester tester,
  ) async {
    AppSharedPreferences.set<List<String>>(
      AppSettingKeys.moduleGuideSeenIds,
      const [],
    );
    tester.view.physicalSize = const Size(1280, 480);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(
      _testApp(
        httpClient: _puzzleThemesBackendClient(),
        appPreferencesStore: MemoryAppPreferencesStore(),
        initialScreen: 'PuzzleThemes',
      ),
    );
    await _pumpUntilFound(
      tester,
      find.byKey(const ValueKey('module-guide-dialog')),
    );
    await _pumpUntilFound(tester, find.text('Theme puzzle #4137413'));
    await tester.pump(const Duration(milliseconds: 100));

    final spotlightRect =
        tester.getRect(find.byKey(const ValueKey('module-guide-spotlight')));
    final cardRect =
        tester.getRect(find.byKey(const ValueKey('puzzle-theme-chooser-card')));
    final titleRect = tester.getRect(find.text('Equality'));
    final countRect = tester.getRect(find.text('2,889 puzzles'));
    final buttonRect = tester
        .getRect(find.byKey(const ValueKey('puzzle-theme-choose-button')));
    final puzzleIdRect = tester.getRect(find.text('Theme puzzle #4137413'));
    final nextRect =
        tester.getRect(find.byKey(const ValueKey('puzzle-theme-next-button')));
    final targetUnion = titleRect
        .expandToInclude(countRect)
        .expandToInclude(buttonRect)
        .expandToInclude(puzzleIdRect)
        .expandToInclude(nextRect);

    expect(spotlightRect.left, lessThanOrEqualTo(cardRect.left + 1));
    expect(spotlightRect.top, lessThanOrEqualTo(cardRect.top + 1));
    expect(spotlightRect.right, greaterThanOrEqualTo(cardRect.right - 1));
    expect(spotlightRect.bottom, greaterThanOrEqualTo(cardRect.bottom - 1));
    expect(spotlightRect.left, lessThanOrEqualTo(targetUnion.left));
    expect(spotlightRect.top, lessThanOrEqualTo(targetUnion.top));
    expect(spotlightRect.right, greaterThanOrEqualTo(targetUnion.right));
    expect(spotlightRect.bottom, greaterThanOrEqualTo(targetUnion.bottom));
    expect(spotlightRect.height, greaterThan(buttonRect.height * 3));

    await tester.tap(find.byKey(const ValueKey('module-guide-next')));
    await _pumpUntilCondition(
      tester,
      () {
        final currentSpotlight = tester
            .getRect(find.byKey(const ValueKey('module-guide-spotlight')));
        final currentBoard = tester
            .getRect(find.byKey(const ValueKey('puzzle-theme-board-area')));
        return currentSpotlight.left <= currentBoard.left + 1 &&
            currentSpotlight.top <= currentBoard.top + 1 &&
            currentSpotlight.right >= currentBoard.right - 1 &&
            currentSpotlight.bottom >= currentBoard.bottom - 1;
      },
      reason: 'module guide spotlight moves to puzzle board',
    );

    final boardSpotlightRect =
        tester.getRect(find.byKey(const ValueKey('module-guide-spotlight')));
    final boardAreaRect =
        tester.getRect(find.byKey(const ValueKey('puzzle-theme-board-area')));

    expect(boardSpotlightRect.left, lessThanOrEqualTo(boardAreaRect.left + 1));
    expect(boardSpotlightRect.top, lessThanOrEqualTo(boardAreaRect.top + 1));
    expect(
      boardSpotlightRect.right,
      greaterThanOrEqualTo(boardAreaRect.right - 1),
    );
    expect(
      boardSpotlightRect.bottom,
      greaterThanOrEqualTo(boardAreaRect.bottom - 1),
    );
    expect(boardSpotlightRect.overlaps(cardRect), isFalse);
  });

