  test('Career opponents match current ELO inside the journey range', () {
    for (final elo in [600, 760, 960, 1190, 1500, 1790, 2075, 2240, 2490]) {
      final progress = CareerModeProgress.fromElo(elo);
      for (var seed = 0; seed < 20; seed += 1) {
        final opponent = CareerOpponentProfile.matchFor(
          progress: progress,
          seed: seed,
        );
        expect(
          opponent.elo,
          progress.currentElo,
          reason: 'opponent should match the current career ELO for $elo',
        );
        expect(
          opponent.elo >= progress.currentLevelElo,
          isTrue,
          reason: 'opponent ${opponent.elo} too low for $elo',
        );
        expect(
          opponent.elo <= progress.nextElo,
          isTrue,
          reason: 'opponent ${opponent.elo} too high for $elo',
        );
        if (!maia1SupportedElos.contains(opponent.elo)) {
          expect(opponent.engineKind, BotEngineKind.maia3);
        }
      }
    }
  });

