      'PuzzleThemes',
      'Engine',
      'Analysis',
      'Editor',
    };

    for (final routeLabel in routeLabels) {
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pump();
      await tester.pumpWidget(
        _testApp(
          appPreferencesStore: MemoryAppPreferencesStore(),
          initialScreen: routeLabel,
        ),
      );
      await _pumpUntilFound(
        tester,
        find.byKey(const ValueKey('module-guide-dialog')),
      );
      await tester.pump(const Duration(milliseconds: 100));

      final spotlightFinder =
          find.byKey(const ValueKey('module-guide-spotlight'));
      final calloutFinder = find.byKey(const ValueKey('module-guide-callout'));
      final guideScrollFinder = find.descendant(
        of: calloutFinder,
        matching: find.byKey(const ValueKey('module-guide-scroll')),
      );
      expect(spotlightFinder, findsOneWidget, reason: routeLabel);
      expect(calloutFinder, findsOneWidget, reason: routeLabel);
      expect(guideScrollFinder, findsOneWidget, reason: routeLabel);

      final spotlightRect = tester.getRect(spotlightFinder);
      final calloutRect = tester.getRect(calloutFinder);
      final nextRect =
          tester.getRect(find.byKey(const ValueKey('module-guide-next')));
      final viewport = Offset.zero & tester.view.physicalSize;
      expect(viewport.contains(spotlightRect.topLeft), isTrue,
          reason: routeLabel);
      expect(viewport.contains(spotlightRect.bottomRight), isTrue,
          reason: routeLabel);
      expect(viewport.contains(calloutRect.topLeft), isTrue,
          reason: routeLabel);
      expect(viewport.contains(calloutRect.bottomRight), isTrue,
          reason: routeLabel);
      expect(viewport.contains(nextRect.topLeft), isTrue, reason: routeLabel);
      expect(viewport.contains(nextRect.bottomRight), isTrue,
          reason: routeLabel);

      final definition = moduleGuideDefinitionForRoute(routeLabel);
      final targetKey = definition?.steps.first.targetKey;
      if (targetKey != null) {
        final targetFinder = find.byKey(targetKey);
        if (targetFinder.evaluate().isNotEmpty) {
          await _pumpUntilCondition(
            tester,
            () {
              final currentSpotlightRect = tester.getRect(spotlightFinder);
              final currentTargetRect = tester.getRect(targetFinder.first);
              return currentSpotlightRect.overlaps(
                currentTargetRect.inflate(18),
              );
            },
            timeout: const Duration(seconds: 1),
            reason: '$routeLabel guide target',
          );
          final targetRect = tester.getRect(targetFinder.first);
          final currentSpotlightRect = tester.getRect(spotlightFinder);
          final currentCalloutRect = tester.getRect(calloutFinder);
          expect(
            currentSpotlightRect.overlaps(targetRect.inflate(18)),
            isTrue,
            reason:
                '$routeLabel spotlight=$currentSpotlightRect target=$targetRect',
          );
          expect(
            currentCalloutRect.overlaps(targetRect),
            isFalse,
            reason:
                '$routeLabel callout=$currentCalloutRect target=$targetRect',
          );
        }
      }
    }
  });

