      await tester.pumpAndSettle();
      await expectSpotlightOn(const ValueKey('mistake-book-search-section'));
      await tester.tap(find.byKey(const ValueKey('module-guide-next')));
      await tester.pumpAndSettle();
      await expectSpotlightOn(const ValueKey('mistake-book-pager-section'));
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

