  testWidgets('iOS board editor guide targets precise editor controls', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.iOS;
    try {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(top: 47, bottom: 34);
      tester.view.viewPadding = const FakeViewPadding(top: 47, bottom: 34);
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      addTearDown(tester.view.resetPadding);
      addTearDown(tester.view.resetViewPadding);
      AppSharedPreferences.set<List<String>>(
        AppSettingKeys.moduleGuideSeenIds,
        moduleGuideDefinitions
            .map((definition) => definition.id)
            .where((id) => id != 'board_editor')
            .toList(),
      );
      final preferencesStore = MemoryAppPreferencesStore();

      await tester.pumpWidget(
        _testApp(
          appPreferencesStore: preferencesStore,
          initialScreen: 'Editor',
        ),
      );
      await _pumpUntilFound(
        tester,
        find.byKey(const ValueKey('module-guide-dialog')),
      );

      Future<void> expectCalloutClearOf(ValueKey<String> targetKey) async {
        final spotlightFinder =
            find.byKey(const ValueKey('module-guide-spotlight'));
        final calloutFinder =
            find.byKey(const ValueKey('module-guide-callout'));
        await _pumpUntilCondition(
          tester,
          () {
            final targetFinder = find.byKey(targetKey);
            if (targetFinder.evaluate().isEmpty) return false;
            final spotlightRect = tester.getRect(spotlightFinder);
            final targetRect = tester.getRect(targetFinder.first);
            return spotlightRect.overlaps(targetRect.inflate(18));
          },
          reason: 'iOS board editor guide target $targetKey',
        );

        final spotlightRect = tester.getRect(spotlightFinder);
        final calloutRect = tester.getRect(calloutFinder);
        final targetRect = tester.getRect(find.byKey(targetKey).first);
        expect(
          spotlightRect.width,
          lessThanOrEqualTo(targetRect.width + 44),
          reason: 'spotlight=$spotlightRect target=$targetRect',
        );
        expect(
          spotlightRect.height,
          lessThanOrEqualTo(targetRect.height + 44),
          reason: 'spotlight=$spotlightRect target=$targetRect',
        );
        expect(
          calloutRect.overlaps(spotlightRect),
          isFalse,
          reason: 'callout=$calloutRect spotlight=$spotlightRect',
        );
      }

      await expectCalloutClearOf(
        const ValueKey('board-editor-status-section'),
      );
      await tester.tap(find.byKey(const ValueKey('module-guide-next')));
      await tester.pumpAndSettle();
      await expectCalloutClearOf(
        const ValueKey('board-editor-edit-controls-section'),
      );
      await tester.tap(find.byKey(const ValueKey('module-guide-next')));
      await tester.pumpAndSettle();
      await expectCalloutClearOf(
        const ValueKey('board-editor-start-bot-button'),
      );
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

