    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    await gateway.connect();
    addTearDown(gateway.dispose);

    await tester.pumpWidget(
      _testApp(
        boardGateway: gateway,
        initialScreen: 'BoardSettings',
      ),
    );
    await tester.pumpAndSettle();

    final label = find.text('Piece position LEDs');
    await tester.scrollUntilVisible(
      label,
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();

    gateway.writes.clear();
    final tile = find.ancestor(
      of: label,
      matching: find.byType(Tooltip),
    );
    await tester.tap(
      find.descendant(
        of: tile,
        matching: find.byType(Switch),
      ),
    );
    await tester.pumpAndSettle();

    expect(
      gateway.writes.any(
        (command) => listEquals(command, ChessnutMoveLedCodec.offCommand()),
      ),
      isTrue,
    );
    expect(
      gateway.writes.any(
        (command) => listEquals(command, ChessnutMoveBoardCodec.stopCommand()),
      ),
      isFalse,
    );
  });

