  testWidgets('Phone login sends SMS code and signs in with code', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/authOptions') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'country': 'CN',
              'preferred_login_method': 'phone',
              'methods': ['phone', 'email_password'],
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/sendPhoneLoginCode') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'phone': '+8613812345678', 'expires_in': 300},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/loginWithPhoneCode') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await tester.pumpAndSettle();

    await tester.enterText(
      find.widgetWithText(TextFormField, 'Phone number'),
      '13812345678',
    );
    await tester.tap(find.text('Send code'));
    await tester.pumpAndSettle();
    expect(find.text('60s'), findsOneWidget);
    final sendCodeButton = tester.widget<TextButton>(
      find.widgetWithText(TextButton, '60s'),
    );
    expect(sendCodeButton.onPressed, isNull);
    await tester.tap(find.widgetWithText(TextButton, '60s'));
    await tester.pump();
    expect(
      requests.where(
        (request) => request.url.path == '/api/v3/sendPhoneLoginCode',
      ),
      hasLength(1),
    );
    await tester.pump(const Duration(seconds: 60));
    final restoredSendCodeButton = tester.widget<TextButton>(
      find.widgetWithText(TextButton, 'Send code'),
    );
    expect(restoredSendCodeButton.onPressed, isNotNull);
    await tester.enterText(
      find.widgetWithText(TextFormField, 'SMS code'),
      '123456',
    );
    await _agreeToTerms(tester);
    await tester.tap(find.text('Sign in / register'));
    await tester.pumpAndSettle();

    final sendRequest = requests.singleWhere(
      (request) => request.url.path == '/api/v3/sendPhoneLoginCode',
    );
    expect(sendRequest.bodyFields['phone'], '13812345678');
    final loginRequest = requests.singleWhere(
      (request) => request.url.path == '/api/v3/loginWithPhoneCode',
    );
    expect(loginRequest.bodyFields['phone'], '13812345678');
    expect(loginRequest.bodyFields['code'], '123456');
    expect(find.text('Pair your physical board'), findsOneWidget);
  });

