  testWidgets('Login and signup inputs keep focus in EVO2 landscape', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(1920, 720);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    addTearDown(tester.view.resetViewInsets);

    final messages = <MethodCall>[];
    tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
      SystemChannels.platform,
      (call) async {
        messages.add(call);
        return null;
      },
    );
    addTearDown(() {
      tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
        SystemChannels.platform,
        null,
      );
    });

    const evo2Profile = _FixedDevicePerformanceService(
      DevicePerformanceProfile(
        platform: 'android',
        model: 'Chessnut EVO2',
        manufacturer: 'Chessnut',
        sdkInt: 35,
        isLowRamDevice: false,
        memoryClassMb: 384,
        largeMemoryClassMb: 512,
        totalRamMb: 4096,
        cpuCores: 8,
        isChessnutEvo2: true,
      ),
    );
    await tester.pumpWidget(
      _testApp(devicePerformanceService: evo2Profile),
    );
    await tester.pump(const Duration(seconds: 3));
    final input = find.descendant(
      of: find.byKey(const ValueKey('login-account-field')),
      matching: find.byType(TextFormField),
    );
    await tester.ensureVisible(input);
    await tester.showKeyboard(input);
    await tester.pump();
    expect(tester.testTextInput.isVisible, isTrue);
    expect(hasFocusedTextInput(), isTrue);
    final loginEditableBefore = tester.widget<EditableText>(
      find.descendant(of: input, matching: find.byType(EditableText)),
    );
    final loginEditableState = tester.state<EditableTextState>(
      find.descendant(of: input, matching: find.byType(EditableText)),
    );
    final loginFocusNode = loginEditableBefore.focusNode;
    messages.clear();

    tester.view.viewInsets = const FakeViewPadding(bottom: 360);
    await tester.pumpAndSettle();

    final loginEditableAfter = tester.widget<EditableText>(
      find.descendant(of: input, matching: find.byType(EditableText)),
    );
    expect(
      tester.state<EditableTextState>(
        find.descendant(of: input, matching: find.byType(EditableText)),
      ),
      same(loginEditableState),
    );
    expect(loginEditableAfter.focusNode, same(loginFocusNode));
    expect(FocusManager.instance.primaryFocus, same(loginFocusNode));
    expect(hasFocusedTextInput(), isTrue);
    expect(
      tester.testTextInput.isVisible,
      isTrue,
      reason: tester.testTextInput.log.toString(),
    );
    expect(find.text('Sign in to Chessnut'), findsOneWidget);
    expect(
      tester
          .widget<Scaffold>(find.byType(Scaffold).first)
          .resizeToAvoidBottomInset,
      isFalse,
    );
    expect(
      messages.where(
        (call) => call.method == 'SystemChrome.setEnabledSystemUIMode',
      ),
      isEmpty,
    );

    tester.testTextInput.hide();
    tester.view.viewInsets = const FakeViewPadding();
    FocusManager.instance.primaryFocus?.unfocus();
    await tester.pumpAndSettle();
    await tester.tap(find.text('Create'));
    await tester.pumpAndSettle();

    final signupInput = find.descendant(
      of: find.byKey(const ValueKey('signup-username-field')),
      matching: find.byType(TextFormField),
    );
    await tester.ensureVisible(signupInput);
    await tester.showKeyboard(signupInput);
    await tester.pump();
    final signupEditableBefore = tester.widget<EditableText>(
      find.descendant(of: signupInput, matching: find.byType(EditableText)),
    );
    final signupEditableState = tester.state<EditableTextState>(
      find.descendant(of: signupInput, matching: find.byType(EditableText)),
    );
    final signupFocusNode = signupEditableBefore.focusNode;
    tester.view.viewInsets = const FakeViewPadding(bottom: 360);
    await tester.pumpAndSettle();

    final signupEditableAfter = tester.widget<EditableText>(
      find.descendant(of: signupInput, matching: find.byType(EditableText)),
    );
    expect(
      tester.state<EditableTextState>(
        find.descendant(of: signupInput, matching: find.byType(EditableText)),
      ),
      same(signupEditableState),
    );
    expect(signupEditableAfter.focusNode, same(signupFocusNode));
    expect(FocusManager.instance.primaryFocus, same(signupFocusNode));
    expect(tester.testTextInput.isVisible, isTrue);
    expect(hasFocusedTextInput(), isTrue);
    expect(find.text('Create your Chessnut ID'), findsOneWidget);
  });

