    var recordTotal = 37;
    final pgnListPages = <String>[];
    var sourceCountRequests = 0;
    final searchPages = <String>[];
    List<Map<String, Object?>> pgnRecords() {
      return [
        for (var index = 0; index < recordTotal; index++)
          {
            'id': 300 + index,
            'pgn': '[White "Fresh White $index"]\n'
                '[Black "Fresh Black $index"]\n'
                '[Result "1-0"]\n\n'
                '1. e4 e5 1-0',
            'white_name': 'Fresh White $index',
            'black_name': 'Fresh Black $index',
            'play_mode': 'bot',
            'win_id': 1,
            'game_status': 2,
            'game_step': 2,
          },
      ];
    }

    final client = MockClient((request) async {
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        final page = int.tryParse(request.bodyFields['page'] ?? '') ?? 1;
        final count = int.tryParse(request.bodyFields['count'] ?? '') ?? 10;
        pgnListPages.add('$page:$count');
        final records = pgnRecords();
        final start = math.min(records.length, (page - 1) * count);
        final end = math.min(records.length, start + count);
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': math.max(1, (recordTotal / count).ceil()),
              'total': recordTotal,
              'pgnList': records.sublist(start, end),
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/gameRecords/sourceCounts') {
        sourceCountRequests += 1;
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'all': recordTotal,
              'local': recordTotal,
              'lichess': 0,
              'chess_com': 0,
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/gameRecords/search') {
        final page = request.bodyFields['page'] ?? '1';
        searchPages.add(page);
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 1,
              'total': 1,
              'records': [
                {
                  'id': 401,
                  'pgn': '[White "Bot White"]\n'
                      '[Black "Bot Black"]\n\n'
                      '1. e4 e5 1-0',
                  'white_name': 'Bot White',
                  'black_name': 'Bot Black',
                  'play_mode': 'bot',
                  'win_id': 1,
                  'game_status': 2,
                  'game_step': 2,
                },
              ],
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(_testApp(httpClient: client));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _openGameRecordsFromHome(tester);
    await tester.pumpAndSettle();

    expect(find.byTooltip('All 37'), findsOneWidget);
    expect(find.byTooltip('Chessnut 37'), findsOneWidget);
    final initialPageOneLoads =
        pgnListPages.where((page) => page == '1:10').length;
    final initialSourceCountLoads = sourceCountRequests;
    expect(initialPageOneLoads, greaterThanOrEqualTo(1));
    expect(initialSourceCountLoads, greaterThanOrEqualTo(1));
    expect(pgnListPages, isNot(contains('1:200')));
    expect(searchPages, isEmpty);

    recordTotal = 38;
    await tester.tap(find.byIcon(Icons.arrow_back_rounded).first);
    await tester.pumpAndSettle();
    await _openGameRecordsFromHome(tester);
    await tester.pumpAndSettle();

    expect(find.byTooltip('All 37'), findsOneWidget);
    expect(find.byTooltip('Chessnut 37'), findsOneWidget);
    expect(
      pgnListPages.where((page) => page == '1:10').length,
      initialPageOneLoads,
    );
    expect(
      sourceCountRequests,
      initialSourceCountLoads,
    );
    expect(pgnListPages, isNot(contains('1:200')));
    expect(searchPages, isEmpty);
  });

