  testWidgets('Signed-in Game records can delete a backend record', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final requests = <http.Request>[];
    var deleted = false;
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 1,
              'pgnList': deleted
                  ? []
                  : [
                      {
                        'id': 99,
                        's_id': 'share-abc',
                        'pgn': 'https://api.chessnutech.com/pgn/99.pgn',
                        'white_name': 'Alice',
                        'black_name': 'Bob',
                        'play_time': 1715900000,
                        'play_mode': 'bot',
                        'win_id': 1,
                        'game_status': 2,
                        'game_step': 12,
                      },
                    ],
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/delPgn') {
        deleted = true;
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() == 'https://api.chessnutech.com/pgn/99.pgn') {
        return http.Response(
          '[Event "Bot"]\n'
          '[White "Alice"]\n'
          '[Black "Bob"]\n'
          '[Result "1-0"]\n'
          '[TimeControl "10+5"]\n\n'
          '1. e4 e5 1-0',
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        networkLatencyProbe: const _FixedLatencyProbe(120),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _openGameRecordsFromHome(tester);

    expect(find.text('White: Alice / Black: Bob'), findsOneWidget);
    expect(find.text('Bot / Time: 10+5'), findsOneWidget);
    expect(find.text('Result: Alice wins'), findsOneWidget);
    await tester.tap(find.byKey(const ValueKey('game-record-select-mode')));
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('game-record-select-pgn:99')));
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('game-record-batch-delete')));
    await tester.pumpAndSettle();
    await tester.tap(
      find.byKey(const ValueKey('delete-records-dialog-confirm')),
    );
    await tester.pumpAndSettle();

    final deleteRequest = requests.firstWhere(
      (request) => request.url.path == '/api/delPgn',
    );
    expect(deleteRequest.bodyFields['pgn_id'], '99');
    expect(deleteRequest.bodyFields['user_id'], '7');
    expect(
      deleteRequest.bodyFields['token'],
      '12345678901234567890123456789012',
    );
    expect(find.text('White: Alice / Black: Bob'), findsNothing);
    expect(find.text('Game record deleted.'), findsOneWidget);
  });

