  testWidgets('Game records keep continue below the record details on iOS', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.iOS;
    try {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(top: 47, bottom: 34);
      tester.view.viewPadding = const FakeViewPadding(top: 47, bottom: 34);
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      addTearDown(tester.view.resetPadding);
      addTearDown(tester.view.resetViewPadding);

      const pgn = '''
[Event "Bot game room"]
[Site "Chessnut App"]
[White "Chessnut Player With A Very Long Display Name"]
[Black "Maia 1500"]
[Result "*"]
[TimeControl "10+5"]

1. e4 e5 *
''';
      var continued = false;

      await tester.pumpWidget(
        _screenTestApp(
          GameRecordScreen(
            signedIn: true,
            currentSession: _signedInKnightSession,
            records: const [
              GameRecord(
                pgnId: 558,
                result: '*',
                title:
                    'Chessnut Player With A Very Long Display Name vs Maia 1500',
                subtitle: 'Bot / 2 moves',
                pgn: pgn,
                playMode: 'bot',
                gameStatus: 1,
                gameStep: 2,
                winId: 0,
                whiteName: 'Chessnut Player With A Very Long Display Name',
                blackName: 'Maia 1500',
              ),
            ],
            onNavigate: (_) {},
            onAnalyzeRecord: (_) {},
            onContinueRecord: (_) => continued = true,
          ),
        ),
      );
      await tester.pumpAndSettle();

      final summaryFinder = find.text(
        'White: Chessnut Player With A Very Long Display Name / Black: Maia 1500',
      );
      final continueFinder = find.byKey(const ValueKey('game-record-continue'));
      expect(summaryFinder, findsOneWidget);
      expect(continueFinder, findsOneWidget);

      final summaryRect = tester.getRect(summaryFinder);
      final continueRect = tester.getRect(continueFinder);
      final boardRect = tester.getRect(find.byType(ChessBoard).first);
      final moreRect = tester.getRect(
        find.byKey(const ValueKey('game-record-more-pgn:558')),
      );

      expect(
        continueRect.top,
        greaterThan(boardRect.bottom),
        reason: 'Continue should use its own row below the record details.',
      );
      expect(
        summaryRect.right,
        lessThanOrEqualTo(moreRect.left),
        reason: 'The details row should only share space with the more button.',
      );
      await tester.tap(continueFinder);
      await tester.pumpAndSettle();
      expect(continued, isTrue);
    } finally {
      debugDefaultTargetPlatformOverride = null;
