  testWidgets('Interrupted bot game appears in Game records for continue', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    addTearDown(gateway.dispose);

    String savedPgn = '';
    final delayedRefresh = Completer<void>();
    var pgnListRequests = 0;
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/uploadPgn') {
        savedPgn = request.bodyFields['pgn'] ?? '';
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'pgn_id': 555, 's_id': 'resume-draft'},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        pgnListRequests += 1;
        final useSavedPgn = pgnListRequests > 1;
        if (pgnListRequests == 1) {
          await delayedRefresh.future;
        }
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 1,
              'pgnList': !useSavedPgn || savedPgn.isEmpty
                  ? []
                  : [
                      {
                        'id': 555,
                        's_id': 'resume-draft',
                        'pgn': 'https://api.chessnutech.com/pgn/resume.pgn',
                        'white_name': 'Chessnut Player',
                        'black_name': 'Maia 1500',
                        'play_time': 1715900000,
                        'play_mode': 'bot',
                        'win_id': 0,
                        'game_status': 1,
                        'game_step': 2,
                      },
                    ],
            },
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/resume.pgn') {
        return http.Response(savedPgn, 200);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        boardGateway: gateway,
        appPreferencesStore: MemoryAppPreferencesStore(),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await gateway.connect();
    await tester.pumpAndSettle();

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Bot game'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('White'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('White'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Start bot game'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Start bot game'));
    await tester.pumpAndSettle();

    const e4Fen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
    gateway.addBoardFen(e4Fen);
    gateway.addBoardFen(e4Fen);
    await tester.pump(const Duration(milliseconds: 850));
    await tester.pumpAndSettle();

    await tester.tap(find.byIcon(Icons.arrow_back_rounded).first);
    await tester.pumpAndSettle();
    expect(
      find.text(
        'Leave for now and continue later from Game Record, or resign to end the game as a loss.',
      ),
      findsOneWidget,
    );
    await tester.tap(find.text('Leave for now'));
    await tester.pump(const Duration(milliseconds: 50));
    expect(find.text('Continue bot game'), findsNothing);
    delayedRefresh.complete();
    await tester.pumpAndSettle();

    expect(savedPgn, contains('[Result "*"]'));
    expect(savedPgn, contains('1. e4'));

    await _pumpUntilFound(
      tester,
      find.text('Continue bot game'),
      timeout: const Duration(seconds: 5),
    );
    expect(find.text('Continue bot game'), findsOneWidget);
    await _openGameRecordsFromHome(tester);

    expect(
      find.text('White: Chessnut Player / Black: Maia 1500'),
      findsOneWidget,
    );
    expect(find.text('Continue'), findsOneWidget);
    expect(
      requests.where((request) => request.url.path == '/api/getPgnList'),
      isNotEmpty,
    );
    expect(
      requests.where((request) => request.url.path == '/api/getPgnList').length,
      greaterThanOrEqualTo(2),
    );
  });

