      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' && request.url.path == '/api/getPgnList') {
        final page = request.bodyFields['page'] ?? '1';
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 2,
              'pgnList': page == '2'
                  ? [
                      {
                        'id': 2202,
                        's_id': 'board-storage-cloud',
                        'pgn': parsedBoardGame.pgn,
                        'white_name': parsedBoardGame.whiteName,
                        'black_name': parsedBoardGame.blackName,
                        'play_time': 1782000000,
                        'play_mode': 'otb',
                        'win_id': 0,
                        'game_status': 2,
                        'game_step': parsedBoardGame.gameStep,
                      },
                    ]
                  : [],
            },
          }),
          200,
        );
      }
      return http.Response.fromStream(await fallbackClient.send(request));
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        boardGateway: gateway,
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await tester.tap(find.text('Pair your physical board'));
    await tester.pumpAndSettle();
    expect(find.text('BOARD READY'), findsOneWidget);

    await tester.ensureVisible(
      find.byKey(const ValueKey('home-board-settings-button')),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('home-board-settings-button')));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Saved games'),
      160,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Saved games'));
    await tester.pumpAndSettle();

    expect(find.text('Import saved board games'), findsOneWidget);
    expect(find.text('Already imported'), findsOneWidget);
    expect(find.text('Ready to import'), findsNothing);
    expect(
      requests
          .where((request) =>
              request.url.path == '/api/getPgnList' &&
              request.bodyFields['page'] == '2')
          .length,
      greaterThanOrEqualTo(1),
    );
  });

