      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/wallet/claimDaily') {
        final points = int.tryParse(request.bodyFields['points'] ?? '') ?? 100;
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'balance': 1240 + points,
              'points_added': points,
              'claimed_today': true,
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(_testApp(httpClient: client));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    expect(
      find.byKey(const ValueKey('home-daily-tasks-entry')),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('daily-task-check-in')), findsNothing);
    await tester.ensureVisible(
      find.byKey(const ValueKey('home-daily-tasks-entry')),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('home-daily-tasks-entry')));
    await tester.pumpAndSettle();
    expect(find.text('Daily Tasks'), findsOneWidget);
    await tester.tap(find.byKey(const ValueKey('daily-task-check-in')));
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 220));

    final claimRequests = requests
        .where((request) => request.url.path == '/api/wallet/claimDaily')
        .toList();
    expect(claimRequests, hasLength(1));
    expect(claimRequests.single.bodyFields['user_id'], '7');
    expect(
      claimRequests.single.bodyFields['token'],
      '12345678901234567890123456789012',
    );
    expect(claimRequests.single.bodyFields['points'], '100');
    expect(find.text('+100'), findsWidgets);
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('daily-task-check-in')),
        matching: find.text('Claimed'),
      ),
      findsOneWidget,
    );

    await tester.pumpAndSettle(const Duration(seconds: 2));
    await tester.scrollUntilVisible(
      find.byKey(const ValueKey('daily-task-check-in')),
      220,
      scrollable: find.byType(Scrollable).first,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('daily-task-check-in')));
    await tester.pumpAndSettle();
    expect(
      requests.where((request) => request.url.path == '/api/wallet/claimDaily'),
      hasLength(1),
    );
  });

