    await tester.tap(find.text('Bot game'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('White'),
      220,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('White'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Start bot game'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Start bot game'));
    await tester.pumpAndSettle();

    expect(gateway.state, PhysicalBoardConnectionState.connected);
    expect(boardBackgroundService.keepAliveRequests.last.enabled, isTrue);

    gateway.writes.clear();
    tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.paused);
    await tester.pump();

    expect(gateway.state, PhysicalBoardConnectionState.connected);
    expect(boardBackgroundService.keepAliveRequests.last.enabled, isTrue);
    expect(
      gateway.writes.any(
        (command) => listEquals(
