    final gameGateway = tester
        .widget<GameRoomScreen>(find.byType(GameRoomScreen))
        .boardGateway!;
    final receivedFens = <String>[];
    final fenSub = gameGateway.boardFenStream.listen(receivedFens.add);
    addTearDown(fenSub.cancel);
    gateway.addBoardFen('8/8/8/8/8/8/8/K7');
    await tester.pump();
    expect(receivedFens, isEmpty);

    await gameGateway.setGeneralLedSquares({'e4'});
    expect(
      gateway.writes.any(
        (command) => listEquals(
          command,
          ChessnutLedCodec.ledCommandFromSquares({'e4'}),
        ),
      ),
      isFalse,
    );
    expect(
      gateway.writes.any(
        (command) => listEquals(
          command,
          ChessnutLedCodec.ledCommand(List<int>.filled(64, 0)),
        ),
      ),
      isTrue,
    );

    tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.resumed);
    await tester.pump();
    gateway.addBoardFen('8/8/8/8/8/8/K7/8');
    await tester.pump();
    expect(receivedFens, ['8/8/8/8/8/8/K7/8']);
    await tester.pumpWidget(const SizedBox.shrink());
    await tester.pumpAndSettle();
  });

