      AppSettingKeys.keepBoardConnectedInBackground,
      false,
    );
    try {
      await tester.pumpWidget(
        _testApp(
          appPreferencesStore: preferencesStore,
          initialScreen: 'Settings',
        ),
      );
      await _pumpUntilCondition(
        tester,
        () async =>
            AppSharedPreferences.instance.getBool(
              AppSettingKeys.keepBoardConnectedInBackground,
            ) ==
            true,
        reason: 'macOS screen-off play preference should be enabled',
      );

      expect(find.text('Keep playing while screen is off'), findsNothing);
      expect(
        AppSharedPreferences.instance.getBool(
          AppSettingKeys.keepBoardConnectedInBackground,
        ),
        isTrue,
      );
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

