  testWidgets('Board editor shows a full board on chess clock landscape', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(1024, 480);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(
      _screenTestApp(
        BoardEditorScreen(
          onNavigate: (_) {},
        ),
      ),
    );
    await tester.pumpAndSettle();

    final boardRect = tester.getRect(find.byType(InteractiveChessBoard));
    final midpoint = tester.view.physicalSize.width / 2;

    expect(boardRect.center.dx, lessThan(midpoint));
    expect((boardRect.width - boardRect.height).abs(), lessThanOrEqualTo(2));
    expect(boardRect.width, greaterThanOrEqualTo(400));
    expect(
        boardRect.bottom, lessThanOrEqualTo(tester.view.physicalSize.height));
    expect(find.text('Physical board sync is live'), findsNothing);
    expect(
      find.byKey(const ValueKey('board-editor-board-status-button')),
      findsOneWidget,
    );
    expect(
      find.byKey(const ValueKey('board-editor-vision-button')),
      findsNothing,
    );
    expect(find.byTooltip('Import from image'), findsNothing);
    expect(find.text('Chessnut Vision'), findsNothing);
    expect(find.text('Import a board position from a photo.'), findsNothing);

    await tester
        .tap(find.byKey(const ValueKey('board-editor-board-status-button')));
    await tester.pumpAndSettle();
    expect(find.text('Board sync'), findsOneWidget);
    expect(find.text('Connect a physical board or switch to FEN to board.'),
        findsOneWidget);
    await tester.tap(find.text('Done'));
    await tester.pumpAndSettle();

    final controlsRect = tester.getRect(
      find.byKey(const ValueKey('board-editor-controls-pane')),
    );
    final boardToAppRect = tester.getRect(find.text('Board to app'));
    final fenToBoardRect = tester.getRect(find.text('FEN to board'));
    expect(boardToAppRect.left, greaterThanOrEqualTo(controlsRect.left));
    expect(fenToBoardRect.left, greaterThanOrEqualTo(controlsRect.left));
    expect(boardToAppRect.center.dx, greaterThan(boardRect.right));
    final sidePanelRect = tester.getRect(
      find
          .ancestor(
            of: find.text('Side to move'),
            matching: find.byType(GlassPanel),
          )
          .first,
    );
    expect(sidePanelRect.height, lessThanOrEqualTo(64));

    final castlingPanelFinder = find
        .ancestor(
          of: find.text('Castling rights'),
          matching: find.byType(GlassPanel),
        )
        .first;
    final castlingPanelRect = tester.getRect(castlingPanelFinder);
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('White')),
      findsOneWidget,
    );
    final whiteLabelRect = tester.getRect(
      find.descendant(of: castlingPanelFinder, matching: find.text('White')),
    );
    expect(whiteLabelRect.left, greaterThanOrEqualTo(castlingPanelRect.left));
    expect(whiteLabelRect.right, lessThanOrEqualTo(castlingPanelRect.right));
    expect(
      tester
          .getSize(
            find.descendant(
                of: castlingPanelFinder, matching: find.text('White')),
          )
          .width,
      greaterThanOrEqualTo(42),
    );
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('Black')),
      findsOneWidget,
    );
    final blackLabelRect = tester.getRect(
      find.descendant(of: castlingPanelFinder, matching: find.text('Black')),
    );
    expect(blackLabelRect.left, greaterThanOrEqualTo(castlingPanelRect.left));
    expect(blackLabelRect.right, lessThanOrEqualTo(castlingPanelRect.right));
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('O-O')),
      findsNWidgets(2),
    );
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('O-O-O')),
      findsNWidgets(2),
    );
    expect(find.text('White O-O'), findsNothing);

    await tester.tap(find.text('FEN to board'));
    await tester.pumpAndSettle();
    expect(
      find.byKey(const ValueKey('board-editor-vision-button')),
      findsNothing,
    );
    expect(find.byTooltip('Import from image'), findsNothing);
    expect(find.text('Chessnut Vision'), findsOneWidget);
    expect(find.text('Import a board position from a photo.'), findsOneWidget);
    expect(find.text('Choose image'), findsOneWidget);
  });

