    expect(find.byKey(const ValueKey('bot-board-editor-landscape-layout')),
        findsOneWidget);

    final sheetRect = tester.getRect(
      find.byKey(const ValueKey('bot-board-editor-sheet-surface')),
    );
    expect(sheetRect.width, greaterThanOrEqualTo(1100));

    final boardRect = tester.getRect(find.byType(InteractiveChessBoard).first);
    final controlsRect = tester.getRect(
      find.byKey(const ValueKey('bot-board-editor-controls-pane')),
    );
    expect(boardRect.right, lessThan(controlsRect.left));
    expect(boardRect.width, greaterThanOrEqualTo(320));
    expect(find.text('Connect a physical board or switch to FEN to board.'),
        findsNothing);
    expect(
      find.byKey(const ValueKey('bot-board-editor-board-status-button')),
      findsOneWidget,
    );
    expect(
      find.byKey(const ValueKey('bot-board-editor-vision-button')),
      findsNothing,
    );
    await tester.tap(
      find.byKey(const ValueKey('bot-board-editor-board-status-button')),
    );
    await tester.pumpAndSettle();
    expect(find.text('Board sync'), findsOneWidget);
    expect(find.text('Connect a physical board or switch to FEN to board.'),
        findsOneWidget);
    await tester.tap(find.text('Done'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('FEN to board'));
    await tester.pumpAndSettle();
    expect(
      find.byKey(const ValueKey('bot-board-editor-vision-button')),
      findsNothing,
    );
    expect(find.text('Chessnut Vision'), findsOneWidget);
    expect(find.text('Import a board position from a photo.'), findsOneWidget);
    expect(find.text('Choose image'), findsOneWidget);
    final cancelRect =
        tester.getRect(find.widgetWithText(OutlinedButton, 'Cancel'));
    final useRect =
        tester.getRect(find.widgetWithText(FilledButton, 'Use this position'));
    expect((cancelRect.height - useRect.height).abs(), lessThanOrEqualTo(1));

    await tester.tap(find.text('Board to app'));
    await tester.pumpAndSettle();

    final boardToAppRect = tester.getRect(find.text('Board to app'));
    final fenToBoardRect = tester.getRect(find.text('FEN to board'));
    expect(boardToAppRect.left, greaterThanOrEqualTo(controlsRect.left));
    expect(fenToBoardRect.left, greaterThanOrEqualTo(controlsRect.left));
    final sidePanelRect = tester.getRect(
      find
          .ancestor(
            of: find.text('Side to move'),
            matching: find.byType(GlassPanel),
          )
          .first,
    );
    expect(sidePanelRect.height, lessThanOrEqualTo(62));
    expect(find.text('Side to move'), findsOneWidget);
    expect(find.text('Castling rights'), findsOneWidget);
    expect(find.text('White O-O'), findsNothing);
    expect(find.text('White O-O-O'), findsNothing);
    expect(find.text('Black O-O'), findsNothing);
    expect(find.text('Black O-O-O'), findsNothing);
    final castlingPanel = tester.getRect(
      find
          .ancestor(
            of: find.text('Castling rights'),
            matching: find.byType(GlassPanel),
          )
          .first,
    );
    final castlingPanelFinder = find
        .ancestor(
          of: find.text('Castling rights'),
          matching: find.byType(GlassPanel),
        )
        .first;
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('White')),
      findsOneWidget,
    );
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('Black')),
      findsOneWidget,
    );
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('O-O')),
      findsNWidgets(2),
    );
    expect(
      find.descendant(of: castlingPanelFinder, matching: find.text('O-O-O')),
      findsNWidgets(2),
    );
    for (final button in find
        .descendant(of: castlingPanelFinder, matching: find.text('O-O'))
        .evaluate()) {
      expect(tester.getRect(find.byWidget(button.widget)).right,
          lessThanOrEqualTo(castlingPanel.right));
    }
    for (final button in find
        .descendant(of: castlingPanelFinder, matching: find.text('O-O-O'))
        .evaluate()) {
      final rect = tester.getRect(find.byWidget(button.widget));
      expect(rect.right, lessThanOrEqualTo(castlingPanel.right));
      expect(rect.bottom, lessThanOrEqualTo(castlingPanel.bottom));
    }
    expect(find.text('Use this position'), findsOneWidget);
  });

