  testWidgets('OTB Leave for now creates a Home continue card', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    addTearDown(gateway.dispose);
    final requests = <http.Request>[];
    var uploadedPgn = '''
[Event "OTB Game 5+3"]
[Site "Chessnut App"]
[White "Chessnut Player"]
[Black "Opponent"]
[Result "*"]
[TimeControl "300+3"]

1. e4 *
''';
    var uploaded = false;
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/version') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'version': request.bodyFields['current_version'] ?? '0.1.4',
              'platform':
                  int.tryParse(request.bodyFields['platform'] ?? '') ?? 0,
              'download_url': 'https://www.chessnutech.com',
              'change_log': '',
              'update_available': false,
              'force_update': false,
              'update_method': 'download',
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/uploadPgn') {
        uploaded = true;
        uploadedPgn = request.bodyFields['pgn'] ?? uploadedPgn;
        return _uploadPgnResponse(pgnId: 888, shareId: 'otb-draft');
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 1,
              'pgnList': uploaded
                  ? [
                      {
                        'id': 888,
                        's_id': 'otb-draft',
                        'pgn': 'https://api.chessnutech.com/pgn/otb-draft.pgn',
                        'white_name': 'Chessnut Player',
                        'black_name': 'Opponent',
                        'play_time': 1715900000,
                        'play_mode': 'otb',
                        'win_id': 0,
                        'game_status': 1,
                        'game_step': 1,
                      },
                    ]
                  : [],
            },
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/otb-draft.pgn') {
        return http.Response(uploadedPgn, 200);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        boardGateway: gateway,
        appPreferencesStore: MemoryAppPreferencesStore(),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await gateway.connect();
    await tester.pumpAndSettle();

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('OTB Game'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('5+3'));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Record Game'));
    await tester.pumpAndSettle();

    const e4Fen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
    gateway.addBoardFen(e4Fen);
    gateway.addBoardFen(e4Fen);
    await tester.pump(const Duration(milliseconds: 850));
    await tester.pumpAndSettle();

    await tester.tap(find.byIcon(Icons.arrow_back_rounded).first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Leave for now'));
    await tester.pumpAndSettle();

    expect(find.text('Chessnut'), findsOneWidget);
    await _pumpUntilFound(
      tester,
      find.text('Continue OTB game'),
      timeout: const Duration(seconds: 5),
    );
    expect(find.text('OTB setup'), findsNothing);
    expect(find.text('Continue OTB game'), findsOneWidget);
    expect(
      requests.where((request) => request.url.path == '/api/uploadPgn'),
      isNotEmpty,
    );

    await tester.tap(find.byKey(const ValueKey('home-continue-action-otb')));
    await tester.pumpAndSettle();

    expect(find.text('OTB Game 5+3'), findsOneWidget);
  });

