    final botConfig = const BotGameConfig.defaultConfig().copyWith(
      playerSide: BotPlayerSide.black,
    );

    GameRoomScreen room(BoardSettingsState settings) {
      return GameRoomScreen(
        onNavigate: (_) {},
        mode: GameLaunchMode.bot,
        boardSettings: settings,
        botConfig: botConfig,
        botEngine: engine,
      );
    }

    await tester.pumpWidget(
      _screenTestApp(
        room(const BoardSettingsState(allowFlip: false, autoFlip: false)),
      ),
    );
    await tester.pumpAndSettle();

    Offset a1() => tester.getTopLeft(find.byKey(const ValueKey('square-a1')));
    Offset h8() => tester.getTopLeft(find.byKey(const ValueKey('square-h8')));

    expect(a1().dy, greaterThan(h8().dy));
    final flipButton = find.byIcon(Icons.swap_vert_rounded);
    expect(flipButton, findsOneWidget);
    await tester.tap(flipButton, warnIfMissed: false);
    await tester.pumpAndSettle();
    expect(a1().dy, greaterThan(h8().dy));

    await tester.pumpWidget(
      _screenTestApp(
        room(const BoardSettingsState(autoFlip: false)),
      ),
    );
    await tester.pumpAndSettle();
    expect(a1().dy, lessThan(h8().dy));
    await tester.tap(flipButton);
    await tester.pumpAndSettle();
    expect(a1().dy, greaterThan(h8().dy));
  });

