  testWidgets(
    'Game room ignores opponent move audio captured by Move voice recognition',
    (WidgetTester tester) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.android;
      addTearDown(() => debugDefaultTargetPlatformOverride = null);
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = MemoryPhysicalBoardGateway();
      await gateway.connect();
      addTearDown(gateway.dispose);
      final voiceService = _FakeVoiceMoveRecognitionService();
      addTearDown(voiceService.dispose);
      final soundService = _BlockingMoveSoundService();
      addTearDown(() {
        if (!soundService.releaseMove.isCompleted) {
          soundService.releaseMove.complete();
        }
      });

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              fenDelayMs: 0,
              clockSwitchAutomation: ClockSwitchAutomationMode.off,
            ),
            botEngine: const _ScriptedBotEngineAdapter(['e7e5']),
            positionAnalyzer: const _NoopPositionAnalyzer(),
            appSoundService: soundService,
            voiceMoveRecognitionService: voiceService,
          ),
        ),
      );
      await tester.pumpAndSettle();

      await tester
          .tap(find.byKey(const ValueKey('game-room-voice-moves-toggle')));
      await tester.pumpAndSettle();
      voiceService.addResult('e4');
      await tester.pump();
      await tester.runAsync(() => soundService.moveStarted.future);

      voiceService.addResult('e7 e5');
      await tester.pump();

      expect(find.textContaining('Voice move e7e5 is not legal here.'),
          findsNothing);
      expect(find.text('e4'), findsOneWidget);
      expect(find.text('e5'), findsOneWidget);

      soundService.releaseMove.complete();
      await tester.pump(const Duration(milliseconds: 801));
      voiceService.addResult('knight f3');
      await tester.pumpAndSettle();

      expect(find.text('Nf3'), findsOneWidget);
      debugDefaultTargetPlatformOverride = null;
    },
  );

