      await gateway.connect();
      addTearDown(gateway.dispose);

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              fenDelayMs: 0,
              moveRestoreDelayMs: 250,
            ),
            positionAnalyzer: const _NoopPositionAnalyzer(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      final startSetMoveCommand =
          ChessnutMoveBoardCodec.setBoardCommand(standardStartFen);
      int startSetMoveCount() => gateway.writes
          .where((command) => listEquals(command, startSetMoveCommand))
          .length;

      expect(startSetMoveCount(), 0);

      await tester.pump(const Duration(milliseconds: 300));
      expect(startSetMoveCount(), 0);

      const emptyBoardFen = '8/8/8/8/8/8/8/8';
      gateway.addBoardFen(emptyBoardFen);
      gateway.addBoardFen(emptyBoardFen);
