  testWidgets(
    'Pending physical Move board move cancels old position restore',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = MemoryPhysicalBoardGateway();
      final clockSwitchService = _RecordingClockSwitchService();
      await gateway.connect();
      addTearDown(gateway.dispose);
      addTearDown(clockSwitchService.dispose);

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              fenDelayMs: 800,
              moveRestoreDelayMs: 250,
            ),
            clockSwitchService: _RecordingClockSwitchService(),
            positionAnalyzer: const _NoopPositionAnalyzer(),
          ),
        ),
      );
      await tester.pumpAndSettle();

      const emptyBoardFen = '8/8/8/8/8/8/8/8';
      gateway.addBoardFen(emptyBoardFen);
      gateway.addBoardFen(emptyBoardFen);
      await tester.pump(const Duration(milliseconds: 250));

      final startSetMoveCommand =
          ChessnutMoveBoardCodec.setBoardCommand(standardStartFen);
      final firstRestoreCount = gateway.writes
          .where((command) => listEquals(command, startSetMoveCommand))
          .length;
      expect(firstRestoreCount, 1);
      gateway.writes.clear();

      gateway.addBoardFen(standardStartFen);
      gateway.addBoardFen(standardStartFen);
      await tester.pumpAndSettle();
      gateway.writes.clear();

