  testWidgets(
    'Bot Play again waits for the complete final PGN save before reset',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final requests = <http.Request>[];
      final stalledUpload = Completer<http.Response>();
      final clockSwitchService = _RecordingClockSwitchService();
      addTearDown(clockSwitchService.dispose);
      final client = MockClient((request) async {
        requests.add(request);
        if (request.method == 'POST' && request.url.path == '/api/uploadPgn') {
          return stalledUpload.future;
        }
        if (request.method == 'POST' && request.url.path == '/api/updatePgn') {
          return http.Response(
            jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
            200,
          );
        }
        return http.Response('not found', 404);
      });
      addTearDown(() {
        if (!stalledUpload.isCompleted) {
          stalledUpload.complete(
            _uploadPgnResponse(pgnId: 881, shareId: 'rematch-save'),
          );
        }
      });

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            apiClient: ChessnutApiClient(
              httpClient: client,
              session: _signedInKnightSession,
            ),
            positionAnalyzer: const _NoopPositionAnalyzer(),
            clockSwitchService: clockSwitchService,
            botEngine: const _DelayedBotEngineAdapter.scripted(
              moves: ['e7e5'],
              delay: Duration.zero,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      await tester.tapAt(_boardSquareCenter(tester, 'e2'));
      await tester.pump();
      await tester.tapAt(_boardSquareCenter(tester, 'e4'));
      await tester.pumpAndSettle();
      await _pumpUntilFound(tester, find.text('e5'));
      await _pumpUntilCondition(
        tester,
        () => requests.any((request) => request.url.path == '/api/uploadPgn'),
        timeout: const Duration(seconds: 5),
        reason: 'stalled rematch draft upload',
      );

      await tester.tap(find.byTooltip('More'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Resign'));
      await tester.pumpAndSettle();
      expect(find.text('Black wins by resignation'), findsWidgets);

      await tester.tap(find.text('Play again'));
      await tester.pump();

      expect(
        tester
            .widget<Semantics>(find.byKey(const ValueKey('square-e2')))
            .properties
            .label,
        isNot(contains('wp')),
      );

      stalledUpload.complete(
        _uploadPgnResponse(pgnId: 881, shareId: 'rematch-save'),
      );
      await _pumpUntilCondition(
        tester,
        () => requests.any(
          (request) =>
              request.url.path == '/api/updatePgn' &&
              request.bodyFields['game_status'] == '2',
        ),
        timeout: const Duration(seconds: 5),
        reason: 'complete rematch final PGN update',
      );
      await tester.pumpAndSettle();

      final finalUpdate = requests.lastWhere(
        (request) =>
            request.url.path == '/api/updatePgn' &&
            request.bodyFields['game_status'] == '2',
      );
      expect(finalUpdate.bodyFields['pgn_id'], '881');
      expect(finalUpdate.bodyFields['game_step'], '2');
      expect(finalUpdate.bodyFields['win_id'], '2');
      expect(finalUpdate.bodyFields['pgn'], contains('[Result "0-1"]'));
      expect(finalUpdate.bodyFields['pgn'], contains('1. e4 e5 0-1'));
      expect(find.text('Black wins by resignation'), findsNothing);
      expect(
        tester
            .widget<Semantics>(find.byKey(const ValueKey('square-e2')))
            .properties
            .label,
        contains('wp'),
      );
    },
  );

