      const e4Fen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
      final moveDiffCommand = ChessnutLedCodec.ledCommandFromSquares({
        'e2',
        'e4',
      });
      final legalTargetsCommand = ChessnutLedCodec.ledCommandFromSquares({
        'e3',
        'e4',
      });
      final clearCommand = ChessnutLedCodec.ledCommand(List<int>.filled(64, 0));
      gateway.addBoardFen(liftedFen);
      await tester.pump(const Duration(milliseconds: 100));
      expect(gateway.writes.last, legalTargetsCommand);

      final writesBeforeMoveFen = gateway.writes.length;
      gateway.addBoardFen(e4Fen);
      await tester.pump(const Duration(milliseconds: 200));
      expect(gateway.writes.last, moveDiffCommand);
      expect(
        gateway.writes
            .skip(writesBeforeMoveFen)
            .any((write) => listEquals(write, legalTargetsCommand)),
        isFalse,
      );
      expect(
        gateway.writes
            .skip(writesBeforeMoveFen)
            .any((write) => listEquals(write, clearCommand)),
        isFalse,
      );
      gateway.addBoardFen(e4Fen);
      await tester.pump(const Duration(milliseconds: 200));
      expect(gateway.writes.last, moveDiffCommand);
      expect(
        gateway.writes
            .skip(writesBeforeMoveFen)
            .any((write) => listEquals(write, legalTargetsCommand)),
        isFalse,
      );
      gateway.addBoardFen(e4Fen);
      await tester.pump(const Duration(milliseconds: 500));
      await tester.pumpAndSettle();

      expect(find.text('e4'), findsOneWidget);
    },
  );

