  testWidgets(
    'Game room lights Chessnut Move bot moves in green',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = MemoryPhysicalBoardGateway();
      await gateway.connect();
      addTearDown(gateway.dispose);

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(fenDelayMs: 0),
            positionAnalyzer: const _NoopPositionAnalyzer(),
            botEngine: const _ScriptedBotEngineAdapter(['e7e5']),
            clockSwitchService: _RecordingClockSwitchService(),
          ),
        ),
      );
      await tester.pumpAndSettle();
      gateway.writes.clear();

      const e4Fen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
      gateway.addBoardFen(e4Fen);
      gateway.addBoardFen(e4Fen);
      await tester.pumpAndSettle();

      final botMoveLedCommand = ChessnutMoveLedCodec.commandFromSquares({
        'e7': ChessnutMoveLedColor.green,
        'e5': ChessnutMoveLedColor.green,
      });
      expect(
        gateway.writes.any((write) => listEquals(write, botMoveLedCommand)),
        isTrue,
      );
      final lastLedCommand = gateway.writes.lastWhere(
        (write) => write.isNotEmpty && write.first == 0x43,
      );
      expect(lastLedCommand, botMoveLedCommand);
      final botMoveRedCommand = ChessnutMoveLedCodec.commandFromSquares({
        'e7': ChessnutMoveLedColor.red,
        'e5': ChessnutMoveLedColor.red,
      });
      expect(
        gateway.writes
            .skipWhile((write) => !listEquals(
                  write,
                  botMoveLedCommand,
                ))
            .any((write) => listEquals(write, botMoveRedCommand)),
        isFalse,
      );
      expect(
        gateway.writes.any((write) =>
            write.length == 35 && write[0] == 0x42 && write[1] == 0x21),
        isTrue,
      );
      const afterBotMoveFen = 'rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR';
      expect(
        gateway.writes.any(
          (write) => listEquals(
            write,
            ChessnutMoveBoardCodec.setBoardCommand(afterBotMoveFen),
          ),
        ),
        isTrue,
      );
    },
  );

