  testWidgets('Game room flip swaps player names and clocks', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(onNavigate: (_) {}, mode: GameLaunchMode.bot),
      ),
    );
    await tester.pumpAndSettle();

    final boardRect = tester.getRect(find.byType(InteractiveChessBoard).first);
    expect(
      tester.getTopLeft(find.text('Maia 1500')).dy,
      lessThan(boardRect.top),
    );
    expect(
      tester.getTopLeft(find.text('Chessnut Player')).dy,
      greaterThan(boardRect.bottom),
    );

    await tester.tap(find.byTooltip('Flip'));
    await tester.pumpAndSettle();

    final flippedBoardRect = tester.getRect(
      find.byType(InteractiveChessBoard).first,
    );
    expect(
      tester.getTopLeft(find.text('Chessnut Player')).dy,
      lessThan(flippedBoardRect.top),
    );
    expect(
      tester.getTopLeft(find.text('Maia 1500')).dy,
      greaterThan(flippedBoardRect.bottom),
    );
  });

