  testWidgets('Game room ends when the active clock flags', (
    WidgetTester tester,
  ) async {
    final navigations = <String>[];
    final soundEvents = <AppSoundEvent>[];
    final gameActiveChanges = <bool>[];
    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: navigations.add,
          mode: GameLaunchMode.otb,
          otbConfig: const OtbGameConfig(timeMinutes: 1, incrementSeconds: 0),
          botConfig: const BotGameConfig.defaultConfig().copyWith(
            startFen:
                'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
          ),
          appSoundService: _RecordingAppSoundService(soundEvents),
          onGameActiveChanged: gameActiveChanges.add,
        ),
      ),
    );
    await tester.pump();

    await tester.pump(const Duration(seconds: 60));
    await tester.pumpAndSettle();

    expect(find.text('Game over'), findsOneWidget);
    expect(find.text('Black wins on time'), findsWidgets);
