  testWidgets('Leaving an active lichess game does not save a draft record', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final navigations = <String>[];
    final requests = <http.Request>[];
    GameRecord? localContinueRecord;
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'state': {'moves': '', 'status': 'started'},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/uploadPgn') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'pgn_id': 777, 's_id': 'live-lichess-share'},
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });
    final apiClient = ChessnutApiClient(
      httpClient: client,
      session: const ChessnutApiSession(
        userId: 7,
        token: '12345678901234567890123456789012',
      ),
    );

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: navigations.add,
          mode: GameLaunchMode.lichess,
          apiClient: apiClient,
          onLichessTemporaryContinueRecord: (record) {
            localContinueRecord = record;
          },
          lichessConfig: const LichessGameConfig(
            gameId: 'lichess-game-1',
            token: 'lichess-token',
            lichessName: 'ChessnutPlayer',
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.tap(find.byIcon(Icons.arrow_back_rounded));
    await tester.pumpAndSettle();

    expect(find.text('Game still in progress'), findsOneWidget);
    expect(
      find.text(
        'Leave for now. The online clock may keep running, and only the completed final game will be saved to Game Records.',
      ),
      findsOneWidget,
    );

    await tester.tap(find.text('Leave for now'));
    await tester.pumpAndSettle();

    expect(
      requests.where((request) => request.url.path == '/api/uploadPgn'),
      isEmpty,
    );
    expect(localContinueRecord, isNotNull);
    expect(localContinueRecord!.canContinueLichessGame, isTrue);
    expect(localContinueRecord!.pgnId, isNull);
    expect(localContinueRecord!.lichessGameId, 'lichess-game-1');
    expect(localContinueRecord!.lichessToken, 'lichess-token');
    expect(localContinueRecord!.pgn, contains('[Result "*"]'));
    expect(
      localContinueRecord!.pgn,
      contains('[LichessGameId "lichess-game-1"]'),
    );
    expect(localContinueRecord!.pgn, contains('[PlayerSide "White"]'));
    expect(navigations, contains('Home'));
  });

