      boardModel: PhysicalBoardModel.air,
    );
    final clockSwitchService = _RecordingClockSwitchService();
    await gateway.connect();
    addTearDown(gateway.dispose);

    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'white': {'id': 'chessnutplayer', 'name': 'ChessnutPlayer'},
            'black': {'id': 'nightbishop', 'name': 'nightbishop'},
            'state': {'moves': '', 'status': 'started'},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/lichess-game-1/move/e2e4') {
        return http.Response('{"ok":true}', 200);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.lichess,
          apiClient: ChessnutApiClient(httpClient: client),
          lichessConfig: const LichessGameConfig(
            gameId: 'lichess-game-1',
            token: 'lichess-token',
            lichessName: 'ChessnutPlayer',
          ),
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(
            fenDelayMs: 0,
            submitMoveOnClockSwitch: true,
            clockSwitchAutomation: ClockSwitchAutomationMode.off,
          ),
          clockSwitchService: clockSwitchService,
        ),
      ),
    );
    await tester.pumpAndSettle();

    const e4Fen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
    gateway.addBoardFen(e4Fen);
    gateway.addBoardFen(e4Fen);
    await tester.pumpAndSettle();

    bool postedMove() => requests.any(
          (request) =>
              request.method == 'POST' &&
              request.url.toString() ==
                  'https://lichess.org/api/board/game/lichess-game-1/move/e2e4',
        );

