    await tester.pumpAndSettle();

    final e5Before = tester.widget<Semantics>(
      find.byKey(const ValueKey('square-e5')),
    );
    expect(e5Before.properties.label, isNot(contains('bp')));

    await tester.pump(const Duration(seconds: 3));
    await tester.pumpAndSettle();

    final e5After = tester.widget<Semantics>(
      find.byKey(const ValueKey('square-e5')),
    );
    expect(e5After.properties.label, contains('bp'));
    expect(streamCalls, greaterThanOrEqualTo(2));
    expect(moveSounds.map((move) => move.uci), ['e7e5']);
    expect(
      requests.any(
        (request) =>
            request.method == 'POST' &&
            request.url.toString() ==
                'https://lichess.org/api/board/game/lichess-game-1/move/e2e4',
      ),
      isTrue,
    );
  });

  testWidgets('Lichess opponent move triggers the clock switch', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    var streamCalls = 0;
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        streamCalls += 1;
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'white': {'id': 'chessnutplayer', 'name': 'ChessnutPlayer'},
            'black': {'id': 'nightbishop', 'name': 'nightbishop'},
            'state': {
              'moves': streamCalls == 1 ? '' : 'e2e4 e7e5',
              'status': 'started',
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/lichess-game-1/move/e2e4') {
        return http.Response('{"ok":true}', 200);
      }
      return http.Response('not found', 404);
    });
    final clockSwitchService = _RecordingClockSwitchService();

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
