          apiClient: ChessnutApiClient(httpClient: client),
          lichessConfig: const LichessGameConfig(
            gameId: 'lichess-game-1',
            token: 'lichess-token',
            lichessName: 'ChessnutPlayer',
          ),
          boardSettings: const BoardSettingsState(
            clockSwitchAutomation: ClockSwitchAutomationMode.opponentMoveOnly,
          ),
          clockSwitchService: clockSwitchService,
        ),
      ),
    );
