    await tester.tapAt(_boardSquareCenter(tester, 'e2'));
    await tester.pumpAndSettle();
    await tester.tapAt(_boardSquareCenter(tester, 'e4'));
    await tester.pumpAndSettle();

    expect(clockSwitchService.oppositeSwitches, 0);

    await tester.pump(const Duration(seconds: 3));
    await tester.pumpAndSettle();

    expect(clockSwitchService.oppositeSwitches, 1);
    expect(streamCalls, greaterThanOrEqualTo(2));
  });

