  testWidgets('Finished OTB game uploads PGN to Chessnut records', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    addTearDown(gateway.dispose);
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/uploadPgn') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'pgn_id': 222, 's_id': 'uploaded-otb'},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/updatePgn') {
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(httpClient: client, boardGateway: gateway),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _connectBoard(tester);

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('OTB Game'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Start recording'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Start recording'));
    await tester.pumpAndSettle();

    for (final fen in const [
      'rnbqkbnr/pppppppp/8/8/8/5P2/PPPPP1PP/RNBQKBNR',
      'rnbqkbnr/pppp1ppp/8/4p3/8/5P2/PPPPP1PP/RNBQKBNR',
      'rnbqkbnr/pppp1ppp/8/4p3/6P1/5P2/PPPPP2P/RNBQKBNR',
      'rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR',
    ]) {
      gateway.addBoardFen(fen);
      await tester.pump(const Duration(milliseconds: 850));
      await tester.pumpAndSettle();
    }

    expect(find.text('Game over'), findsWidgets);
    expect(find.text('Black wins by checkmate'), findsWidgets);

    final saves = requests
        .where(
          (request) =>
              request.url.path == '/api/uploadPgn' ||
              request.url.path == '/api/updatePgn',
        )
        .toList();
    final upload = saves.firstWhere(
      (request) => request.url.path == '/api/uploadPgn',
    );
    final finalSave = saves.last;
    expect(upload.bodyFields['play_mode'], 'otb');
    expect(finalSave.bodyFields['user_id'], '7');
    expect(finalSave.bodyFields['token'], '12345678901234567890123456789012');
    expect(finalSave.bodyFields['game_status'], '2');
    expect(finalSave.bodyFields['win_id'], '2');
    expect(finalSave.bodyFields['game_step'], '4');
    expect(finalSave.bodyFields['pgn'], contains('1. f3 e5 2. g4 Qh4#'));
    expect(finalSave.bodyFields['pgn'], contains('0-1'));
  });

