  testWidgets('Android Move game option flips the physical board', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.android;
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    await gateway.connect();
    addTearDown(gateway.dispose);

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.otb,
          boardGateway: gateway,
          botEngine: const _ScriptedBotEngineAdapter([]),
          positionAnalyzer: const _NoopPositionAnalyzer(),
        ),
      ),
    );
    await tester.pumpAndSettle();
    gateway.writes.clear();
    expect(
      tester
          .widget<InteractiveChessBoard>(find.byType(InteractiveChessBoard))
          .flipped,
      isFalse,
    );

    await tester.tap(find.byTooltip('More'));
    await tester.pumpAndSettle();
    expect(find.text('Flip board'), findsOneWidget);
    await tester.ensureVisible(find.text('Flip board'));
    await tester.tap(find.text('Flip board'));
    await tester.pumpAndSettle();

    expect(find.text('Are you sure?'), findsOneWidget);
    expect(
      find.text(
        "This action will initiate the pieces' movement and cannot be interrupted once started.",
      ),
      findsOneWidget,
    );
    expect(
      gateway.writes.any(
        (command) => command.isNotEmpty && command.first == 0x42,
      ),
      isFalse,
    );
    await tester.tap(find.text('Confirm'));
    await tester.pumpAndSettle();

    expect(
      gateway.writes.any(
        (command) => listEquals(
          command,
          ChessnutMoveBoardCodec.setBoardCommand(
            standardStartFen,
            isReverse: true,
          ),
        ),
      ),
      isTrue,
    );
    expect(find.text('Move board flipped.'), findsOneWidget);
    expect(
      tester
          .widget<InteractiveChessBoard>(find.byType(InteractiveChessBoard))
          .flipped,
      isFalse,
      reason: 'flipping the physical Move board must not rotate the UI board',
    );
    debugDefaultTargetPlatformOverride = null;
  });

  testWidgets('Move board flip option is available on every native platform', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    await gateway.connect();
    addTearDown(gateway.dispose);

    Future<void> pumpRoom({
      required PhysicalBoardGateway boardGateway,
      required bool isChessnutClockDevice,
    }) async {
      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.otb,
            boardGateway: boardGateway,
            isChessnutClockDevice: isChessnutClockDevice,
            botEngine: const _ScriptedBotEngineAdapter([]),
            positionAnalyzer: const _NoopPositionAnalyzer(),
          ),
        ),
      );
      await tester.pumpAndSettle();
      await tester.tap(find.byTooltip('More'));
      await tester.pumpAndSettle();
    }

    for (final platform in const [
      TargetPlatform.iOS,
      TargetPlatform.windows,
      TargetPlatform.macOS,
    ]) {
      debugDefaultTargetPlatformOverride = platform;
      await pumpRoom(
        boardGateway: gateway,
        isChessnutClockDevice: false,
      );
      expect(find.text('Flip board'), findsOneWidget);
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpAndSettle();
    }

    debugDefaultTargetPlatformOverride = TargetPlatform.android;
    await pumpRoom(
      boardGateway: gateway,
      isChessnutClockDevice: true,
    );
    expect(find.text('Flip board'), findsOneWidget);
    await tester.pumpWidget(const SizedBox.shrink());
    await tester.pumpAndSettle();

    final nonMoveGateway = MemoryPhysicalBoardGateway(
      boardModel: PhysicalBoardModel.air,
    );
    await nonMoveGateway.connect();
    addTearDown(nonMoveGateway.dispose);
    await pumpRoom(
      boardGateway: nonMoveGateway,
      isChessnutClockDevice: false,
    );
    expect(find.text('Flip board'), findsNothing);
    debugDefaultTargetPlatformOverride = null;
  });

