  testWidgets('Career game records include resumable career metadata', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    addTearDown(gateway.dispose);

    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' && request.url.path == '/api/uploadPgn') {
        return _uploadPgnResponse(pgnId: 665, shareId: 'career-draft');
      }
      if (request.method == 'POST' && request.url.path == '/api/updatePgn') {
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      return http.Response('not found', 404);
    });
    final progress = CareerModeProgress.fromElo(1500);
    final careerConfig = CareerOpponentProfile.matchFor(
      progress: progress,
      seed: 1,
    ).toBotGameConfig(progress: progress).copyWith(
          playerSide: BotPlayerSide.white,
          turn: 'White to move',
        );

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          apiClient: ChessnutApiClient(
            httpClient: client,
            session: _signedInKnightSession,
          ),
          boardSettings: const BoardSettingsState(fenDelayMs: 0),
          botConfig: careerConfig,
          botEngine: const _ScriptedBotEngineAdapter(['e7e5']),
          clockSwitchService: _RecordingClockSwitchService(),
          positionAnalyzer: const _NoopPositionAnalyzer(),
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.tapAt(_boardSquareCenter(tester, 'e2'));
    await tester.pumpAndSettle();
    await tester.tapAt(_boardSquareCenter(tester, 'e4'));
    await tester.pumpAndSettle();

    await _pumpUntilCondition(
      tester,
      () => requests.any((request) => request.url.path == '/api/uploadPgn'),
      timeout: const Duration(seconds: 5),
      reason: 'career record upload',
    );
    final upload = requests.firstWhere(
      (request) => request.url.path == '/api/uploadPgn',
    );
    final pgn = upload.bodyFields['pgn'] ?? '';
    expect(pgn, contains('[GameMode "Career"]'));
    expect(pgn, contains('[CareerMode "'));
    expect(pgn, contains('[CareerStartElo "1500"]'));
    expect(pgn, contains('[CareerWinElo "1525"]'));
    expect(pgn, contains('[CareerLoseElo "1475"]'));

