    expect(update.bodyFields['win_id'], '2');
    expect(update.bodyFields['game_step'], isNotEmpty);
    expect(update.bodyFields['pgn'], contains('[Result "0-1"]'));
    expect(update.bodyFields['pgn'], contains('[GameStatus "2"]'));

    final resignedCareerRecord = GameRecord(
      result: '0-1',
      title: 'Mila Chen (Maia 1500) vs Knight Rider',
      subtitle: 'Career / resigned',
      pgn: update.bodyFields['pgn'] ?? '',
      playMode: 'bot',
      gameStatus: 2,
      gameStep: int.parse(update.bodyFields['game_step'] ?? '0'),
