[CareerWinElo "1525"]
[CareerLoseElo "1475"]
[CareerOpponentName "Mila Chen"]

1. f3 e5 2. g4 *
''';
    const careerRecord = GameRecord(
      pgnId: 666,
      result: '*',
      title: 'Mila Chen (Maia 1500) vs Knight Rider',
      subtitle: 'Bot / 4 moves',
      pgn: careerPgn,
      playMode: 'bot',
      gameStatus: 1,
      gameStep: 4,
      winId: 0,
      whiteName: 'Mila Chen (Maia 1500)',
      blackName: 'Knight Rider',
    );
    expect(careerRecord.canContinueBotGame, isTrue);
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/wallet/balance') {
        return _walletBalanceResponse();
      }
      if (request.method == 'POST' && request.url.path == '/api/getPgnList') {
        return _pgnListResponse([
          {
            'id': 666,
            's_id': 'career-resume',
            'pgn': careerPgn,
            'white_name': 'Mila Chen (Maia 1500)',
            'black_name': 'Knight Rider',
            'play_time': 1715900000,
            'play_mode': 'bot',
            'win_id': 0,
            'game_status': 1,
            'game_step': 4,
          },
        ]);
      }
      if (request.method == 'POST' && request.url.path == '/api/updateElo') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'elo': 1525,
              'previous_elo': 1500,
              'delta': 25,
              'daily_task_reward': {
                'balance': 1250,
                'points_added': 20,
                'claimed_today': false,
              },
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' && request.url.path == '/api/updatePgn') {
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/wallet/claimTask') {
        final points = int.tryParse(request.bodyFields['points'] ?? '') ?? 0;
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'balance': 1240 + points,
              'points_added': points,
              'claimed_today': false,
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        boardGateway: gateway,
        clockSwitchService: _RecordingClockSwitchService(),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _openGameRecordsFromHome(tester);
    await _pumpUntilFound(
      tester,
      find.text('White: Mila Chen (Maia 1500) / Black: Knight Rider'),
      timeout: const Duration(seconds: 5),
    );
    await _pumpUntilFound(
      tester,
      find.byKey(const ValueKey('game-record-continue')),
      timeout: const Duration(seconds: 5),
    );
    await tester.tap(find.byKey(const ValueKey('game-record-continue')));
    await tester.pumpAndSettle();

    expect(find.byTooltip('Hint'), findsNothing);
    expect(find.text('0:00'), findsWidgets);

    gateway.addBoardFen('rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR');
    gateway.addBoardFen('rnb1kbnr/pppp1ppp/8/4p3/6Pq/5P2/PPPPP2P/RNBQKBNR');
    await tester.pump(const Duration(milliseconds: 850));
    await tester.pumpAndSettle();

    expect(find.text('Black wins by checkmate'), findsWidgets);
    await _pumpUntilCondition(
      tester,
      () => requests.any(
        (request) =>
            request.url.path == '/api/updateElo' &&
            request.bodyFields['career_result'] == 'victory',
      ),
      timeout: const Duration(seconds: 5),
      reason: 'career ELO settlement and task reward',
    );
    final eloRequest = requests.firstWhere(
      (request) =>
          request.url.path == '/api/updateElo' &&
          request.bodyFields['career_result'] == 'victory',
    );
    expect(eloRequest.bodyFields['user_id'], '7');
    expect(
      requests.where(
        (request) =>
            request.url.path == '/api/wallet/claimTask' &&
            request.bodyFields['task_key'] == 'career',
      ),
      isEmpty,
    );
    expect(find.text('Career challenge complete +20 points'), findsOneWidget);
  });

