  testWidgets('Bot evaluation score label follows the score boundary', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          positionAnalyzer: _SequencePositionAnalyzer(const [3.0]),
        ),
      ),
    );
    await tester.pumpAndSettle();

    final scoreBarRect = tester.getRect(
      find.byKey(const ValueKey('game-score-bar')),
    );
    final scoreLabelRect = tester.getRect(
      find.byKey(const ValueKey('game-score-label')),
    );
    final boundaryY = scoreBarRect.top +
        scoreBarRect.height * (1 - _normalizedEvalForTest('+3.00'));

    expect((scoreLabelRect.center.dy - boundaryY).abs(), lessThanOrEqualTo(3));
    expect(scoreBarRect.contains(scoreLabelRect.center), isTrue);
    expect(find.byKey(const ValueKey('game-score-bar-+3.00')), findsNothing);
  });

  testWidgets('Bot evaluation score bar maps mate scores to decisive fill', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
