    expect(scoreLabelRect.center.dy, greaterThan(scoreBarRect.center.dy));
    expect(scoreBarRect.contains(scoreLabelRect.center), isTrue);

    await tester.pumpWidget(_screenTestApp(const SizedBox.shrink()));
    await tester.pumpAndSettle();

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          positionAnalyzer: _SequencePositionAnalyzer(
            const [9.8],
            mates: const [2],
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    scoreBarRect = tester.getRect(
      find.byKey(const ValueKey('game-score-bar')),
    );
    scoreLabelRect = tester.getRect(
      find.byKey(const ValueKey('game-score-label')),
    );

    expect(find.text('#+2'), findsOneWidget);
    expect(scoreLabelRect.top, lessThan(scoreBarRect.top + 1));
    expect(scoreLabelRect.center.dy, lessThan(scoreBarRect.center.dy));
    expect(scoreBarRect.contains(scoreLabelRect.center), isTrue);
  });

