      addTearDown(gateway.dispose);

      await tester.pumpWidget(
        _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.bot,
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              evaluateLed: false,
              fenDelayMs: 0,
            ),
            positionAnalyzer: const _NoopPositionAnalyzer(),
            botEngine: const _FixedBotMoveEngineAdapter('e2e4'),
          ),
        ),
      );
      await tester.pumpAndSettle();

      await tester.tap(find.byTooltip('Hint'));
      await tester.pumpAndSettle();

      final hintCommand = ChessnutMoveLedCodec.commandFromSquares({
        'e2': ChessnutMoveLedColor.blue,
        'e4': ChessnutMoveLedColor.blue,
      });
      expect(gateway.writes.last, hintCommand);

      gateway.writes.clear();
      const liftedFen = 'rnbqkbnr/pppppppp/8/8/8/8/PPPP1PPP/RNBQKBNR';
      gateway.addBoardFen(liftedFen);
      await tester.pumpAndSettle();

      final hintedLegalTargetsCommand =
          ChessnutMoveLedCodec.commandFromSquares({
        'e2': ChessnutMoveLedColor.blue,
        'e3': ChessnutMoveLedColor.green,
        'e4': ChessnutMoveLedColor.blue,
      });
      expect(gateway.writes.last, hintedLegalTargetsCommand);

      gateway.writes.clear();
      gateway.addBoardFen(standardStartFen);
      gateway.addBoardFen(standardStartFen);
      await tester.pumpAndSettle();

      expect(gateway.writes.last, hintCommand);

      await tester.tap(find.byTooltip('Hint'));
      await tester.pumpAndSettle();

      expect(gateway.writes.last, ChessnutMoveLedCodec.offCommand());
    },
  );

