  testWidgets('Bot hint uses a dedicated strong Stockfish search', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final engine = _CapturingBotEngineAdapter('e2e4');

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          botConfig: const BotGameConfig.defaultConfig().copyWith(
            engineKind: BotEngineKind.maia,
            maiaElo: 1100,
          ),
          positionAnalyzer: const _NoopPositionAnalyzer(),
          botEngine: engine,
        ),
      ),
    );
    await tester.pumpAndSettle();

    final hintPrepareConfig = engine.preparedConfigs.lastWhere(
      (config) => config.engineKind == BotEngineKind.stockfish,
    );
    expect(hintPrepareConfig.stockfishElo, greaterThanOrEqualTo(2000));
    expect(
      hintPrepareConfig.stockfishThinkingTime,
      lessThanOrEqualTo(const Duration(milliseconds: 30)),
    );

    await tester.tap(find.byTooltip('Hint'));
    await tester.pumpAndSettle();

    expect(engine.configs, isNotEmpty);
    final hintConfig = engine.configs.single;
    expect(hintConfig.engineKind, BotEngineKind.stockfish);
    expect(hintConfig.stockfishElo, greaterThanOrEqualTo(2000));
    expect(
      hintConfig.stockfishThinkingTime,
      lessThanOrEqualTo(const Duration(milliseconds: 30)),
    );
  });

