  testWidgets('Bot score bar follows the displayed position in resumed PGN', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final analyzer = _SequencePositionAnalyzer([0.72, -0.48, 0.31]);
    const resumePgn = '''
[Event "Bot game room"]
[Site "Chessnut App"]
[White "Chessnut Player"]
[Black "Maia 1500"]
[Result "*"]

1. e4 e5 *
''';

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          botConfig: const BotGameConfig.defaultConfig().copyWith(
            resumePgn: resumePgn,
          ),
          positionAnalyzer: analyzer,
          botEngine: const _ScriptedBotEngineAdapter([]),
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(find.text('+0.72'), findsOneWidget);

    await tester.tap(find.byTooltip('Prev'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.length, 2);
    expect(find.text('-0.48'), findsOneWidget);
    expect(find.text('Move 1/2'), findsNothing);

    await tester.tap(find.byTooltip('Next'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.length, 3);
    expect(find.text('+0.31'), findsOneWidget);
  });

