  testWidgets('Bot leave exits immediately while record upload is pending', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final navigations = <String>[];
    final stalledUpload = Completer<http.Response>();
    final updates = <http.Request>[];
    http.Request? uploadRequest;
    GameRecord? localContinueRecord;
    var uploadStarted = false;
    final client = MockClient((request) async {
      if (request.method == 'POST' && request.url.path == '/api/uploadPgn') {
        uploadStarted = true;
        uploadRequest = request;
        return stalledUpload.future;
      }
      if (request.method == 'POST' && request.url.path == '/api/updatePgn') {
        updates.add(request);
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      return http.Response('not found', 404);
    });
    addTearDown(() {
      if (!stalledUpload.isCompleted) {
        stalledUpload.complete(_uploadPgnResponse());
      }
    });
    final clockSwitchService = _RecordingClockSwitchService();

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: navigations.add,
          mode: GameLaunchMode.bot,
          apiClient: ChessnutApiClient(
            httpClient: client,
            session: _signedInKnightSession,
          ),
          positionAnalyzer: const _NoopPositionAnalyzer(),
          botEngine: const _DelayedBotEngineAdapter.scripted(
            moves: ['e7e5', 'b8c6'],
            delay: Duration.zero,
          ),
          clockSwitchService: clockSwitchService,
          onBotTemporaryContinueRecord: (record) {
            localContinueRecord = record;
          },
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.tapAt(_boardSquareCenter(tester, 'e2'));
    await tester.pump();
    await tester.tapAt(_boardSquareCenter(tester, 'e4'));
    await tester.pumpAndSettle();
    await _pumpUntilFound(tester, find.text('e5'));

    await tester.tapAt(_boardSquareCenter(tester, 'g1'));
    await tester.pump();
    await tester.tapAt(_boardSquareCenter(tester, 'f3'));
    await tester.pumpAndSettle();
    await _pumpUntilFound(tester, find.text('Nc6'));

    await tester.tapAt(_boardSquareCenter(tester, 'f1'));
    await tester.pump();
    await tester.tapAt(_boardSquareCenter(tester, 'e2'));
    await tester.pumpAndSettle();

    await tester.tap(find.byIcon(Icons.arrow_back_rounded));
    await tester.pumpAndSettle();
    expect(find.text('Game still in progress'), findsOneWidget);

    await tester.tap(find.text('Leave for now'));
    await tester.pump();

    expect(uploadStarted, isTrue);
    expect(navigations, contains('Home'));
    expect(localContinueRecord?.gameStep, 5);
    expect(localContinueRecord?.pgn, contains('3. Be2'));
    await tester.pump(const Duration(milliseconds: 300));
    expect(find.text('Game still in progress'), findsNothing);

    stalledUpload.complete(_uploadPgnResponse());
    await _pumpUntilCondition(
      tester,
      () =>
          uploadRequest?.bodyFields['game_step'] == '5' ||
          updates.any((request) => request.bodyFields['game_step'] == '5'),
      timeout: const Duration(seconds: 10),
      reason: 'latest Bot PGN update after leaving the disposed room',
    );
    final latestRequest = updates.lastOrNull ?? uploadRequest!;
    expect(latestRequest.bodyFields['game_step'], '5');
    expect(latestRequest.bodyFields['pgn'], contains('3. Be2'));
    await tester.pumpAndSettle();
  });

