    addTearDown(gateway.dispose);

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(evaluateLed: false),
        ),
      ),
    );
    await tester.pumpAndSettle();
    gateway.writes.clear();

    await tester.tapAt(_boardSquareCenter(tester, 'e2'));
    await tester.pump();
    final firstCount = gateway.writes.length;

    await tester.tapAt(_boardSquareCenter(tester, 'g1'));
    await tester.pump(const Duration(milliseconds: 199));

    final knightTargetsCommand = ChessnutMoveLedCodec.commandFromSquares({
      'f3': ChessnutMoveLedColor.green,
      'h3': ChessnutMoveLedColor.green,
    });
    expect(firstCount, greaterThan(0));
