      gateway.writes.any((write) => listEquals(write, knightTargetsCommand)),
      isFalse,
    );

    await tester.pump(const Duration(milliseconds: 1));

    expect(
      gateway.writes.any((write) => listEquals(write, knightTargetsCommand)),
      isTrue,
    );
  });
  testWidgets('Lichess game hides engine assistance and evaluation', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final client = MockClient((request) async {
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getLichessToken') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'token': 'lichess-token',
              'lichess_name': 'ChessnutPlayer',
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() == 'https://lichess.org/api/board/seek') {
        return http.Response('', 200);
      }
      if (request.method == 'GET' &&
          request.url.toString() == 'https://lichess.org/api/stream/event') {
        return http.Response(
          jsonEncode({
            'type': 'gameStart',
            'game': {'id': 'lichess-game-1'},
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'state': {'moves': '', 'status': 'started'},
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        networkLatencyProbe: const _FixedLatencyProbe(120),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _connectBoard(tester);

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find an online match'));
    await tester.pumpAndSettle();
    final findGameButton = find.text('Find 10+5 game');
    expect(findGameButton, findsOneWidget);
    await tester.ensureVisible(findGameButton);
    await tester.pumpAndSettle();
    await tester.tap(findGameButton);
    await tester.pumpAndSettle();
    await tester.runAsync(() => Future<void>.delayed(Duration.zero));
    await tester.pumpAndSettle();
    expect(find.text('Board connected'), findsOneWidget);
    expect(find.text('Lichess 120ms'), findsOneWidget);
    expect(find.text('Lichess 10+5'), findsNothing);
    expect(
      find.byKey(const ValueKey('network-latency-stable')),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('game-score-bar')), findsNothing);
    expect(find.byTooltip('Hint'), findsNothing);

    await tester.tap(find.byTooltip('More'));
    await tester.pumpAndSettle();
    expect(find.text('Show scorebar'), findsNothing);
    expect(find.text('Move quality lights'), findsNothing);
    expect(find.text('Share live URL'), findsOneWidget);
  });

