  testWidgets(
      'Lichess friend mode detects missing scope and upgrades authorization', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(900, 1200);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    var tokenChecks = 0;
    final authorizationUrls = <Uri>[];
    final requestPaths = <String>[];
    final client = MockClient((request) async {
      requestPaths.add(request.url.path);
      if (request.url.path == '/api/getLichessToken') {
        tokenChecks += 1;
        final token = tokenChecks == 1 ? 'old-token' : 'upgraded-token';
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'token': token,
              'lichess_name': 'ChessnutPlayer',
            },
          }),
          200,
        );
      }
      if (request.url.path == '/api/freeUserBind') {
        expect(request.bodyFields['bind_type'], 'lichess');
        return http.Response(
          '{"ret":1,"code":200,"info":"ok","data":null}',
          200,
        );
      }
      if (request.url.path == '/api/bindLichess') {
        expect(request.bodyFields.containsKey('reauthorize'), isFalse);
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': 'https://lichess.org/oauth?scope=follow%3Aread',
          }),
          200,
        );
      }
      if (request.url.path == '/api/rel/following') {
        if (request.headers['Authorization'] == 'Bearer old-token') {
          return http.Response('{"error":"Missing scope: follow:read"}', 403);
        }
        return http.Response(
          jsonEncode({
            'id': 'friend-player',
            'username': 'FriendPlayer',
            'online': true,
            'perfs': {
              'rapid': {'rating': 1800},
            },
          }),
          200,
        );
      }
      if (request.url.path == '/api/challenge') {
        return http.Response('{"in":[],"out":[]}', 200);
      }
      return http.Response('not found', 404);
    });
    final apiClient = ChessnutApiClient(httpClient: client)
      ..session = _signedInKnightSession.copyWith(
        bindLichess: true,
        lichessName: 'ChessnutPlayer',
      );

    await tester.pumpWidget(
      _screenTestApp(
        OnlineSetupScreen(
          onNavigate: (_) {},
          apiClient: apiClient,
          onSessionUpdated: (session) => apiClient.session = session,
          boardSettings: const BoardSettingsState(),
          onBoardSettingsChanged: (_) {},
          lichessAuthorizationPresenter: (context,
              {required authorizationUri}) async {
            authorizationUrls.add(authorizationUri);
            return true;
          },
          onLaunchGame: (mode, {botConfig, otbConfig, lichessConfig}) {},
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.tap(find.text('Friend match'));
    await tester.pumpAndSettle();
    expect(
      find.textContaining('does not include friend-list access'),
      findsOneWidget,
    );
    expect(find.text('Re-authorize Lichess'), findsOneWidget);

    final reauthorizeButton = find.text('Re-authorize Lichess');
    await tester.ensureVisible(reauthorizeButton);
    await tester.pumpAndSettle();
    await tester.tap(reauthorizeButton);
    await tester.pumpAndSettle();

    expect(authorizationUrls, hasLength(1));
    expect(
      requestPaths.indexOf('/api/freeUserBind'),
      lessThan(requestPaths.indexOf('/api/bindLichess')),
    );
    expect(find.textContaining('FriendPlayer'), findsOneWidget);
    expect(find.text('Challenge player'), findsOneWidget);
  });

