  testWidgets('Lichess challenge shows terminal dialogs and can be canceled', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final pendingChallengeLines = StreamController<List<int>>();
    addTearDown(() {
      unawaited(pendingChallengeLines.close());
    });
    final requestedPaths = <String>[];
    http.StreamedResponse response(String body, {int statusCode = 200}) {
      return http.StreamedResponse(
        Stream<List<int>>.value(utf8.encode(body)),
        statusCode,
      );
    }

    final client = MockClient.streaming((request, bodyStream) async {
      requestedPaths.add(request.url.path);
      if (request.url.path == '/api/getLichessToken') {
        return response(jsonEncode({
          'ret': 1,
          'code': 200,
          'info': 'ok',
          'data': {
            'token': 'challenge-token',
            'lichess_name': 'ChessnutPlayer',
          },
        }));
      }
      if (request.url.path == '/api/rel/following') {
        return response(
          '{"error":"Missing scope: follow:read"}',
          statusCode: 403,
        );
      }
      if (request.url.path == '/api/challenge/DecliningPlayer') {
        return response([
          jsonEncode({
            'challenge': {
              'id': 'declined-game',
              'status': 'created',
              'direction': 'out',
              'challenger': {'name': 'ChessnutPlayer'},
              'destUser': {'name': 'DecliningPlayer'},
              'variant': {'key': 'standard'},
              'speed': 'rapid',
              'rated': false,
              'color': 'random',
              'timeControl': {'limit': 600, 'increment': 5},
            },
          }),
          jsonEncode({'done': 'declined'}),
        ].join('\n'));
      }
      if (request.url.path == '/api/challenge/WaitingPlayer') {
        return http.StreamedResponse(pendingChallengeLines.stream, 200);
      }
      if (request.url.path == '/api/challenge/ExpiringPlayer') {
        return response(jsonEncode({
          'challenge': {
            'id': 'expired-game',
            'status': 'created',
            'direction': 'out',
            'challenger': {'name': 'ChessnutPlayer'},
            'destUser': {'name': 'ExpiringPlayer'},
            'variant': {'key': 'standard'},
            'speed': 'rapid',
            'rated': false,
            'color': 'random',
            'timeControl': {'limit': 600, 'increment': 5},
          },
        }));
      }
      if (request.url.path == '/api/challenge/pending-game/cancel') {
        return response('{"ok":true}');
      }
      return response('not found', statusCode: 404);
    });
    final apiClient = ChessnutApiClient(httpClient: client)
      ..session = _signedInKnightSession.copyWith(
        bindLichess: true,
        lichessName: 'ChessnutPlayer',
      );

    await tester.pumpWidget(
      _screenTestApp(
        OnlineSetupScreen(
          onNavigate: (_) {},
          apiClient: apiClient,
          onSessionUpdated: (session) => apiClient.session = session,
          boardSettings: const BoardSettingsState(),
          onBoardSettingsChanged: (_) {},
          onLaunchGame: (mode, {botConfig, otbConfig, lichessConfig}) {
            fail('A declined or canceled challenge must not launch a game.');
          },
        ),
      ),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Friend match'));
    await tester.pumpAndSettle();

    final usernameField =
        find.byKey(const ValueKey('lichess-player-username-field'));
    await tester.enterText(usernameField, 'DecliningPlayer');
    await tester.pumpAndSettle();
    var challengeButton = find.text('Challenge player');
    await tester.ensureVisible(challengeButton);
    await tester.pumpAndSettle();
    await tester.tap(challengeButton);
    await tester.pumpAndSettle();

    expect(
      find.byKey(const ValueKey('lichess-challenge-status-dialog')),
      findsOneWidget,
    );
    expect(find.text('The player declined the challenge.'), findsWidgets);
    await tester.tap(find.text('Done'));
    await tester.pumpAndSettle();

    await tester.enterText(usernameField, 'WaitingPlayer');
    await tester.pumpAndSettle();
    challengeButton = find.text('Challenge player');
    await tester.ensureVisible(challengeButton);
    await tester.pumpAndSettle();
    await tester.tap(challengeButton);
    await tester.pump();
    await tester.runAsync(() => Future<void>.delayed(Duration.zero));
    await tester.pump();
    expect(requestedPaths, contains('/api/challenge/WaitingPlayer'));
    pendingChallengeLines.add(utf8.encode('${jsonEncode({
          'challenge': {
            'id': 'pending-game',
            'status': 'created',
            'direction': 'out',
            'challenger': {'name': 'ChessnutPlayer'},
            'destUser': {'name': 'WaitingPlayer'},
            'variant': {'key': 'standard'},
            'speed': 'rapid',
            'rated': false,
            'color': 'random',
            'timeControl': {'limit': 600, 'increment': 5},
          },
        })}\n'));
    await tester.runAsync(() => Future<void>.delayed(Duration.zero));
    await tester.pumpAndSettle();

    final cancelButton =
        find.byKey(const ValueKey('lichess-cancel-challenge-button'));
    expect(cancelButton, findsOneWidget);
    await tester.ensureVisible(cancelButton);
    await tester.tap(cancelButton);
    await tester.runAsync(
      () => Future<void>.delayed(const Duration(milliseconds: 10)),
    );
    await tester.pumpAndSettle();

    expect(
      requestedPaths,
      contains('/api/challenge/pending-game/cancel'),
    );
    expect(
      find.byKey(const ValueKey('lichess-challenge-status-dialog')),
      findsOneWidget,
    );
    expect(find.text('Challenge canceled.'), findsWidgets);
    await tester.tap(find.text('Done'));
    await tester.pumpAndSettle();

    await tester.enterText(usernameField, 'ExpiringPlayer');
    await tester.pumpAndSettle();
    challengeButton = find.text('Challenge player');
    await tester.ensureVisible(challengeButton);
    await tester.pumpAndSettle();
    await tester.tap(challengeButton);
    await tester.pumpAndSettle();

    expect(
      find.byKey(const ValueKey('lichess-challenge-status-dialog')),
      findsOneWidget,
    );
    expect(find.text('The challenge expired.'), findsWidgets);
  });

  testWidgets('Online match connection steps are static information', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final apiClient = ChessnutApiClient(
      httpClient: MockClient((_) async => http.Response('not found', 404)),
    );

    await tester.pumpWidget(
