        OnlineSetupScreen(
          onNavigate: (_) {},
          onLaunchGame: (
            mode, {
            botConfig,
            otbConfig,
            lichessConfig,
          }) {},
          apiClient: apiClient,
          onSessionUpdated: (_) {},
          boardSettings: const BoardSettingsState(),
          onBoardSettingsChanged: (_) {},
        ),
      ),
    );
    await tester.pumpAndSettle();

    void expectStaticSteps() {
      for (final number in ['1', '2', '3']) {
        final step = find.byKey(ValueKey('online-connection-step-$number'));
        expect(step, findsOneWidget);
        expect(
          find.descendant(of: step, matching: find.byType(InkWell)),
          findsNothing,
        );
        expect(
          find.descendant(of: step, matching: find.byType(GlassPanel)),
          findsNothing,
        );
      }
    }

    expect(find.text('Authorize'), findsOneWidget);
    expect(find.text('Seek'), findsOneWidget);
    expect(find.text('Stream'), findsOneWidget);
    expectStaticSteps();

    await tester.tap(find.text('Chess.com'));
    await tester.pumpAndSettle();

    expect(find.text('WebView'), findsWidgets);
    expect(find.text('Mirror'), findsOneWidget);
    expect(find.text('Board'), findsOneWidget);
    expectStaticSteps();
  });

  testWidgets(
    'Lichess disables queued physical board LEDs when piece position LED is off',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = _BlockingGeneralLedGateway();
      await gateway.connect();
      addTearDown(gateway.dispose);
      final clockSwitchService = _RecordingClockSwitchService();

      final client = MockClient((request) async {
        if (request.method == 'GET' &&
            request.url.toString() ==
                'https://lichess.org/api/board/game/stream/lichess-game-1') {
          return http.Response(
            [
              jsonEncode({
                'type': 'gameFull',
                'id': 'lichess-game-1',
                'initialFen': 'startpos',
                'white': {'id': 'chessnutplayer', 'name': 'ChessnutPlayer'},
                'black': {'id': 'nightbishop', 'name': 'nightbishop'},
                'state': {'moves': 'e2e4', 'status': 'started'},
              }),
              jsonEncode({
                'type': 'gameState',
                'moves': 'e2e4 e7e5',
                'status': 'started',
              }),
            ].join('\n'),
            200,
          );
        }
        return http.Response('not found', 404);
      });

      Widget buildRoom(BoardSettingsState settings) {
        return _screenTestApp(
          GameRoomScreen(
            onNavigate: (_) {},
            mode: GameLaunchMode.lichess,
            apiClient: ChessnutApiClient(httpClient: client),
            boardGateway: gateway,
            boardSettings: settings,
            clockSwitchService: clockSwitchService,
            lichessConfig: const LichessGameConfig(
              gameId: 'lichess-game-1',
              token: 'lichess-token',
              lichessName: 'ChessnutPlayer',
            ),
          ),
        );
      }

      await tester.pumpWidget(
        buildRoom(const BoardSettingsState(fenDelayMs: 0)),
      );
      await tester.pump();
      for (var i = 0;
          i < 20 && !gateway.firstSetLedWriteStarted.isCompleted;
          i += 1) {
        await tester.pump(const Duration(milliseconds: 50));
      }
      expect(gateway.firstSetLedWriteStarted.isCompleted, isTrue);

      await tester.pumpWidget(
        buildRoom(
          const BoardSettingsState(fenDelayMs: 0, piecePositionLed: false),
        ),
      );
      await tester.pump();

      gateway.releaseFirstSetLedWrite.complete();
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 250));

      final clearCommand = ChessnutLedCodec.ledCommand(List<int>.filled(64, 0));
      final ledWrites = gateway.writes.where(_isGeneralLedCommand).toList();
      expect(ledWrites, isNotEmpty);
      expect(ledWrites.last, clearCommand);
    },
  );

