      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'state': {
              'moves': 'd2d4 d7d5',
              'status': 'started',
              'wtime': 185000,
              'btime': 245000,
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });
    final apiClient = ChessnutApiClient(httpClient: client);

    const resumePgn = '''
[Event "Native game room"]
[Site "Chessnut App"]
[White "ChessnutPlayer"]
[Black "nightbishop"]
[Result "*"]
[TimeControl "5+3"]
[LichessGameId "lichess-game-1"]
[LichessToken "lichess-token"]
[LichessName "ChessnutPlayer"]
[WhiteTime "250"]
[BlackTime "230"]

1. e4 e5 *
''';

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.lichess,
          apiClient: apiClient,
          lichessConfig: const LichessGameConfig(
            gameId: 'lichess-game-1',
            token: 'lichess-token',
            lichessName: 'ChessnutPlayer',
            timeMinutes: 5,
            incrementSeconds: 3,
            resumePgn: resumePgn,
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(find.text('3:05'), findsOneWidget);
    expect(find.text('4:05'), findsOneWidget);
    expect(find.text('4:10'), findsNothing);
    expect(find.text('3:50'), findsNothing);
    final board = tester.widget<InteractiveChessBoard>(
      find.byType(InteractiveChessBoard),
    );
    // The room must be built from the live stream, not from resumePgn.
    expect(board.initialFen, contains('3P4'));
    expect(board.initialFen, isNot(contains('4P3')));
  });

