  testWidgets('Lichess clock times stay with the correct player side', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(1280, 480);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final client = MockClient((request) async {
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'white': {
              'id': 'nightbishop',
              'name': 'nightbishop',
              'rating': 1842,
            },
            'black': {
              'id': 'chessnutplayer',
              'name': 'ChessnutPlayer',
              'rating': 1765,
            },
            'state': {
              'moves': 'e2e4 e7e5',
              'status': 'started',
              'wtime': 83000,
              'btime': 296000,
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.lichess,
          apiClient: ChessnutApiClient(httpClient: client),
          lichessConfig: const LichessGameConfig(
            gameId: 'lichess-game-1',
            token: 'lichess-token',
            lichessName: 'ChessnutPlayer',
          ),
        ),
      ),
    );
    await tester.pumpAndSettle();

    final boardRect = tester.getRect(find.byType(InteractiveChessBoard));
    final headerRect =
        tester.getRect(find.byKey(const ValueKey('game-compact-header')));
    final statusRect =
        tester.getRect(find.byKey(const ValueKey('game-room-status-capsules')));
    final topClockRect =
        tester.getRect(find.byKey(const ValueKey('game-clock-top')));
    final bottomClockRect =
        tester.getRect(find.byKey(const ValueKey('game-clock-bottom')));
    final pgnRect =
        tester.getRect(find.byKey(const ValueKey('game-pgn-strip')));
    final actionsRect =
        tester.getRect(find.byKey(const ValueKey('game-actions')));
    expect(find.text('Lichess game'), findsOneWidget);
    expect(headerRect.bottom, lessThanOrEqualTo(boardRect.top));
    expect(statusRect.top, greaterThanOrEqualTo(headerRect.top));
    expect(statusRect.bottom, lessThanOrEqualTo(headerRect.bottom));
    expect(boardRect.left, lessThan(80));
    expect(topClockRect.left, greaterThan(boardRect.right));
    expect(bottomClockRect.left, greaterThan(boardRect.right));
    expect(pgnRect.left, greaterThan(topClockRect.right));
    expect(actionsRect.left, greaterThan(topClockRect.right));
    expect(actionsRect.bottom, lessThanOrEqualTo(480));
    final topSourceRect =
        tester.getRect(find.byKey(const ValueKey('game-clock-top-source')));
    final topNameRect =
        tester.getRect(find.byKey(const ValueKey('game-clock-top-name')));
    final topRatingRect =
        tester.getRect(find.byKey(const ValueKey('game-clock-top-rating')));
    expect(topNameRect.bottom, lessThanOrEqualTo(topRatingRect.top));
    expect(topRatingRect.bottom, lessThanOrEqualTo(topSourceRect.top));
    expect(topSourceRect.bottom, lessThan(topClockRect.bottom));

    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('ChessnutPlayer'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('Elo 1765'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('ChessnutPlayer (Elo 1765)'),
      ),
      findsNothing,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('4:56'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-bottom')),
        matching: find.text('nightbishop'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-bottom')),
        matching: find.text('Elo 1842'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-bottom')),
        matching: find.text('1:23'),
      ),
      findsOneWidget,
    );

    await tester.tap(find.byIcon(Icons.swap_vert_rounded));
    await tester.pump();

    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('nightbishop'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-top')),
        matching: find.text('1:23'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-bottom')),
        matching: find.text('ChessnutPlayer'),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('game-clock-bottom')),
        matching: find.text('4:56'),
      ),
      findsOneWidget,
    );
  });

