  testWidgets('Lichess online setup requires auth and custom time works', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    var lichessBound = false;
    var launchedLichessUri = <Uri>[];
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getLichessToken') {
        if (!lichessBound) {
          return http.Response(
            jsonEncode({
              'ret': 0,
              'code': 502,
              'info': 'lichess not bound',
              'data': null,
            }),
            200,
          );
        }
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'token': 'lichess-token',
              'lichess_name': 'ChessnutPlayer',
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/bindLichess') {
        lichessBound = true;
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': 'https://lichess.org/oauth',
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() == 'https://lichess.org/api/board/seek') {
        return http.Response('', 200);
      }
      if (request.method == 'GET' &&
          request.url.toString() == 'https://lichess.org/api/stream/event') {
        return http.Response(
          [
            jsonEncode({
              'type': 'gameStart',
              'game': {'id': 'lichess-game-1'},
            }),
          ].join('\n'),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://lichess.org/api/board/game/stream/lichess-game-1') {
        return http.Response(
          jsonEncode({
            'type': 'gameFull',
            'id': 'lichess-game-1',
            'initialFen': 'startpos',
            'state': {'moves': '', 'status': 'started'},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'total_page': 1, 'pgnList': []},
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        lichessAuthorizationPresenter: (BuildContext context,
            {required Uri authorizationUri}) async {
          launchedLichessUri.add(authorizationUri);
          return true;
        },
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _connectBoard(tester);

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find an online match'));
    await tester.pumpAndSettle();

    expect(
      requests.any((request) => request.url.path == '/api/getLichessToken'),
      isTrue,
    );
    expect(find.text('Lichess authorization required'), findsOneWidget);
    expect(find.text('Find 10+5 game'), findsOneWidget);
    await tester.scrollUntilVisible(
      find.text('Find 10+5 game'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find 10+5 game'));
    await tester.pumpAndSettle();
    expect(
      requests.any((request) => request.url.path == '/api/board/seek'),
      isFalse,
    );

    await tester.tap(find.text('Authorize Lichess'));
    await tester.pumpAndSettle();
    expect(
      requests.any((request) => request.url.path == '/api/bindLichess'),
      isTrue,
    );
    expect(launchedLichessUri.single.toString(), 'https://lichess.org/oauth');
    expect(
      requests
          .where((request) => request.url.path == '/api/getLichessToken')
          .length,
      greaterThanOrEqualTo(2),
    );
    expect(find.text('Lichess authorized'), findsOneWidget);
    expect(find.text('Simulate expired'), findsNothing);
    expect(find.text('Rated'), findsOneWidget);

    await tester.scrollUntilVisible(
      find.text('15+10'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('15+10'));
    await tester.pumpAndSettle();
    expect(find.text('Online search: 15+10'), findsOneWidget);

    await tester.tap(find.text('Custom'));
    await tester.pumpAndSettle();
    expect(find.text('Custom time'), findsOneWidget);
    await tester.enterText(find.widgetWithText(TextField, 'Minutes'), '12');
    await tester.enterText(find.widgetWithText(TextField, 'Increment'), '3');
    await tester.tap(find.text('Save'));
    await tester.pumpAndSettle();
    expect(find.text('Custom 12+3'), findsOneWidget);
    expect(find.text('Online search: Custom 12+3'), findsOneWidget);

    await tester.scrollUntilVisible(
      find.text('Find Custom 12+3 game'),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find Custom 12+3 game'));
    await tester.pumpAndSettle();
    await tester.runAsync(() => Future<void>.delayed(Duration.zero));
    await tester.pumpAndSettle();
    expect(find.text('Board connected'), findsOneWidget);
    final eventStreamIndex = requests.indexWhere(
      (request) => request.url.path == '/api/stream/event',
    );
    final seekIndex = requests.indexWhere(
      (request) => request.url.path == '/api/board/seek',
    );
    expect(eventStreamIndex, lessThan(seekIndex));
    expect(requests[seekIndex].bodyFields['rated'], 'false');
  });

  testWidgets('Lichess 10+5 seek starts immediately while event stream waits', (
    WidgetTester tester,
  ) async {
