    final requests = <http.BaseRequest>[];
    final apiClient = ChessnutApiClient(
      httpClient: MockClient.streaming((request, bodyStream) async {
        requests.add(request);
        if (request.method == 'POST' &&
            request.url.toString() ==
                'https://api.chessnutech.com/api/getLichessToken') {
          return http.StreamedResponse(
            Stream<List<int>>.value(
              utf8.encode(jsonEncode({
                'ret': 1,
                'code': 200,
                'info': 'ok',
                'data': {
                  'token': 'lichess-token',
                  'lichess_name': 'ChessnutPlayer',
                },
              })),
            ),
            200,
          );
        }
        if (request.method == 'GET' &&
            request.url.toString() == 'https://lichess.org/api/stream/event') {
          return http.StreamedResponse(eventLines.stream, 200);
        }
        if (request.method == 'POST' &&
            request.url.toString() == 'https://lichess.org/api/board/seek') {
          return http.StreamedResponse(const Stream<List<int>>.empty(), 200);
        }
        return http.StreamedResponse(
          Stream<List<int>>.value(utf8.encode('not found')),
