      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(findGameButton);
    await tester.pump(const Duration(milliseconds: 600));

    expect(find.text('Finding game...'), findsOneWidget);
    final seekRequest = requests
        .whereType<http.Request>()
        .firstWhere((request) => request.url.path == '/api/board/seek');
    expect(seekRequest.bodyFields['time'], '10');
    expect(seekRequest.bodyFields['increment'], '5');
    eventLines.add(utf8.encode('${jsonEncode({
          'type': 'gameStart',
          'game': {'id': 'lichess-game-1'},
        })}\n'));
    await tester.pumpAndSettle();
  });

  testWidgets('Lichess online setup reauthorizes expired tokens', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    var reauthorizationRequested = false;
    final launchedLichessUri = <Uri>[];
    final requests = <http.Request>[];
    final linkedLoginResponse = {
      ..._loginResponse,
      'data': {
        ..._loginResponse['data'] as Map<String, Object?>,
        'bind_lichess': true,
        'lichess_name': 'OldLichessName',
      },
    };
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(linkedLoginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getLichessToken') {
        if (!reauthorizationRequested) {
          return http.Response(
            jsonEncode({
              'ret': 0,
              'code': 502,
              'info': 'Lichess authorization expired',
              'data': null,
            }),
            200,
          );
        }
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'token': 'fresh-lichess-token',
              'lichess_name': 'ChessnutPlayer',
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/bindLichess') {
        reauthorizationRequested = true;
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': 'https://lichess.org/oauth',
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/freeUserBind') {
        expect(request.bodyFields['bind_type'], 'lichess');
        return http.Response(
          '{"ret":1,"code":200,"info":"ok","data":null}',
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'total_page': 1, 'pgnList': []},
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        lichessAuthorizationPresenter: (BuildContext context,
            {required Uri authorizationUri}) async {
          launchedLichessUri.add(authorizationUri);
          return true;
        },
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _connectBoard(tester);

    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find an online match'));
    await tester.pumpAndSettle();

    expect(find.text('Authorization expired'), findsOneWidget);
    expect(find.text('Re-authorize Lichess'), findsOneWidget);

    await tester.tap(find.text('Re-authorize Lichess'));
    await tester.pumpAndSettle();

    expect(
      requests.any((request) => request.url.path == '/api/bindLichess'),
      isTrue,
    );
    expect(
      requests.indexWhere(
        (request) => request.url.path == '/api/freeUserBind',
      ),
      lessThan(
        requests.indexWhere(
          (request) => request.url.path == '/api/bindLichess',
        ),
      ),
    );
    expect(launchedLichessUri.single.toString(), 'https://lichess.org/oauth');
    expect(find.text('Lichess authorized'), findsOneWidget);
    expect(find.textContaining('ChessnutPlayer'), findsWidgets);
    expect(find.text('Find 10+5 game'), findsOneWidget);
  });

