  testWidgets('Android Chess.com shows confirmed Move board actions', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.android;
    try {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(top: 24, bottom: 24);
      tester.view.viewPadding = const FakeViewPadding(top: 24, bottom: 24);
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      addTearDown(tester.view.resetPadding);
      addTearDown(tester.view.resetViewPadding);
      final gateway = MemoryPhysicalBoardGateway();
      await gateway.connect();
      addTearDown(gateway.dispose);

      await tester.pumpWidget(
        _screenTestApp(
          ChessComWebViewScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: _emptyBackendClient()),
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(fenDelayMs: 0),
            latencyProbe: const _FixedLatencyProbe(80),
            webViewAdapter: _MutableChessComWebViewAdapter(
              chessnutStandardStartFen,
            ),
          ),
        ),
      );
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 950));
      await tester.pumpAndSettle();

      const resetKey = ValueKey('chesscom-reset-move-board-button');
      const flipKey = ValueKey('chesscom-flip-move-board-button');
      expect(find.byKey(resetKey), findsOneWidget);
      expect(find.byKey(flipKey), findsOneWidget);
      for (final key in [
        const ValueKey('chesscom-back-button'),
        resetKey,
        flipKey,
        const ValueKey('chesscom-refresh-page-button'),
        const ValueKey('chesscom-board-bluetooth-status'),
      ]) {
        expect(tester.getSize(find.byKey(key)), const Size.square(44));
        final icon = tester.widget<Icon>(
          find.descendant(of: find.byKey(key), matching: find.byType(Icon)),
        );
        expect(icon.size, 28);
      }

      gateway.writes.clear();
      await tester.tap(find.byKey(resetKey));
      await tester.pumpAndSettle();
      expect(find.text('Are you sure?'), findsOneWidget);
      expect(
        gateway.writes.any(
          (command) => command.isNotEmpty && command.first == 0x42,
        ),
        isFalse,
      );
      await tester.tap(find.text('Confirm'));
      await tester.pumpAndSettle();
      expect(
        gateway.writes.any(
          (command) => listEquals(
            command,
            ChessnutMoveBoardCodec.setBoardCommand(chessnutStandardStartFen),
          ),
        ),
        isTrue,
      );

      gateway.writes.clear();
      await tester.tap(find.byKey(flipKey));
      await tester.pumpAndSettle();
      expect(find.text('Are you sure?'), findsOneWidget);
      await tester.tap(find.text('Confirm'));
      await tester.pumpAndSettle();
      expect(
        gateway.writes.any(
          (command) => listEquals(
            command,
            ChessnutMoveBoardCodec.setBoardCommand(
              chessnutStandardStartFen,
              isReverse: true,
            ),
          ),
        ),
        isTrue,
      );

      gateway.writes.clear();
      await tester.tap(find.byKey(resetKey));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Confirm'));
      await tester.pumpAndSettle();
      expect(
        gateway.writes.any(
          (command) => listEquals(
            command,
            ChessnutMoveBoardCodec.setBoardCommand(
              chessnutStandardStartFen,
              isReverse: true,
            ),
          ),
        ),
        isTrue,
        reason: 'Reset must preserve the current Move board direction.',
      );
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

