  testWidgets('Chess.com game records save the players from the WebView', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    addTearDown(gateway.dispose);
    await gateway.connect();
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'GET' &&
          request.url.toString() ==
              ChessnutEndpointConfig.apiBaseUri
                  .replace(path: 'static/js/chess-helper.js')
                  .toString()) {
        return http.Response('', 200);
      }
      if (request.method == 'POST' && request.url.path == '/api/uploadPgn') {
        return _uploadPgnResponse(pgnId: 6262, shareId: 'chesscom-players');
      }
      if (request.method == 'POST' && request.url.path == '/api/updatePgn') {
        return http.Response(jsonEncode({'ret': 1, 'code': 200}), 200);
      }
      return http.Response('not found', 404);
    });
    final webViewAdapter = _MutableChessComWebViewAdapter(
      chessnutStandardStartFen,
      players: const {
        'white': 'Alice',
        'black': 'Bob',
      },
      resultToken: null,
      timeControl: '5+0',
      gameSite: 'https://www.chess.com/game/live/123',
    );

    await tester.pumpWidget(
      _screenTestApp(
        ChessComWebViewScreen(
          onNavigate: (_) {},
          apiClient: ChessnutApiClient(
            httpClient: client,
            session: const ChessnutApiSession(userId: 1, token: 'token'),
          ),
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(fenDelayMs: 0),
          latencyProbe: const _FixedLatencyProbe(80),
          webViewAdapter: webViewAdapter,
        ),
      ),
    );
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 950));
    await tester.pumpAndSettle();

    const e4BoardFen = 'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR';
    gateway.addBoardFen(e4BoardFen);
    gateway.addBoardFen(e4BoardFen);

    await _pumpUntilCondition(
      tester,
      () => requests.any((request) => request.url.path == '/api/uploadPgn'),
      timeout: const Duration(seconds: 3),
      reason: 'Chess.com record upload',
    );

    final upload =
        requests.singleWhere((request) => request.url.path == '/api/uploadPgn');
    expect(upload.bodyFields['white_name'], 'Alice');
    expect(upload.bodyFields['black_name'], 'Bob');
    expect(upload.bodyFields['game_status'], '1');
    expect(upload.bodyFields['win_id'], '0');
    expect(upload.bodyFields['pgn'], contains('[White "Alice"]'));
    expect(upload.bodyFields['pgn'], contains('[Black "Bob"]'));
    expect(upload.bodyFields['pgn'], contains('[Result "*"]'));
    expect(upload.bodyFields['pgn'], contains('[TimeControl "300+0"]'));
    expect(upload.bodyFields['pgn'], isNot(contains('[PlayerSide ')));
    expect(upload.bodyFields['pgn'], isNot(contains('[ChessnutGameId ')));

    webViewAdapter.resultToken = '0-1';
    webViewAdapter.completeRecord = const {
      'pgn': '''
[Event "Live Chess"]
[Site "https://www.chess.com/game/live/123"]
[UTCDate "2026.08.26"]
[UTCTime "12:00:00"]
[White "Alice"]
[Black "Bob"]
[Result "0-1"]
[Speed "Classical"]
[TimeControl "300+0"]

1. e4 e5 2. Nf3 Nc6 0-1
''',
      'result': '0-1',
      'white': 'Alice',
      'black': 'Bob',
    };
    webViewAdapter.currentFen =
        'r1bqkbnr/pppp1ppp/2n5/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 2 3';
    await tester.pump(const Duration(milliseconds: 950));
    await _pumpUntilCondition(
      tester,
      () => requests.any((request) =>
          request.url.path == '/api/updatePgn' &&
          request.bodyFields['game_status'] == '2'),
      timeout: const Duration(seconds: 3),
      reason: 'Chess.com finished record update',
    );

    final update =
        requests.where((request) => request.url.path == '/api/updatePgn').last;
    expect(update.bodyFields['white_name'], 'Alice');
    expect(update.bodyFields['black_name'], 'Bob');
    expect(update.bodyFields['game_status'], '2');
    expect(update.bodyFields['win_id'], '2');
    expect(update.bodyFields['pgn'], contains('[Result "0-1"]'));
    expect(update.bodyFields['pgn'], contains('[TimeControl "300+0"]'));
    expect(update.bodyFields['pgn'], contains('[Speed "Classical"]'));
    expect(update.bodyFields['pgn'], isNot(contains('[PlayerSide ')));
    expect(update.bodyFields['pgn'], isNot(contains('[ChessnutGameId ')));
    expect(update.bodyFields['pgn'], contains('2. Nf3 Nc6 0-1'));
    expect(
      update.bodyFields['pgn'],
      isNot(contains('[ChessComSync "complete/webview"]')),
    );

    webViewAdapter.completeRecord = const {
      'pgn': '''
[Event "Live Chess"]
[Site "https://www.chess.com/game/live/456"]
[UTCDate "2026.08.26"]
[UTCTime "13:00:00"]
[White "Alice"]
[Black "Carol"]
[Result "*"]
[TimeControl "600+5"]

1. d4 d5 *
''',
    };
    webViewAdapter.currentFen =
        'rnbqkbnr/ppp1pppp/8/3p4/3P4/8/PPP1PPPP/RNBQKBNR w KQkq - 0 2';
    await tester.pump(const Duration(milliseconds: 950));
    await _pumpUntilCondition(
      tester,
      () =>
          requests
              .where((request) => request.url.path == '/api/uploadPgn')
              .length ==
          2,
      timeout: const Duration(seconds: 3),
      reason: 'second Chess.com game upload',
    );
    final secondUpload =
        requests.where((request) => request.url.path == '/api/uploadPgn').last;
    expect(secondUpload.bodyFields['black_name'], 'Carol');
    expect(
      secondUpload.bodyFields['pgn'],
      contains('https://www.chess.com/game/live/456'),
    );
  });

