      }
      return http.Response('not found', 404);
    });
    final webViewAdapter = _MutableChessComWebViewAdapter(
      'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1',
      players: const {'white': 'Alice', 'black': 'Bob'},
