    await tester.tap(find.text('Leave'));

    bool hasSnapshotSave() {
      return requests.any((request) =>
          request.method == 'POST' &&
          (request.url.path == '/api/uploadPgn' ||
              request.url.path == '/api/updatePgn') &&
          request.bodyFields['game_status'] == '1');
    }

    await _pumpUntilCondition(
      tester,
      hasSnapshotSave,
      timeout: const Duration(seconds: 3),
      reason: 'Chess.com snapshot save',
    );

    final upload = requests.lastWhere((request) =>
        request.method == 'POST' &&
        (request.url.path == '/api/uploadPgn' ||
            request.url.path == '/api/updatePgn') &&
        request.bodyFields['game_status'] == '1');
