    expect(upload.bodyFields['white_name'], 'Alice');
    expect(upload.bodyFields['black_name'], 'Bob');
    if (upload.url.path == '/api/uploadPgn') {
      expect(upload.bodyFields['play_mode'], 'chesscom');
    }
    expect(upload.bodyFields['game_status'], '1');
    expect(upload.bodyFields['win_id'], '0');
    expect(upload.bodyFields['game_step'], '1');
    final uploadedPgn = upload.bodyFields['pgn'] ?? '';
    expect(uploadedPgn, contains('[Result "*"]'));
    expect(uploadedPgn, isNot(contains('[ChessComSync ')));
    expect(uploadedPgn, isNot(contains('[CurrentFEN ')));
    expect(uploadedPgn.trim(), endsWith('1. e4 *'));
  });

