  testWidgets(
    'Android phone Analyze PGN landscape scrolls both columns independently',
    (WidgetTester tester) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.android;
      tester.view.physicalSize = const Size(844, 390);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(right: 48);
      tester.view.viewPadding = const FakeViewPadding(right: 48);
      try {
        await tester.pumpWidget(_testApp(initialScreen: 'Analysis'));
        await tester.pump(const Duration(seconds: 1));

        final layout = find.byKey(
          const ValueKey('analysis-entry-android-phone-landscape'),
        );
        final input = find.byKey(const ValueKey('analysis-pgn-input'));
        final rightPanel = find.byKey(
          const ValueKey('analysis-entry-right-scroll'),
        );
        expect(layout, findsOneWidget);
        expect(input, findsOneWidget);
        expect(rightPanel, findsOneWidget);

        await tester.enterText(
          input,
          List<String>.generate(80, (index) => '${index + 1}. e4 e5').join(' '),
        );
        await tester.pump();

        final outerScrollable =
            find.ancestor(of: layout, matching: find.byType(Scrollable)).first;
        final inputScrollable =
            find.descendant(of: input, matching: find.byType(Scrollable)).first;
        final rightScrollable = find
            .descendant(of: rightPanel, matching: find.byType(Scrollable))
            .first;
        final outerState = tester.state<ScrollableState>(outerScrollable);
        final inputState = tester.state<ScrollableState>(inputScrollable);
        final rightState = tester.state<ScrollableState>(rightScrollable);

        expect(outerState.position.maxScrollExtent, moreOrLessEquals(0));
        expect(inputState.position.maxScrollExtent, greaterThan(0));
        expect(rightState.position.maxScrollExtent, greaterThan(0));

        inputState.position.jumpTo(inputState.position.maxScrollExtent / 2);
        await tester.pump();
        final inputOffset = inputState.position.pixels;
        expect(inputOffset, greaterThan(0));
        expect(inputOffset, lessThan(inputState.position.maxScrollExtent));

        await tester.drag(rightPanel, const Offset(0, -120));
        await tester.pumpAndSettle();
        expect(rightState.position.pixels, greaterThan(0));

        await tester.drag(rightPanel, const Offset(0, 1000));
        await tester.pumpAndSettle();
        expect(rightState.position.pixels, moreOrLessEquals(0));
        expect(inputState.position.pixels, moreOrLessEquals(inputOffset));
        expect(outerState.position.pixels, moreOrLessEquals(0));
      } finally {
        debugDefaultTargetPlatformOverride = null;
        tester.view.resetPhysicalSize();
        tester.view.resetDevicePixelRatio();
        tester.view.resetPadding();
        tester.view.resetViewPadding();
      }
    },
  );

