          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': 1,
              'pgnList': [
                {
                  'id': 102,
                  's_id': 'empty-finished-share',
                  'pgn': 'https://api.chessnutech.com/pgn/empty-finished.pgn',
                  'white_name': 'Empty',
                  'black_name': 'Finished',
                  'play_time': 1715900400,
                  'play_mode': 'bot',
                  'win_id': 1,
                  'game_status': 2,
                  'game_step': 0,
                },
                {
                  'id': 101,
                  's_id': 'draft-share',
                  'pgn': 'https://api.chessnutech.com/pgn/draft.pgn',
                  'white_name': 'Draft',
                  'black_name': 'Opponent',
                  'play_time': 1715900300,
                  'play_mode': 'bot',
                  'win_id': 0,
                  'game_status': 1,
                  'game_step': 6,
                },
                {
                  'id': 99,
                  's_id': 'finished-share',
                  'pgn': 'https://api.chessnutech.com/pgn/finished.pgn',
                  'white_name': 'Alice',
                  'black_name': 'Bob',
                  'play_time': 1715900000,
                  'play_mode': 'bot',
                  'win_id': 2,
                  'game_status': 2,
                  'game_step': 4,
                },
              ],
            },
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/draft.pgn') {
        return http.Response(
          '[Event "Draft"]\n'
          '[White "Draft"]\n'
          '[Black "Opponent"]\n'
          '[Result "*"]\n'
          '[TimeControl "3+2"]\n\n'
          '1. e4 e5 *',
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/empty-finished.pgn') {
        return http.Response(
          '[Event "Empty Finished"]\n'
          '[White "Empty"]\n'
          '[Black "Finished"]\n'
          '[Result "1-0"]\n\n'
          '1-0',
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/finished.pgn') {
        return http.Response(finishedPgn, 200);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(_testApp(httpClient: client));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await tester.tap(find.text('Analysis'));
    await tester.pumpAndSettle();

    final lastGameEntry =
        find.byKey(const ValueKey('analysis-last-game-entry'));
    await tester.ensureVisible(lastGameEntry);
    await tester.pumpAndSettle();
    await tester.tap(lastGameEntry);
    await tester.pumpAndSettle();

    expect(find.text('Analysis board'), findsOneWidget);
    expect(find.byKey(const ValueKey('analysis-san-ply-3')), findsOneWidget);
    expect(
      requests.any((request) => request.url.path == '/api/getPgnList'),
      isTrue,
    );
  });

