  testWidgets('Maia3 move list waits for real Stockfish results', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final stockfishCompleter = Completer<void>();
    addTearDown(() {
      if (!stockfishCompleter.isCompleted) stockfishCompleter.complete();
    });
    final client = MockClient((request) async {
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' && request.url.path == '/api/uploadPgn') {
        return _uploadPgnResponse(pgnId: 9031, shareId: 'maia3-stockfish');
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/analysis/maia3/start') {
        return _maia3CompletedJobResponse();
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        positionAnalyzer: _DelayedPositionAnalyzer(stockfishCompleter),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _openAnalysisForPgn(
      tester,
      '[Event "Maia3 Stockfish Gate"]\n\n1. e4 e5 2. Nf3 Nc6 *',
    );

    final reviewButton =
        find.byKey(const ValueKey('analysis-maia3-human-review-button'));
    await tester.ensureVisible(reviewButton);
    await tester.pump(const Duration(milliseconds: 100));
    await tester.tap(reviewButton);
    await _pumpUntilFound(
      tester,
      find.byKey(const ValueKey('maia3-review-start-button')),
    );
    await tester.tap(find.byKey(const ValueKey('maia3-review-start-button')));
    await _pumpUntilFound(tester, find.text('Move likelihood'));
    await tester.ensureVisible(find.text('Moves'));
    await tester.pump(const Duration(milliseconds: 100));
    await tester.tap(find.text('Moves'));
    await tester.pump(const Duration(milliseconds: 100));

    final pendingSanFinder =
        find.byKey(const ValueKey('analysis-san-label-ply-1'));
    final pendingSan = tester.widget<localized.Text>(pendingSanFinder);
    expect(
      pendingSan.style?.color,
      Theme.of(tester.element(pendingSanFinder)).colorScheme.onSurface,
    );
    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      '--',
    );

    stockfishCompleter.complete();
    await tester.pumpAndSettle();

    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      isNot('--'),
    );
  });

