  testWidgets('Standard report waits for Stockfish before showing timeline', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final analysisCompleter = Completer<void>();
    await tester.pumpWidget(
      _testApp(positionAnalyzer: _DelayedPositionAnalyzer(analysisCompleter)),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await tester.tap(find.text('Analysis'));
    await tester.pumpAndSettle();
    await tester.enterText(
      find.byType(TextField).last,
      '[Event "Async"]\n\n1. e4 e5 2. Nf3 Nc6 *',
    );
    final startReviewButton = find.text('Start review').last;
    await tester.ensureVisible(startReviewButton);
    await tester.pumpAndSettle();
    await tester.tap(startReviewButton, warnIfMissed: false);
    await tester.pump(const Duration(milliseconds: 200));

    final pendingSan = tester.widget<localized.Text>(
      find.byKey(const ValueKey('analysis-san-label-ply-1')),
    );
    final pendingSanContext = tester.element(
      find.byKey(const ValueKey('analysis-san-label-ply-1')),
    );
    expect(pendingSan.style?.color,
        Theme.of(pendingSanContext).colorScheme.onSurface);
    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      '--',
    );

    final standardReportButton = find.byKey(
      const ValueKey('analysis-standard-report-button'),
    );
    await tester.ensureVisible(standardReportButton);
    await tester.pump(const Duration(milliseconds: 100));
    await tester.tap(standardReportButton);
    await tester.pump(const Duration(milliseconds: 200));

    expect(find.text('Stockfish analysis in progress'), findsOneWidget);
    expect(find.text('Evaluation timeline'), findsNothing);

    analysisCompleter.complete();
    await tester.pumpAndSettle();

    expect(find.text('Stockfish analysis in progress'), findsNothing);
    expect(find.text('Evaluation timeline'), findsOneWidget);
    expect(find.byKey(const ValueKey('eval-point-1')), findsOneWidget);
    expect(find.byKey(const ValueKey('eval-point-2')), findsOneWidget);
    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      isNot('--'),
    );
    final analyzedSan = tester.widget<localized.Text>(
      find.byKey(const ValueKey('analysis-san-label-ply-1')),
    );
    final analyzedSanContext = tester.element(
      find.byKey(const ValueKey('analysis-san-label-ply-1')),
    );
    expect(analyzedSan.style?.color,
        isNot(Theme.of(analyzedSanContext).colorScheme.onSurface));
  });

