          request.url.path == '/api/uploadPgnList') {
        uploadedPgn = request.bodyFields['pgnList'] ?? '';
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': 1}),
          200,
        );
      }
      if (request.method == 'POST' && request.url.path == '/api/getPgnList') {
        return _pgnListResponse(
          uploadedPgn.isEmpty
              ? const []
              : [
                  _analysisPgnRecord(
                    id: 7126,
                    shareId: 'record-import',
                    pgnUrl: 'https://api.chessnutech.com/pgn/record-import.pgn',
                    whiteName: 'Record Import',
                    blackName: 'Record Archive',
                    gameStep: 4,
                  ),
                ],
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() ==
              'https://api.chessnutech.com/pgn/record-import.pgn') {
        return http.Response(uploadedPgn, 200);
      }
      return http.Response('not found', 404);
    });
    await tester.pumpWidget(
      _testApp(
        httpClient: client,
        analysisPgnFileLoader: () async {
          fileLoaderCalls += 1;
          return pgn;
        },
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _openGameRecordsFromHome(tester);
    await tester.tap(find.byKey(const ValueKey('game-record-import-menu')));
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('game-record-import-pgn-menu')));
    await _pumpUntilFound(
      tester,
      find.text('White: Record Import / Black: Record Archive'),
    );

    expect(fileLoaderCalls, 1);
    expect(uploadedPgn, pgn);
    expect(find.text('Analysis board'), findsNothing);
    expect(find.text('Imported 1 games.'), findsOneWidget);
  });

