  testWidgets('Analysis depth is persisted and regenerates the report', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    const pgn = '[Event "Configurable Depth"]\n\n1. e4 e5 2. Nf3 Nc6 *';
    final analyzer = _RecordingPositionAnalyzer();
    await tester.pumpWidget(_testApp(positionAnalyzer: analyzer));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _openAnalysisForPgn(tester, pgn);
    await _pumpUntilFound(tester, find.text('Report ready'));

    final initialCalls = analyzer.calls.length;
    expect(analyzer.depths, everyElement(16));

    final depthMenu =
        find.byKey(const ValueKey('standard-analysis-depth-menu'));
    await tester.ensureVisible(depthMenu);
    await tester.tap(depthMenu);
    await tester.pumpAndSettle();
    await tester.tap(find.text('20').last);
    await _pumpUntilCondition(
      tester,
      () =>
          analyzer.calls.length > initialCalls &&
          analyzer.depths.skip(initialCalls).every((depth) => depth == 20),
      timeout: const Duration(seconds: 5),
      reason: 'depth change report regeneration',
    );
    expect(
      AppSharedPreferences.get<int>(AppSettingKeys.standardAnalysisDepth),
      20,
    );

    final callsAfterDepthChange = analyzer.calls.length;
    final regenerateButton =
        find.byKey(const ValueKey('standard-analysis-regenerate-button'));
    await tester.ensureVisible(regenerateButton);
    await tester.tap(regenerateButton);
    await _pumpUntilCondition(
      tester,
      () => analyzer.calls.length > callsAfterDepthChange,
      timeout: const Duration(seconds: 5),
      reason: 'manual report regeneration',
    );
    expect(
      analyzer.depths.skip(callsAfterDepthChange),
      everyElement(20),
    );
  });

