    await tester.tap(find.text('Spend 100 points'));
    await tester.pumpAndSettle();
    expect(find.text('Grandeur Analysis'), findsOneWidget);

    final walletCalls = requests
        .where((request) => request.url.path == '/api/wallet/balance')
        .length;
    final consumeCalls = requests
        .where((request) => request.url.path == '/api/wallet/consumePoints')
        .length;
    final pushCalls = requests
        .where((request) => request.url.path == '/api/v3/grandeur/push')
        .length;
    expect(walletCalls, greaterThan(walletBaseline));
    expect(consumeCalls - consumeBaseline, 0);
    expect(pushCalls - pushBaseline, 1);

    await tester.tap(
      find.byKey(const ValueKey('analysis-grandeur-back-button')).first,
    );
    await tester.pumpAndSettle();
    await tester.ensureVisible(grandeurButton);
    await tester.pumpAndSettle();
    await tester.tap(grandeurButton);
    await tester.pumpAndSettle();

    expect(find.text('Spend 100 points?'), findsNothing);
    expect(find.text('Grandeur Analysis'), findsOneWidget);
    expect(
      requests.where(
        (request) => request.url.path == '/api/wallet/consumePoints',
      ),
      hasLength(consumeCalls),
    );
    expect(
      requests.where((request) => request.url.path == '/api/v3/grandeur/push'),
      hasLength(pushCalls),
    );
  });

