  testWidgets('Cached Grandeur-only reports reopen without wallet charge', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    const pgn = '[Event "Grandeur Only"]\n\n'
        '1. e4 e5 2. Nf3 Nc6 1-0';
    final cacheKey = gameAnalysisReportCacheKeyForPgn(pgn);
    final preferencesStore = MemoryAppPreferencesStore(
      StoredAppPreferences(
        analysisReports: {
          cacheKey: const GameAnalysisReportCacheEntry(
            pgn: pgn,
            grandeurReport: GrandeurAnalysisResult(
              analysisId: 'cached-grandeur-only',
              summary: [
                'Backend overall summary says White converted the center bind.',
              ],
              moves: [
                GrandeurMoveExplanation(
                  ply: 1,
                  san: 'e4',
                  tag: 'Best',
                  commentary: 'It creates useful space.',
                  purpose: 'Take the center.',
                  why: 'It creates useful space.',
                  betterMove: '',
                  classification: 'Best',
                ),
              ],
            ),
          ),
        },
      ),
    );
    final requests = <http.Request>[];
    final client = MockClient((request) async {
      requests.add(request);
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(_loginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getPgnList') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'total_page': 1, 'pgnList': []},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/wallet/balance') {
        return _walletBalanceResponse(balance: 240);
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/wallet/consumePoints') {
        return http.Response('unexpected consume', 500);
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/grandeur/push') {
        return http.Response('unexpected push', 500);
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/grandeur/get') {
        return http.Response('unexpected get', 500);
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _testApp(httpClient: client, appPreferencesStore: preferencesStore),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _openAnalysisForPgn(tester, pgn);
    final grandeurButton = find.byKey(
      const ValueKey('analysis-grandeur-review-button'),
    );
    final walletBaseline = requests
        .where((request) => request.url.path == '/api/wallet/balance')
        .length;
    final consumeBaseline = requests
        .where((request) => request.url.path == '/api/wallet/consumePoints')
        .length;
    final pushBaseline = requests
        .where((request) => request.url.path == '/api/v3/grandeur/push')
        .length;
    await tester.ensureVisible(grandeurButton);
    await tester.pumpAndSettle();
    await tester.tap(grandeurButton);
    await tester.pumpAndSettle();

    expect(find.text('Spend 100 points?'), findsNothing);
    expect(find.text('Grandeur Analysis'), findsOneWidget);
    await tester.ensureVisible(
      find.byKey(const ValueKey('analysis-grandeur-summary-button')),
    );
    await tester.pumpAndSettle();
    await tester.tap(
      find.byKey(const ValueKey('analysis-grandeur-summary-button')),
    );
    await tester.pumpAndSettle();

    expect(
      find.text(
        'Backend overall summary says White converted the center bind.',
      ),
      findsWidgets,
    );
    expect(
      requests.where((request) => request.url.path == '/api/wallet/balance'),
      hasLength(walletBaseline),
    );
    expect(
      requests.where(
        (request) => request.url.path == '/api/wallet/consumePoints',
      ),
      hasLength(consumeBaseline),
    );
    expect(
      requests.where((request) => request.url.path == '/api/v3/grandeur/push'),
      hasLength(pushBaseline),
    );
  });

