    );
    expect(find.text('Voice on'), findsNothing);
    expect(find.byTooltip('Mute Grandeur voice'), findsNothing);
    expect(find.text('Deep analyst'), findsNothing);
    expect(find.byKey(const ValueKey('grandeur-speech-card')), findsNothing);
    expect(
      find.byKey(const ValueKey('grandeur-generation-hint')),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('grandeur-generation-hint')),
        matching: find.textContaining('coach report is still being generated'),
      ),
      findsOneWidget,
    );
    expect(find.text('Replay'), findsNothing);
    expect(
      find.byKey(const ValueKey('grandeur-generation-progress')),
      findsOneWidget,
    );
    expect(find.textContaining('You can leave this page'), findsWidgets);
    expect(find.textContaining('Grandeur would'), findsNothing);
    expect(
      find.textContaining('coach report is still being generated'),
      findsWidgets,
    );
    expect(find.text('Purpose'), findsNothing);
    expect(find.text('Why it matters'), findsNothing);
    expect(find.text('Better plan'), findsNothing);
    expect(find.byKey(const ValueKey('grandeur-coach-picker')), findsNothing);

    await _pumpUntilCondition(
      tester,
      () => find
          .byKey(const ValueKey('grandeur-speech-card'))
          .evaluate()
          .isNotEmpty,
      timeout: const Duration(seconds: 10),
      reason: 'Grandeur speech card after report completes',
    );
    expect(
        find.byKey(const ValueKey('grandeur-generation-hint')), findsNothing);
    expect(find.byKey(const ValueKey('coach-avatar-deep')), findsWidgets);
    expect(find.byTooltip('Mute Grandeur voice'), findsOneWidget);
    expect(
      find.byKey(const ValueKey('analysis-commentary-voice-gender')),
      findsOneWidget,
    );
    expect(find.textContaining('center plan'), findsWidgets);
    expect(
      find.descendant(
        of: find.byKey(const ValueKey('grandeur-speech-card')),
        matching: find.text('1. e4'),
      ),
      findsOneWidget,
    );

    await tester.pump(const Duration(milliseconds: 500));
    final syncedSpeech = find.byWidgetPredicate((widget) {
      final key = widget.key;
      return key is ValueKey<String> &&
          key.value.startsWith('grandeur-speech-');
    });
    final colorTransitionText = find.descendant(
      of: syncedSpeech,
      matching: find.byWidgetPredicate(
        (widget) => widget is Text && widget.textSpan != null,
      ),
    );
    expect(colorTransitionText, findsOneWidget);
    expect(
      find.descendant(of: syncedSpeech, matching: find.byType(Stack)),
      findsNothing,
    );
    final transitionSpan =
        tester.widget<Text>(colorTransitionText).textSpan as TextSpan;
    expect(transitionSpan.children, isNotNull);
    expect(transitionSpan.children!.length, greaterThanOrEqualTo(2));

    await tester.ensureVisible(find.byTooltip('Mute Grandeur voice'));
    await tester.pumpAndSettle();
    await tester.tap(find.byTooltip('Mute Grandeur voice'));
    await tester.pumpAndSettle();
    expect(find.text('Voice muted'), findsNothing);
    expect(find.byTooltip('Unmute Grandeur voice'), findsOneWidget);

    await tester.pump(const Duration(seconds: 8));
    await tester.pumpAndSettle();
  });

