        );

        final firstFen = tester.widget<InteractiveChessBoard>(board).initialFen;
        final speechBubble = tester.widget(
          find.byWidgetPredicate((widget) {
            final key = widget.key;
            return key is ValueKey<String> &&
                key.value.startsWith('grandeur-bubble-');
          }),
        );
        final onPlaybackComplete =
            (speechBubble as dynamic).onPlaybackComplete as VoidCallback?;
        expect(onPlaybackComplete, isNotNull);
        onPlaybackComplete!.call();
        await tester.pump();
        expect(
          tester.widget<InteractiveChessBoard>(board).initialFen,
          isNot(firstFen),
        );

        await tester.tap(autoPlayButton);
        await tester.pump();
        expect(
          find.byTooltip('Play automatic commentary'),
