        );

        debugDefaultTargetPlatformOverride = TargetPlatform.iOS;
        await tester.pump();
        expect(
          find.byKey(const ValueKey('grandeur-landscape-layout')),
          findsOneWidget,
        );
        expect(
          tester.getRect(board).right,
          lessThanOrEqualTo(
