    await _chooseGrandeurStyle(tester);
    expect(find.text('Spend 100 points?'), findsOneWidget);
    expect(find.text('Current balance: 240'), findsOneWidget);
    expect(find.text('Balance after review: 140'), findsOneWidget);
    expect(find.text('Grandeur Analysis'), findsNothing);

    await tester.tap(find.text('Cancel'));
