    final cachedReports = (await preferencesStore.read()).analysisReports;
    expect(
      cachedReports.values.any((entry) => entry.grandeurStyleId == 'rapid'),
      isTrue,
    );
    expect(find.text('Grandeur Analysis'), findsOneWidget);
  });

