  testWidgets('Grandeur move list waits for real Stockfish results', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final stockfishCompleter = Completer<void>();
    addTearDown(() {
      if (!stockfishCompleter.isCompleted) stockfishCompleter.complete();
    });
    await tester.pumpWidget(
      _testApp(
        positionAnalyzer: _DelayedPositionAnalyzer(stockfishCompleter),
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);
    await _openAnalysisForPgn(
      tester,
      '[Event "Grandeur Stockfish Gate"]\n\n1. e4 e5 2. Nf3 Nc6 *',
    );

    final grandeurButton = find.byKey(
      const ValueKey('analysis-grandeur-review-button'),
    );
    await tester.ensureVisible(grandeurButton);
    await tester.pump(const Duration(milliseconds: 100));
    await tester.tap(grandeurButton);
    await _pumpUntilFound(
      tester,
      find.byKey(const ValueKey('grandeur-style-picker')),
    );
    await tester.tap(find.text('Deep analyst'));
    await _pumpUntilFound(tester, find.text('Spend 100 points?'));
    await tester.tap(find.text('Spend 100 points'));
    await _pumpUntilFound(tester, find.text('Grandeur Analysis'));

    final pendingSanFinder =
        find.byKey(const ValueKey('analysis-san-label-ply-1'));
    final pendingSan = tester.widget<localized.Text>(pendingSanFinder);
    expect(
      pendingSan.style?.color,
      Theme.of(tester.element(pendingSanFinder)).colorScheme.onSurface,
    );
    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      '--',
    );

    stockfishCompleter.complete();
    await tester.pumpAndSettle();

    expect(
      tester
          .widget<localized.Text>(
            find.byKey(const ValueKey('analysis-eval-label-ply-1')),
          )
          .data,
      isNot('--'),
    );
  });

