  testWidgets('Chess clock supports pre-start side selection', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final clockSwitchService = _RecordingClockSwitchService();

    await tester.pumpWidget(
      _screenTestApp(
        ChessClockScreen(
          onNavigate: (_) {},
          config: const OtbGameConfig(timeMinutes: 1, incrementSeconds: 3),
          clockSwitchService: clockSwitchService,
        ),
      ),
    );

    double whiteTop() =>
        tester.getTopLeft(find.byKey(const ValueKey('clock-face-white'))).dy;
    double blackTop() =>
        tester.getTopLeft(find.byKey(const ValueKey('clock-face-black'))).dy;

    expect(whiteTop(), greaterThan(blackTop()));

    await tester.tap(find.byKey(const ValueKey('clock-face-white')));
    await tester.pump();
    expect(whiteTop(), lessThan(blackTop()));

    await tester.tap(find.byKey(const ValueKey('clock-face-white')));
    await tester.pump();
    expect(whiteTop(), greaterThan(blackTop()));

    clockSwitchService.emitSwitch(ChessClockSide.right);
    await tester.pump();
    expect(whiteTop(), lessThan(blackTop()));

    await tester.tap(find.text('Start'));
    await tester.pump();
    await tester.tap(find.byKey(const ValueKey('clock-face-white')));
    await tester.pump();
    expect(whiteTop(), lessThan(blackTop()));

    await tester.tap(find.text('Pause'));
    await tester.pump();
    await tester.tap(find.byKey(const ValueKey('clock-face-black')));
    await tester.pump();
    expect(whiteTop(), lessThan(blackTop()));
  });

