[Site "Chessnut"]
[White "LC0 training"]
[Black "Chessnut Player"]
[Result "*"]
[WhiteTime "487"]
[BlackTime "10"]

1. e4 e5 2. Nf3 *
''';

    await tester.pumpWidget(
      _screenTestApp(
        GameRoomScreen(
          onNavigate: (_) {},
          mode: GameLaunchMode.bot,
          botConfig: const BotGameConfig.defaultConfig().copyWith(
            playerSide: BotPlayerSide.black,
            resumePgn: resumePgn,
          ),
          botEngine: const _ScriptedBotEngineAdapter([]),
          positionAnalyzer: const _NoopPositionAnalyzer(),
        ),
      ),
    );
    await tester.pumpAndSettle();

    String playerClock() => tester
        .widget<Text>(
          find.descendant(
            of: find.byKey(const ValueKey('game-clock-bottom-time')),
            matching: find.byType(Text),
          ),
        )
        .data!;

    expect(
      find.byKey(const ValueKey('game-clock-bottom-source')),
      findsOneWidget,
    );
    expect(find.text('Your turn / legal moves only'), findsOneWidget);
    final beforeReview = playerClock();

    await tester.tap(find.byKey(const ValueKey('game-pgn-white-1')));
    await tester.pump();

    expect(find.text('Your turn / legal moves only'), findsOneWidget);
    expect(playerClock(), beforeReview);

    await tester.pump(const Duration(seconds: 2));

    expect(find.text('Your turn / legal moves only'), findsOneWidget);
    expect(playerClock(), isNot(beforeReview));
  });

