  testWidgets('Android narrow Puzzle Storm keeps flip action visible', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.android;
    tester.view.devicePixelRatio = 1;
    addTearDown(() => debugDefaultTargetPlatformOverride = null);
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway(
      boardModel: PhysicalBoardModel.move,
    );
    await gateway.connect();
    addTearDown(gateway.dispose);

    for (final width in <double>[320, 360, 390, 430]) {
      tester.view.physicalSize = Size(width, 844);
      final client = MockClient((request) async {
        if (request.method == 'GET' &&
            request.url.toString() == 'http://puzzle.chessnutech.com/random') {
          return http.Response(
            jsonEncode({
              'id': 808,
              'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
              'move': 'f1c1',
              'lichess_id': 'narrowStorm$width',
              'tags': 'fork',
            }),
            200,
          );
        }
        return http.Response('not found', 404);
      });

      await tester.pumpWidget(
        _screenTestApp(
          PuzzleStormScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: client),
            boardGateway: gateway,
          ),
        ),
      );
      await tester.pumpAndSettle();

      final toolbar = find.byKey(const ValueKey('puzzle-storm-narrow-toolbar'));
      final flip = find.byKey(const ValueKey('puzzle-storm-flip-board'));
      expect(toolbar, findsOneWidget, reason: 'width=$width');
      expect(flip, findsOneWidget, reason: 'width=$width');
      expect(
        find.descendant(
          of: toolbar,
          matching: find.byKey(
            const ValueKey('puzzle-storm-voice-moves-toggle'),
          ),
        ),
        findsOneWidget,
        reason: 'width=$width',
      );
      final toolbarRect = tester.getRect(toolbar);
      final flipRect = tester.getRect(flip);
      expect(toolbarRect.left, greaterThanOrEqualTo(0), reason: 'width=$width');
      expect(toolbarRect.right, lessThanOrEqualTo(width),
          reason: 'width=$width');
      expect(flipRect.width, greaterThanOrEqualTo(44), reason: 'width=$width');
      expect(flipRect.height, greaterThanOrEqualTo(44), reason: 'width=$width');
      expect(flipRect.left, greaterThanOrEqualTo(toolbarRect.left),
          reason: 'width=$width');
      expect(flipRect.right, lessThanOrEqualTo(toolbarRect.right),
          reason: 'width=$width');
      expect(flipRect.top, greaterThanOrEqualTo(toolbarRect.top),
          reason: 'width=$width');
      expect(flipRect.bottom, lessThanOrEqualTo(toolbarRect.bottom),
          reason: 'width=$width');
      expect(
        tester
            .widget<localized.IconButton>(flip)
            .style
            ?.backgroundColor
            ?.resolve(const <WidgetState>{}),
        Theme.of(tester.element(flip)).colorScheme.primary,
        reason: 'width=$width',
      );
      expect(tester.takeException(), isNull, reason: 'width=$width');

      await tester.pumpWidget(
        _screenTestApp(
          PuzzleStormScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: client),
          ),
        ),
      );
      await tester.pumpAndSettle();

      final inlineToolbar =
          find.byKey(const ValueKey('puzzle-storm-narrow-toolbar'));
      final title = find.byKey(const ValueKey('puzzle-storm-title'));
      expect(inlineToolbar, findsOneWidget, reason: 'width=$width');
      expect(title, findsOneWidget, reason: 'width=$width');
      expect(
        find.descendant(
          of: inlineToolbar,
          matching: find.byKey(
            const ValueKey('puzzle-storm-voice-moves-toggle'),
          ),
        ),
        findsNothing,
        reason: 'width=$width',
      );
      final inlineToolbarRect = tester.getRect(inlineToolbar);
      final titleRect = tester.getRect(title);
      expect(
        (inlineToolbarRect.center.dy - titleRect.center.dy).abs(),
        lessThan(1),
        reason: 'width=$width',
      );
      expect(inlineToolbarRect.right, lessThanOrEqualTo(width),
          reason: 'width=$width');
      expect(tester.takeException(), isNull, reason: 'width=$width');
    }
    debugDefaultTargetPlatformOverride = null;
  });

