    final lineScroll = find.byKey(
      const ValueKey('board-analyzer-candidate-line-1'),
    );
    for (final segment in const [
      'e4',
      'e5',
      'Nf3',
      'Nc6',
      'Bb5',
      'a6',
      'Ba4',
      'Nf6',
      'O-O',
      'Be7',
      'Re1',
      'b5',
      'Bb3',
      'd6',
      'c3',
      'O-O',
    ]) {
      expect(
        find.descendant(of: lineScroll, matching: find.text(segment)),
        findsWidgets,
      );
    }
    expect(
      tester.widget<SingleChildScrollView>(lineScroll).scrollDirection,
      Axis.horizontal,
    );
    expect(
      find.descendant(of: lineScroll, matching: find.text('+1.00')),
      findsNothing,
    );
    expect(
      find.descendant(of: candidate, matching: find.text('+1.00')),
      findsOneWidget,
    );
