    await tester.drag(lineScroll, const Offset(-180, 0));
    await tester.pumpAndSettle();
    final lineScrollable = find.descendant(
      of: lineScroll,
      matching: find.byType(Scrollable),
    );
    expect(
      tester.state<ScrollableState>(lineScrollable).position.pixels,
      greaterThan(0),
    );
    expect(tester.getCenter(find.text('+1.00')).dx, closeTo(scoreXBefore, 0.1));
    await tester.drag(lineScroll, const Offset(1000, 0));
    await tester.pumpAndSettle();
    await tester.tap(
      find.byKey(
        const ValueKey('board-analyzer-candidate-1-san-0'),
      ),
    );
    await tester.pumpAndSettle();

    final fenInput = tester.widget(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
    ) as dynamic;
    expect(fenInput.controller?.text, contains('4P3'));
    expect(
      gateway.writes.any(
        (command) => listEquals(
          command,
          ChessnutLedCodec.ledCommandFromSquares({'e2', 'e4'}),
        ),
      ),
      isTrue,
    );
  });

