  testWidgets('Board analyzer loads a custom FEN and rejects invalid FEN', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final analyzer = _RecordingPositionAnalyzer();
    await tester.pumpWidget(_testApp(positionAnalyzer: analyzer));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await tester.tap(find.text('Practice'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Board analyzer'),
      220,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Board analyzer'));
    await tester.pumpAndSettle();

    const customFen = '8/8/8/8/4k3/8/4K3/8 w - - 0 1';
    await tester.scrollUntilVisible(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      260,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.enterText(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      customFen,
    );
    await tester.tap(find.text('Analyze FEN'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.last, contains('4k3'));
    expect(find.byKey(const ValueKey('square-e4')), findsOneWidget);

    await tester.enterText(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      'position fen $customFen moves e2e4',
    );
    await tester.tap(find.text('Analyze FEN'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.last, customFen);
    expect(find.text('This FEN is not legal.'), findsNothing);

    await tester.enterText(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      'FEN: 8/8/8/8/4k3/8/4K3/8 w - -',
    );
    await tester.tap(find.text('Analyze FEN'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.last, customFen);
    expect(find.text('This FEN is not legal.'), findsNothing);

    const boardOnlyFen = '8/8/8/8/4k3/8/4K3/8';
    await tester.enterText(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      boardOnlyFen,
    );
    await tester.tap(find.text('Analyze FEN'));
    await tester.pumpAndSettle();

    expect(analyzer.calls.last, customFen);
    expect(find.text('This FEN is not legal.'), findsNothing);

    await tester.enterText(
      find.byKey(const ValueKey('board-analyzer-fen-input')),
      'not a fen',
    );
    await tester.tap(find.text('Analyze FEN'));
    await tester.pumpAndSettle();

    expect(find.text('This FEN is not legal.'), findsOneWidget);
  });

