  testWidgets(
    'Puzzle Storm ignores intermediate Move FENs while loading the next puzzle',
    (WidgetTester tester) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.windows;
      addTearDown(() => debugDefaultTargetPlatformOverride = null);
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = MemoryPhysicalBoardGateway(
        boardModel: PhysicalBoardModel.move,
      );
      await gateway.connect();
      addTearDown(gateway.dispose);
      const firstFen = '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1';
      const firstMoveFen = '6k1/5ppp/8/8/8/8/5PPP/2R3K1 b - - 1 1';
      const nextFen = '8/8/8/3k4/8/8/3Q4/3K4 w - - 0 1';
      const intermediateFen = '8/8/8/3k4/8/8/8/3K4';
      final nextPuzzleResponse = Completer<http.Response>();
      var requestCount = 0;
      final client = MockClient((request) async {
        if (request.method == 'GET' &&
            request.url.toString() == 'http://puzzle.chessnutech.com/random') {
          requestCount += 1;
          if (requestCount == 1) {
            return http.Response(
              jsonEncode({
                'id': 901,
                'fen': firstFen,
                'move': 'f1c1',
                'lichess_id': 'stormMoveFirst',
                'tags': 'fork',
              }),
              200,
            );
          }
          return nextPuzzleResponse.future;
        }
        return http.Response('not found', 404);
      });

      await tester.pumpWidget(
        _screenTestApp(
          PuzzleStormScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: client),
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              fenDelayMs: 0,
              moveRestoreDelayMs: 100,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      gateway.writes.clear();

      gateway.addBoardFen(firstFen);
      await tester.pump();
      gateway.addBoardFen(firstMoveFen);
      await tester.pump();
      expect(
        _textByKey(tester, const ValueKey('puzzle-storm-solved-count')),
        '1',
      );

      await tester.pump(const Duration(milliseconds: 100));
      gateway.addBoardFen(intermediateFen);
      await tester.pump(const Duration(milliseconds: 150));
      expect(
        gateway.writes.where(
          (write) => listEquals(
            write,
            ChessnutMoveBoardCodec.setBoardCommand(firstFen),
          ),
        ),
        isEmpty,
      );

      nextPuzzleResponse.complete(
        http.Response(
          jsonEncode({
            'id': 902,
            'fen': nextFen,
            'move': 'd2d3',
            'lichess_id': 'stormMoveNext',
            'tags': 'fork middlegame',
          }),
          200,
        ),
      );
      await tester.pumpAndSettle();
      gateway.addBoardFen(intermediateFen);
      await tester.pump(const Duration(milliseconds: 150));
      expect(
        gateway.writes.where(
          (write) => listEquals(
            write,
            ChessnutMoveBoardCodec.setBoardCommand(nextFen),
          ),
        ),
        hasLength(1),
      );
      debugDefaultTargetPlatformOverride = null;
    },
  );

  testWidgets(
    'Puzzle Storm judges backend move and rewards only after solving',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      var solvedCount = 0;
      final requests = <http.Request>[];
      final client = MockClient((request) async {
        requests.add(request);
        if (request.method == 'GET' &&
            request.url.toString() == 'http://puzzle.chessnutech.com/random') {
          return http.Response(
            jsonEncode({
              'id': requests
                  .where(
                    (entry) =>
                        entry.url.toString() ==
                        'http://puzzle.chessnutech.com/random',
                  )
                  .length,
              'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
              'move': 'f1c1',
              'lichess_id': 'storm1234',
              'tags': 'backRankMate fork',
            }),
            200,
          );
        }
        return http.Response('not found', 404);
      });

      await tester.pumpWidget(
        _screenTestApp(
          PuzzleStormScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: client),
            onPuzzleSolved: () => solvedCount += 1,
          ),
        ),
      );
      await tester.pumpAndSettle();

      expect(solvedCount, 0);
      expect(find.byKey(const ValueKey('hint-square-f1')), findsNothing);
      expect(find.byKey(const ValueKey('hint-square-c1')), findsNothing);

      await tester.tap(find.byTooltip('Hint'));
      await tester.pump();

      expect(find.byKey(const ValueKey('hint-square-f1')), findsOneWidget);
      expect(find.byKey(const ValueKey('hint-square-c1')), findsOneWidget);

      var board = tester.widget<InteractiveChessBoard>(
        find.byType(InteractiveChessBoard).first,
      );
      board.onMove?.call(
        _testMoveFromFen(
          '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
          'f1e1',
        ),
      );
      await tester.pump();

      final e1AfterWrong = tester.widget<Semantics>(
        find.byKey(const ValueKey('square-e1')),
      );
      expect(e1AfterWrong.properties.label, contains('wr'));
      expect(find.text('Try again: follow the highlighted board move.'),
          findsOneWidget);
      expect(solvedCount, 0);

      await tester.pump(const Duration(milliseconds: 700));
      final f1AfterReset = tester.widget<Semantics>(
        find.byKey(const ValueKey('square-f1')),
      );
      expect(f1AfterReset.properties.label, contains('wr'));

      board = tester.widget<InteractiveChessBoard>(
        find.byType(InteractiveChessBoard).first,
      );
      board.onMove?.call(
        _testMoveFromFen(
          '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
          'f1c1',
        ),
      );
      await tester.pump();

      final c1AfterCorrect = tester.widget<Semantics>(
        find.byKey(const ValueKey('square-c1')),
      );
      expect(c1AfterCorrect.properties.label, contains('wr'));
      expect(find.text('Puzzle solved'), findsOneWidget);
      expect(find.byKey(const ValueKey('puzzle-empty-board')), findsNothing);
      expect(find.byType(InteractiveChessBoard), findsNothing);
      expect(solvedCount, 1);

      await tester.pump(const Duration(milliseconds: 300));
      final c1BeforeClear = tester.widget<Semantics>(
        find.byKey(const ValueKey('square-c1')),
      );
      final f1BeforeClear = tester.widget<Semantics>(
        find.byKey(const ValueKey('square-f1')),
      );
      expect(c1BeforeClear.properties.label, contains('wr'));
      expect(f1BeforeClear.properties.label, contains('empty'));
      expect(find.text('Puzzle solved'), findsOneWidget);
      expect(find.byKey(const ValueKey('puzzle-empty-board')), findsNothing);

      await tester.pump(const Duration(milliseconds: 400));
      expect(find.byKey(const ValueKey('puzzle-empty-board')), findsOneWidget);
      await tester.pump(const Duration(milliseconds: 500));
      await tester.pumpAndSettle();
      expect(
        requests
            .where(
              (request) =>
                  request.url.toString() ==
                  'http://puzzle.chessnutech.com/random',
            )
            .length,
        2,
      );
    },
  );

