  testWidgets('Puzzle Storm syncs answer to physical board LEDs and FEN', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    await gateway.connect();
    addTearDown(gateway.dispose);
    var solvedCount = 0;
    final client = MockClient((request) async {
      if (request.method == 'GET' &&
          request.url.toString() == 'http://puzzle.chessnutech.com/random') {
        return http.Response(
          jsonEncode({
            'id': 808,
            'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
            'move': 'f1c1',
            'lichess_id': 'storm1234',
            'tags': 'backRankMate fork',
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _screenTestApp(
        PuzzleStormScreen(
          onNavigate: (_) {},
          apiClient: ChessnutApiClient(httpClient: client),
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(fenDelayMs: 0),
          onPuzzleSolved: () => solvedCount += 1,
        ),
      ),
    );
    await tester.pumpAndSettle();

    final answerLedCommand = ChessnutMoveLedCodec.commandFromSquares({
      'f1': ChessnutMoveLedColor.green,
      'c1': ChessnutMoveLedColor.green,
    }).toString();
    expect(
      gateway.writes.any(
        (command) =>
            command.toString() ==
            ChessnutMoveBoardCodec.setBoardCommand(
              '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
            ).toString(),
      ),
      isTrue,
    );
    expect(
      gateway.writes.any((command) => command.toString() == answerLedCommand),
      isFalse,
    );

    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await tester.pump();

    await tester.tap(find.byTooltip('Hint'));
    await tester.pump();

    expect(
      gateway.writes.any((command) => command.toString() == answerLedCommand),
      isTrue,
    );

    final move = dc.NormalMove.fromUci('f1c1');
    final (afterMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(move);
    gateway.addBoardFen(afterMove.board.fen);
    await tester.pump();

    expect(solvedCount, 1);
    expect(
      gateway.writes.any(
        (command) =>
            command.toString() == ChessnutMoveLedCodec.offCommand().toString(),
      ),
      isTrue,
    );
    await tester.pump(const Duration(milliseconds: 1200));
    await tester.pumpAndSettle();
  });

