          request.url.toString() == 'http://puzzle.chessnutech.com/random') {
        return http.Response(
          jsonEncode({
            'id': 809,
            'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
            'move': 'f1c1',
            'lichess_id': 'stormSetup',
            'tags': 'backRankMate',
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _screenTestApp(
        PuzzleStormScreen(
          onNavigate: (_) {},
          apiClient: ChessnutApiClient(httpClient: client),
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(fenDelayMs: 0),
          onPuzzleSolved: () => solvedCount += 1,
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(
      find.text('Set up the physical board to match this puzzle position.'),
      findsOneWidget,
    );
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({
            'g8',
            'f7',
            'g7',
            'h7',
            'f2',
            'g2',
            'h2',
            'f1',
            'g1',
          }),
        ),
      ),
      isTrue,
    );

    final move = dc.NormalMove.fromUci('f1c1');
    final (afterMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(move);
    gateway.addBoardFen(afterMove.board.fen);
    await tester.pump();

    expect(solvedCount, 0);
    expect(find.text('Puzzle solved'), findsNothing);
    expect(
      find.text('Set up the physical board to match this puzzle position.'),
      findsOneWidget,
    );
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({'c1', 'f1'}),
        ),
      ),
      isTrue,
    );

