      find.text('Set up the physical board to match this puzzle position.'),
      findsNothing,
    );
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({}),
        ),
      ),
      isTrue,
    );

