    await tester.pump();

    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({'f1'}),
        ),
      ),
      isTrue,
    );

    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await tester.pump();
    gateway.writes.clear();

    final wrongMove = dc.NormalMove.fromUci('f1e1');
    final (afterWrongMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(wrongMove);
    gateway.addBoardFen(afterWrongMove.board.fen);
    await tester.pump();

    expect(solvedCount, 0);
    expect(find.text('Try again: follow the highlighted board move.'),
        findsOneWidget);
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({'e1', 'f1'}),
        ),
