      isTrue,
    );

    await tester.pump(const Duration(milliseconds: 700));
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await tester.pump();

    gateway.addBoardFen(afterMove.board.fen);
    await tester.pump();

    expect(solvedCount, 1);
    expect(find.text('Puzzle solved'), findsOneWidget);
  });

