          onNavigate: (_) {},
          apiClient: ChessnutApiClient(httpClient: client),
          boardGateway: gateway,
          boardSettings: const BoardSettingsState(fenDelayMs: 0),
          onPuzzleSolved: () => solvedCount += 1,
        ),
      ),
    );
    await tester.pumpAndSettle();

    final initialSetupCommand = ChessnutLedCodec.ledCommandFromSquares({
      'g8',
      'f7',
      'g7',
      'h7',
      'f2',
      'g2',
      'h2',
      'f1',
      'g1',
    });
    expect(
      gateway.writes.any((write) => listEquals(write, initialSetupCommand)),
      isTrue,
    );

    gateway.writes.clear();
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await tester.pump();
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({}),
        ),
      ),
      isTrue,
    );

    gateway.writes.clear();
    final wrongMove = dc.NormalMove.fromUci('f1e1');
    final (afterWrongMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(wrongMove);
    gateway.addBoardFen(afterWrongMove.board.fen);
    await tester.pump();

    expect(solvedCount, 0);
    expect(find.text('Try again: follow the highlighted board move.'),
        findsOneWidget);
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({'e1', 'f1'}),
        ),
      ),
      isTrue,
    );

    await tester.pump(const Duration(milliseconds: 700));
    gateway.writes.clear();
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await tester.pump();

    final correctFirstMove = dc.NormalMove.fromUci('f1c1');
    final (afterCorrectFirstMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(correctFirstMove);
    gateway.addBoardFen(afterCorrectFirstMove.board.fen);
    await tester.pump();

    expect(solvedCount, 0);
    expect(find.text('Puzzle solved'), findsNothing);
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({'g8', 'h8'}),
        ),
      ),
      isTrue,
    );

    gateway.writes.clear();
    gateway.addBoardFen('7k/5ppp/8/8/8/8/5PPP/2R3K1');
    await tester.pump();
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({}),
        ),
      ),
      isTrue,
    );

    final finalMove = dc.NormalMove.fromUci('c1c8');
    final (afterFinalMove, _) = loadDartChessPosition(
      '7k/5ppp/8/8/8/8/5PPP/2R3K1 w - - 1 2',
    ).makeSan(finalMove);
    gateway.addBoardFen(afterFinalMove.board.fen);
    await tester.pump();
    await tester.pump();

    expect(solvedCount, 1);
    expect(find.text('Puzzle solved'), findsOneWidget);
    expect(
      gateway.writes.any(
        (write) => listEquals(
          write,
          ChessnutLedCodec.ledCommandFromSquares({}),
        ),
      ),
      isTrue,
    );
  });

