    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/6K1');
    await tester.pump();
    expect(gateway.writes.length, 1);

    gateway.writes.clear();
    final firstMove = dc.NormalMove.fromUci('f1c1');
    final (afterFirstMove, _) = loadDartChessPosition(
      '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
    ).makeSan(firstMove);
    gateway.addBoardFen(afterFirstMove.board.fen);
    await tester.pump();

    expect(solvedCount, 0);
    expect(find.text('Puzzle solved'), findsNothing);
    expect(
      gateway.writes.last,
      ChessnutLedCodec.ledCommandFromSquares({'g8', 'h8'}),
    );

    gateway.writes.clear();
    gateway.addBoardFen('7k/5ppp/8/8/8/8/5PPP/2R3K1');
    await tester.pump();
    expect(
      gateway.writes.last,
      ChessnutLedCodec.ledCommandFromSquares({}),
    );

    gateway.writes.clear();
    gateway.addBoardFen('7k/5ppp/8/8/8/8/5PPP/6K1');
    await tester.pump();
    expect(
      gateway.writes.last,
      ChessnutLedCodec.ledCommandFromSquares({'c1'}),
    );

    final finalMove = dc.NormalMove.fromUci('c1c8');
    final (afterFinalMove, _) = loadDartChessPosition(
      '7k/5ppp/8/8/8/8/5PPP/2R3K1 w - - 1 2',
    ).makeSan(finalMove);
    gateway.addBoardFen(afterFinalMove.board.fen);
    await tester.pump();
    await tester.pump();

    expect(solvedCount, 1);
    expect(find.text('Puzzle solved'), findsOneWidget);
    expect(
      gateway.writes.last,
      ChessnutLedCodec.ledCommandFromSquares({}),
    );

    await tester.pump(const Duration(milliseconds: 40));
    await tester.pump();
    expect(
      requests
          .where(
            (request) =>
                request.url.toString() ==
                'http://puzzle.chessnutech.com/random',
          )
          .length,
      2,
    );
  });

