    expect(find.text('Live database: 4,000,000 puzzles'), findsNothing);
    expect(find.text('4,000,000 in Lichess database'), findsOneWidget);
    expect(find.byTooltip('Refresh themes'), findsNothing);
    expect(find.text('Change theme'), findsOneWidget);
    expect(
      requests.any(
        (request) =>
            request.url.toString() ==
                'http://puzzle.chessnutech.com/3/random' ||
            request.url.toString() == 'http://puzzle.chessnutech.com/7/random',
      ),
      isTrue,
    );
    expect(
      find.text('Theme puzzle #909').evaluate().isNotEmpty ||
          find.text('Theme puzzle #910').evaluate().isNotEmpty,
      isTrue,
    );

