    addTearDown(() => debugDefaultTargetPlatformOverride = null);
    tester.view.physicalSize = const Size(1280, 800);
    await tester.pumpAndSettle();

    final horizontalLayout = find.byKey(
      const ValueKey('puzzle-themes-horizontal-layout'),
    );
    final desktopBoard = tester.getRect(find.byType(InteractiveChessBoard));
    final desktopChooser = tester.getRect(
      find.byKey(const ValueKey('puzzle-theme-chooser-card')),
    );
    expect(horizontalLayout, findsOneWidget);
    expect(desktopBoard.right, lessThan(desktopChooser.left));
    expect(desktopBoard.center.dx, lessThan(desktopChooser.center.dx));
    expect(desktopBoard.width, greaterThan(600));
    expect(desktopBoard.width, greaterThan(desktopChooser.width));
    expect(desktopBoard.bottom, lessThanOrEqualTo(800));
    expect(tester.takeException(), isNull);

    debugDefaultTargetPlatformOverride = TargetPlatform.macOS;
    tester.view.physicalSize = const Size(1279, 800);
    await tester.pumpAndSettle();
    final macBoard = tester.getRect(find.byType(InteractiveChessBoard));
    final macChooser = tester.getRect(
      find.byKey(const ValueKey('puzzle-theme-chooser-card')),
    );
    expect(horizontalLayout, findsOneWidget);
    expect(macBoard.right, lessThan(macChooser.left));
    expect(macBoard.center.dx, lessThan(macChooser.center.dx));
    expect(macBoard.width, lessThanOrEqualTo(430));
    expect(macBoard.width, lessThan(macChooser.width));
    expect(tester.takeException(), isNull);

    debugDefaultTargetPlatformOverride = null;
    tester.view.physicalSize = const Size(390, 844);
    await tester.pumpAndSettle();

    await tester.tap(find.text('Change theme'));
    await tester.pumpAndSettle();

    expect(find.text('Fork'), findsWidgets);
    await tester.tap(find.text('Fork').last);
    await tester.pumpAndSettle();

    expect(
      requests.any(
        (request) =>
            request.url.toString() == 'http://puzzle.chessnutech.com/3/random',
      ),
      isTrue,
    );
    expect(find.text('Theme puzzle #909'), findsOneWidget);
    expect(find.text('fork / pin'), findsOneWidget);
    expect(find.text('184,000'), findsOneWidget);
    expect(find.text('Fork puzzles'), findsOneWidget);
    await tester.drag(find.byType(Scrollable).last, const Offset(0, -700));
    await tester.pumpAndSettle();
    expect(
      find.byWidgetPredicate(
        (widget) => widget.runtimeType.toString() == '_ThemePuzzleDetailCard',
      ),
      findsNothing,
    );
    expect(find.text('Next puzzle'), findsOneWidget);

    await tester.tap(find.text('Change theme'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(
      find.text('Attraction'),
      260,
      scrollable: find
          .descendant(
            of: find.byKey(const ValueKey('puzzle-theme-picker-list')),
            matching: find.byType(Scrollable),
          )
          .first,
    );
    await tester.pumpAndSettle();
    await tester.tap(
      find
          .ancestor(
            of: find.text('Attraction').last,
            matching: find.byWidgetPredicate(
              (widget) => widget.runtimeType.toString() == 'GlassPanel',
            ),
          )
          .first,
      warnIfMissed: false,
    );
    await tester.pumpAndSettle();

    expect(
      requests.any(
        (request) =>
            request.url.toString() == 'http://puzzle.chessnutech.com/7/random',
      ),
      isTrue,
    );
    expect(find.text('Theme puzzle #910'), findsOneWidget);
    expect(find.text('attraction / middlegame'), findsOneWidget);
  });

