  testWidgets(
    'Puzzle themes sends only the final Move board target when loading next',
    (WidgetTester tester) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.iOS;
      addTearDown(() => debugDefaultTargetPlatformOverride = null);
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      final gateway = MemoryPhysicalBoardGateway(
        boardModel: PhysicalBoardModel.move,
      );
      await gateway.connect();
      addTearDown(gateway.dispose);
      const firstFen = '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1';
      const nextFen = '8/8/8/3k4/8/8/3Q4/3K4 w - - 0 1';
      const intermediateFen = '8/8/8/3k4/8/8/8/3K4';
      final nextPuzzleResponse = Completer<http.Response>();
      var requestCount = 0;
      final client = MockClient((request) async {
        if (request.method == 'GET' &&
            request.url.toString() == 'http://puzzle.chessnutech.com/info') {
          return http.Response(
            jsonEncode({
              'total': 4000000,
              'tags': [
                {
                  'id': 3,
                  'key': 'fork',
                  'name': 'Fork',
                  'desc': 'Attack two targets',
                  'total': 184000,
                },
              ],
            }),
            200,
          );
        }
        if (request.method == 'GET' &&
            request.url.toString() ==
                'http://puzzle.chessnutech.com/3/random') {
          requestCount += 1;
          if (requestCount == 1) {
            return http.Response(
              jsonEncode({
                'id': 913,
                'fen': firstFen,
                'move': 'f1c1',
                'lichess_id': 'themeMoveFirst',
                'tags': 'fork pin',
              }),
              200,
            );
          }
          return nextPuzzleResponse.future;
        }
        return http.Response('not found', 404);
      });

      await tester.pumpWidget(
        _screenTestApp(
          PuzzleThemesScreen(
            onNavigate: (_) {},
            apiClient: ChessnutApiClient(httpClient: client),
            boardGateway: gateway,
            boardSettings: const BoardSettingsState(
              moveRestoreDelayMs: 100,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
      await tester.pump();
      gateway.writes.clear();

      final nextButton = find.byKey(const ValueKey('puzzle-theme-next-button'));
      await tester.ensureVisible(nextButton);
      await tester.pumpAndSettle();
      await tester.tap(nextButton);
      await tester.pump();
      gateway.addBoardFen(intermediateFen);
      await tester.pump(const Duration(milliseconds: 150));

      expect(
        gateway.writes.where(
          (write) => listEquals(
            write,
            ChessnutMoveBoardCodec.setBoardCommand(firstFen),
          ),
        ),
        isEmpty,
      );

      nextPuzzleResponse.complete(
        http.Response(
          jsonEncode({
            'id': 914,
            'fen': nextFen,
            'move': 'd2d5',
            'lichess_id': 'themeMoveNext',
            'tags': 'fork middlegame',
          }),
          200,
        ),
      );
      await tester.pumpAndSettle();
      gateway.addBoardFen(intermediateFen);
      await tester.pump(const Duration(milliseconds: 150));

      final nextCommand = ChessnutMoveBoardCodec.setBoardCommand(nextFen);
      expect(
        gateway.writes.where((write) => listEquals(write, nextCommand)),
        hasLength(1),
      );
      debugDefaultTargetPlatformOverride = null;
    },
  );

