  testWidgets('Puzzle pages apply Move voice moves', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final gateway = MemoryPhysicalBoardGateway();
    await gateway.connect();
    addTearDown(gateway.dispose);
    final stormVoiceService = _FakeVoiceMoveRecognitionService();
    final themeVoiceService = _FakeVoiceMoveRecognitionService();
    addTearDown(stormVoiceService.dispose);
    addTearDown(themeVoiceService.dispose);
    var stormSolvedCount = 0;
    var themeSolvedCount = 0;
    var stormRequestCount = 0;
    var themeRequestCount = 0;

    final client = MockClient((request) async {
      if (request.method == 'GET' &&
          request.url.toString() == 'http://puzzle.chessnutech.com/random') {
        stormRequestCount += 1;
        return http.Response(
          jsonEncode({
            'id': 808,
            'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
            'move': 'f1c1',
            'lichess_id': 'storm1234',
            'tags': 'backRankMate fork',
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() == 'http://puzzle.chessnutech.com/3/random') {
        themeRequestCount += 1;
        return http.Response(
          jsonEncode({
            'id': 809,
            'fen': '6k1/5ppp/8/8/8/8/5PPP/5RK1 w - - 0 1',
            'move': 'f1c1',
            'lichess_id': 'theme809',
            'tags': 'fork',
          }),
          200,
        );
      }
      if (request.method == 'GET' &&
          request.url.toString() == 'http://puzzle.chessnutech.com/info') {
        return http.Response(
          jsonEncode({
            'total': 4000000,
            'tags': [
              {
                'id': 3,
                'key': 'fork',
                'name': 'Fork',
                'desc': 'Attack two targets',
                'total': 184000,
              },
            ],
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(
      _screenTestApp(
        PuzzleStormScreen(
          onNavigate: (_) {},
          apiClient: ChessnutApiClient(httpClient: client),
          boardGateway: gateway,
          voiceMoveRecognitionService: stormVoiceService,
          onPuzzleSolved: () => stormSolvedCount += 1,
        ),
      ),
    );
    await tester.pumpAndSettle();
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await _pumpUntilCondition(
      tester,
      () => find
          .text('Set up the physical board to match this puzzle position.')
          .evaluate()
          .isEmpty,
      reason: 'storm physical setup ready',
    );

    final stormToggle =
        find.byKey(const ValueKey('puzzle-storm-voice-moves-toggle'));
    expect(stormToggle, findsOneWidget);
    (tester.widget(stormToggle) as dynamic).onPressed?.call();
    await tester.pumpAndSettle();
    expect(stormVoiceService.started, isTrue);
    expect(find.byTooltip('Turn voice moves off'), findsOneWidget);
    expect(
      find.text('Chessnut uses the microphone only while voice moves are on.'),
      findsOneWidget,
    );
    await tester.tap(find.text('Got it'));
    await tester.pumpAndSettle();
    stormVoiceService.addResult('rook c one');
    await _pumpUntilCondition(
      tester,
      () => stormSolvedCount == 1,
      reason: 'storm voice puzzle solved',
    );
    expect(find.text('Puzzle solved'), findsOneWidget);
    await tester.pump(const Duration(seconds: 2));
    expect(stormRequestCount, 1);
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/2R3K1');
    await _pumpUntilCondition(
      tester,
      () => stormRequestCount == 2,
      reason: 'storm waits for Move board final voice position',
    );

    await tester.pumpWidget(
      _screenTestApp(
        PuzzleThemesScreen(
          onNavigate: (_) {},
          apiClient: ChessnutApiClient(httpClient: client),
          boardGateway: gateway,
          voiceMoveRecognitionService: themeVoiceService,
          onPuzzleSolved: () => themeSolvedCount += 1,
        ),
      ),
    );
    await tester.pumpAndSettle();
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/5RK1');
    await _pumpUntilCondition(
      tester,
      () => find
          .text('Set up the physical board to match this puzzle position.')
          .evaluate()
          .isEmpty,
      reason: 'theme physical setup ready',
    );

    final themeToggle =
        find.byKey(const ValueKey('puzzle-themes-voice-moves-toggle'));
    expect(themeToggle, findsOneWidget);
    (tester.widget(themeToggle) as dynamic).onPressed?.call();
    await tester.pumpAndSettle();
    expect(themeVoiceService.started, isTrue);
    await tester.tap(find.text('Got it'));
    await tester.pumpAndSettle();
    themeVoiceService.addResult('Rc1');
    await _pumpUntilCondition(
      tester,
      () => themeSolvedCount == 1,
      reason: 'theme voice puzzle solved',
    );
    expect(find.text('Puzzle solved'), findsOneWidget);
    await tester.pump(const Duration(seconds: 2));
    expect(themeRequestCount, 1);
    gateway.addBoardFen('6k1/5ppp/8/8/8/8/5PPP/2R3K1');
    await _pumpUntilCondition(
      tester,
      () => themeRequestCount == 2,
      reason: 'theme waits for Move board final voice position',
    );
  });

