          .where((element) {
        final text = element.widget as Text;
        return text.data == item.title || text.data == item.subtitle;
      }).map((element) {
        final box = element.renderObject! as RenderBox;
        return box.localToGlobal(Offset.zero) & box.size;
      }).toList();
      expect(textRects, isNotEmpty);
      final textTop = textRects.map((rect) => rect.top).reduce(math.min);
      final textBottom = textRects.map((rect) => rect.bottom).reduce(math.max);
      expect(
        (((textTop + textBottom) / 2) - cardRect.center.dy).abs(),
        lessThanOrEqualTo(3),
      );
    }
    _expectNoLayoutOverflow(tester);
  });

