  testWidgets('Mistake Book paginates and filters a long mistake list', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(1200, 900);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final now = DateTime.now();
    MistakeBookEntry entry(int index) {
      final classification = index % 3 == 0
          ? 'Blunder'
          : index % 3 == 1
              ? 'Mistake'
              : 'Inaccuracy';
      final theme = index.isEven ? 'Opening' : 'Endgame';
      return MistakeBookEntry(
        id: 'long-$index',
        reportKey: 'long-report-$index',
        pgn: _sampleAnalysisPgn,
        sourceTitle: 'Long Game $index vs Bot',
        ply: index,
        moveSan: '$index. Qa4?',
        bestMoveSan: 'Qe2',
        classification: classification,
        summary: 'Searchable note $index from a saved review.',
        theme: theme,
        fenBefore: standardStartFen,
        fenAfter: standardStartFen,
        engineLine: 'Qe2 Nf6',
        createdAt: now.subtract(Duration(days: index)),
        updatedAt: now.subtract(Duration(hours: index)),
        dueAt: now.subtract(Duration(minutes: 19 - index)),
      );
    }

    final preferencesStore = MemoryAppPreferencesStore(
      StoredAppPreferences(
        mistakeBook: MistakeBookState(
          entries: {
            for (var index = 1; index <= 18; index++)
              'long-$index': entry(index),
          },
        ),
      ),
    );

    await tester.pumpWidget(
      _screenTestApp(
        MistakeBookScreen(
          onNavigate: (_) {},
          store: AppPreferencesMistakeBookStore(preferencesStore),
        ),
      ),
    );
    await tester.pumpAndSettle();

    expect(find.text('Showing 1-10 of 18'), findsOneWidget);
    expect(find.text('1. Qa4?'), findsWidgets);
    expect(find.text('10. Qa4?'), findsOneWidget);
    expect(find.text('11. Qa4?'), findsNothing);

    await tester.tap(find.byTooltip('Next page'));
    await tester.pumpAndSettle();

    expect(find.text('Showing 11-18 of 18'), findsOneWidget);
    expect(find.text('1. Qa4?'), findsNothing);
    expect(find.text('11. Qa4?'), findsWidgets);
    expect(find.text('18. Qa4?'), findsOneWidget);

    await tester
        .tap(find.byKey(const ValueKey('mistake-classification-Blunder')));
    await tester.pumpAndSettle();

    expect(find.text('Showing 1-6 of 6'), findsOneWidget);
    expect(find.text('3. Qa4?'), findsWidgets);
    expect(find.text('6. Qa4?'), findsWidgets);
    expect(find.text('1. Qa4?'), findsNothing);

    await tester.tap(find.text('Opening').first);
    await tester.pumpAndSettle();

    expect(find.text('Showing 1-3 of 3'), findsOneWidget);
    expect(find.text('6. Qa4?'), findsWidgets);
    expect(find.text('12. Qa4?'), findsWidgets);
    expect(find.text('18. Qa4?'), findsWidgets);

    await tester.enterText(
      find.byKey(const ValueKey('mistake-book-search-field')),
      'Long Game 12',
    );
    await tester.pumpAndSettle();

    expect(find.text('Showing 1-1 of 1'), findsOneWidget);
    expect(find.text('12. Qa4?'), findsWidgets);
    expect(find.text('6. Qa4?'), findsNothing);
  });

