  testWidgets('Course checkpoint refreshes board LEDs until matched', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final gateway =
        MemoryPhysicalBoardGateway(boardModel: PhysicalBoardModel.air);
    await gateway.connect();
    addTearDown(gateway.dispose);

    final videoAdapter = _PolledCourseVideoAdapter()
      ..stalePosition = Duration.zero
      ..polledPosition = Duration.zero;

    await tester.pumpWidget(
      _screenTestApp(
        InteractiveCoursesScreen(
          onNavigate: (_) {},
          boardGateway: gateway,
          courseService: const _TimedCourseLessonRepository(),
          progressStore: const NullCourseProgressStore(),
          videoAdapterFactory: () => videoAdapter,
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.scrollUntilVisible(
      find.byKey(const ValueKey('course-tile-03')),
      220,
      scrollable: find.byType(Scrollable).last,
    );
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('course-tile-03')));
    await _pumpUntilFound(tester, find.text('Lesson board'));
    await tester.pump(const Duration(milliseconds: 150));

    final lightCommand = ChessnutLedCodec.ledCommandFromSquares({'e7'});
    final clearCommand = ChessnutLedCodec.ledCommandFromSquares({});

    int lightWriteCount() => gateway.writes
        .where((command) => listEquals(command, lightCommand))
        .length;

    videoAdapter.polledPosition = const Duration(milliseconds: 2500);
    await tester.pump(const Duration(milliseconds: 300));
    await tester.pump();

    final initialCount = lightWriteCount();
    expect(initialCount, greaterThanOrEqualTo(1));

    await tester.pump(const Duration(milliseconds: 950));
    final refreshedCount = lightWriteCount();
    expect(refreshedCount, greaterThan(initialCount));

    gateway.writes.clear();
    gateway.addBoardFen('8/8/8/8/8/8/8/8');
    await tester.pump();
    expect(
      gateway.writes.any((command) => listEquals(command, clearCommand)),
      isFalse,
    );

    gateway.addBoardFen('8/4N3/8/8/8/8/8/8');
    await tester.pump();
    expect(
      gateway.writes.any((command) => listEquals(command, clearCommand)),
      isTrue,
    );

    final matchedCount = lightWriteCount();
    await tester.pump(const Duration(milliseconds: 950));
    expect(lightWriteCount(), matchedCount);
  });

