    );
    await tester.pumpAndSettle();
    await tester.tap(find.byKey(const ValueKey('course-tile-03')));
    await _pumpUntilFound(tester, find.text('Lesson board'));
    await tester.pump(const Duration(milliseconds: 150));

    bool wroteLed(Set<String> squares) {
      final command = ChessnutLedCodec.ledCommandFromSquares(squares);
      return gateway.writes.any((write) => listEquals(write, command));
    }

    videoAdapter.polledPosition = const Duration(milliseconds: 2500);
    await tester.pump(const Duration(milliseconds: 300));
    await tester.pump();

    expect(wroteLed({'e7'}), isTrue);

    gateway.writes.clear();
    await tester.tap(find.text('Final placement'));
    await tester.pump(const Duration(milliseconds: 50));
    expect(wroteLed({'c5'}), isTrue);

    gateway.writes.clear();
    await tester.tap(find.text('Timed placement'));
    await tester.pump(const Duration(milliseconds: 50));
    expect(wroteLed({'e7'}), isTrue);

    gateway.writes.clear();
    await tester.tap(find.text('Middle placement'));
    await tester.pump(const Duration(milliseconds: 50));
    expect(wroteLed({'d6'}), isTrue);

    gateway.writes.clear();
    videoAdapter.polledPosition = const Duration(milliseconds: 6500);
    await tester.pump(const Duration(milliseconds: 300));
    await tester.pump();

    expect(videoAdapter.seekPositions, contains(const Duration(seconds: 6)));
    expect(wroteLed({'c5'}), isTrue);
  });

