  testWidgets(
    'Android phone interactive course landscape shows board video and checkpoints',
    (WidgetTester tester) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.android;
      tester.view.physicalSize = const Size(844, 390);
      tester.view.devicePixelRatio = 1;
      tester.view.padding = const FakeViewPadding(right: 48);
      tester.view.viewPadding = const FakeViewPadding(right: 48);
      try {
        await tester.pumpWidget(
          _testApp(
            initialScreen: 'Courses',
            courseLessonRepository:
                const _MultiCheckpointCourseLessonRepository(),
            courseVideoAdapterFactory: _FakeCourseVideoAdapter.new,
          ),
        );
        await tester.pumpAndSettle();

        final course = find.text('03 - Attack and Captures').last;
        await tester.ensureVisible(course);
        await tester.pumpAndSettle();
        await tester.tap(course);
        final layout = find.byKey(
          const ValueKey('lesson-android-phone-landscape'),
        );
        await _pumpUntilFound(
          tester,
          layout,
        );

        final boardPane = find.byKey(const ValueKey('lesson-board-pane'));
        final videoPane = find.byKey(const ValueKey('lesson-video-pane'));
        final checkpointPane =
            find.byKey(const ValueKey('lesson-checkpoint-pane'));
        final boardRect = tester.getRect(boardPane);
        final videoRect = tester.getRect(videoPane);
        final checkpointRect = tester.getRect(checkpointPane);
        final board = tester.getRect(find.byType(ChessBoard));
        final videoFrame =
            tester.getRect(find.byKey(const ValueKey('lesson-video-frame')));
        final outerScrollable =
            find.ancestor(of: layout, matching: find.byType(Scrollable)).first;
        final outerState = tester.state<ScrollableState>(outerScrollable);
        expect(boardRect.center.dx, lessThan(videoRect.center.dx));
        expect(
          checkpointRect.top,
          greaterThanOrEqualTo(math.max(boardRect.bottom, videoRect.bottom)),
        );
        expect(checkpointRect.left, lessThanOrEqualTo(boardRect.left));
        expect(checkpointRect.right, greaterThanOrEqualTo(videoRect.right));
        expect(checkpointRect.right, lessThanOrEqualTo(844 - 48));
        expect(checkpointRect.bottom, greaterThan(390));
        expect(board.width, greaterThan(220));
        expect(videoFrame.width, greaterThan(360));
        expect(boardRect.width - board.width, lessThan(50));
        expect(videoFrame.width / videoRect.width, greaterThan(0.75));
        expect(outerState.position.maxScrollExtent, greaterThan(0));
        expect(
          find.descendant(
            of: checkpointPane,
            matching: find.byType(Scrollable),
          ),
          findsNothing,
        );
        expect(find.byType(ChessBoard), findsOneWidget);
        expect(
            find.byKey(const ValueKey('lesson-video-frame')), findsOneWidget);
        expect(find.text('Checkpoints'), findsOneWidget);
        _expectNoLayoutOverflow(tester);

        await tester.dragFrom(
          Offset(
            checkpointRect.center.dx,
            math.min(checkpointRect.top + 40, 360),
          ),
          const Offset(0, -240),
        );
        await tester.pumpAndSettle();

        expect(outerState.position.pixels, greaterThan(0));
        final finalCheckpoint = tester.getRect(find.text('Final placement'));
        expect(finalCheckpoint.top, greaterThanOrEqualTo(0));
        expect(finalCheckpoint.bottom, lessThanOrEqualTo(390));
      } finally {
        debugDefaultTargetPlatformOverride = null;
        tester.view.resetPhysicalSize();
        tester.view.resetDevicePixelRatio();
        tester.view.resetPadding();
        tester.view.resetViewPadding();
      }
    },
  );

