  testWidgets('Settings mode pills switch app theme', (
    WidgetTester tester,
  ) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    final preferencesStore = MemoryAppPreferencesStore();
    await tester.pumpWidget(
      _testApp(
        appPreferencesStore: preferencesStore,
        initialScreen: 'Settings',
      ),
    );
    await tester.pump(const Duration(seconds: 3));
    expect(find.text('Settings'), findsWidgets);

    void selectMode(String label) {
      final button = find.ancestor(
        of: find.text(label),
        matching: find.byType(InkWell),
      );
      tester.widget<InkWell>(button.first).onTap?.call();
    }

    selectMode('Light');
    await tester.pumpAndSettle();
    expect(
      tester.widget<MaterialApp>(find.byType(MaterialApp)).themeMode,
      ThemeMode.light,
    );

    selectMode('System');
    await tester.pumpAndSettle();
    expect(
      tester.widget<MaterialApp>(find.byType(MaterialApp)).themeMode,
      ThemeMode.system,
    );

    selectMode('Dark');
    await tester.pumpAndSettle();
    expect(
      tester.widget<MaterialApp>(find.byType(MaterialApp)).themeMode,
      ThemeMode.dark,
    );
    expect(
      AppSharedPreferences.instance.getString(AppSettingKeys.themeMode),
      ThemeMode.dark.name,
    );

    await tester.pumpWidget(
      _testApp(
        appPreferencesStore: preferencesStore,
        initialScreen: 'Settings',
      ),
    );
    await tester.pumpAndSettle();

    expect(
      tester.widget<MaterialApp>(find.byType(MaterialApp)).themeMode,
      ThemeMode.dark,
    );
  });

