          lichessAuthorizationPresenter: (
            BuildContext context, {
            required Uri authorizationUri,
          }) async {
            return true;
          },
        ),
      ),
    );
    await tester.pumpAndSettle();

    await tester.tap(find.byKey(const ValueKey('account-shortcut-lichess')));
    await tester.pumpAndSettle();

    expect(tokenChecks, 4);
    expect(find.text('ChessnutPlayer'), findsWidgets);
    expect(find.textContaining('Get OAuth code failed'), findsNothing);
    expect(updatedSession?.bindLichess, isTrue);
    expect(updatedSession?.lichessName, 'ChessnutPlayer');
  });

