  testWidgets('Lichess unlink keeps online setup auth status in sync',
      (WidgetTester tester) async {
    tester.view.physicalSize = const Size(390, 844);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);

    var lichessBound = true;
    final linkedLoginResponse = {
      ..._loginResponse,
      'data': {
        ..._loginResponse['data'] as Map<String, Object?>,
        'bind_lichess': true,
        'lichess_name': 'ChessnutPlayer',
      },
    };
    final fallbackClient = _emptyBackendClient();
    final client = MockClient((request) async {
      if (request.method == 'POST' &&
          request.url.toString() == 'https://api.chessnutech.com/api/login') {
        return http.Response(jsonEncode(linkedLoginResponse), 200);
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/freeUserBind') {
        lichessBound = false;
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.toString() ==
              'https://api.chessnutech.com/api/getLichessToken') {
        if (!lichessBound) {
          return http.Response(
            jsonEncode({
              'ret': 0,
              'code': 502,
              'info': 'lichess not bound',
              'data': null,
            }),
            200,
          );
        }
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'token': 'lichess-token',
              'lichess_name': 'ChessnutPlayer',
            },
          }),
          200,
        );
      }
      return http.Response.fromStream(await fallbackClient.send(request));
    });

    await tester.pumpWidget(_testApp(httpClient: client));
    await tester.pump(const Duration(seconds: 3));
    await _signIn(tester);

    await _openAccountFromHome(tester);
    expect(find.text('ChessnutPlayer'), findsWidgets);

    await tester.tap(find.byKey(const ValueKey('account-shortcut-lichess')));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Unlink Lichess'));
    await tester.pumpAndSettle();
    expect(find.text('Authorize Lichess'), findsOneWidget);

    await tester.tap(find.byKey(const ValueKey('account-back-button')));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Play').first);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Find an online match'));
    await tester.pumpAndSettle();

