  testWidgets(
    'Account delete submits verification code to Chessnut API after confirm',
    (WidgetTester tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);

      final requests = <http.Request>[];
      final client = MockClient((request) async {
        requests.add(request);
        if (request.method == 'POST' &&
            request.url.toString() == 'https://api.chessnutech.com/api/login') {
          return http.Response(jsonEncode(_loginResponse), 200);
        }
        if (request.method == 'POST' &&
            request.url.toString() ==
                'https://api.chessnutech.com/api/getDeleteUserImage') {
          return http.Response(
            jsonEncode({
              'ret': 1,
              'code': 200,
              'info': 'ok',
              'data': {
                'base64': '',
                'captchaId': 'captcha-1',
              },
            }),
            200,
          );
        }
        if (request.method == 'POST' &&
            request.url.toString() ==
                'https://api.chessnutech.com/api/deleteUser') {
          return http.Response(
            jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
            200,
          );
        }
        if (request.method == 'POST' &&
            request.url.toString() ==
                'https://api.chessnutech.com/api/wallet/balance') {
          return _walletBalanceResponse();
        }
        if (request.method == 'POST' &&
            request.url.toString() ==
                'https://api.chessnutech.com/api/wallet/ledger') {
          return _walletLedgerResponse();
        }
        return http.Response('not found', 404);
      });

      await tester.pumpWidget(_testApp(httpClient: client));
      await tester.pump(const Duration(seconds: 3));
      await _signIn(tester);

      await _openAccountFromHome(tester);
      await tester.scrollUntilVisible(
        find.text('Delete account'),
        240,
        scrollable: find.byType(Scrollable).last,
      );
      await tester.pumpAndSettle();
      await tester.tap(find.text('Delete account'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Continue'));
      await tester.pumpAndSettle();
      expect(find.text('Enter the verification code'), findsOneWidget);
      final deleteCodeField =
          find.byKey(const ValueKey('delete-account-code-field'));
      expect(deleteCodeField, findsOneWidget);
      expect(find.byKey(const ValueKey('delete-account-password-field')),
          findsNothing);
      expect(
        tester.getSize(deleteCodeField).height,
        greaterThanOrEqualTo(56),
      );
      await tester.enterText(
        deleteCodeField,
        '123456',
      );
      await tester.pumpAndSettle();
      expect(find.text('123456'), findsOneWidget);
      await tester.tap(find.text('Delete permanently'));
      await tester.pumpAndSettle();

      final deleteRequest = requests.singleWhere(
        (request) => request.url.path == '/api/deleteUser',
      );
      expect(deleteRequest.bodyFields['user_id'], '7');
      expect(
        deleteRequest.bodyFields['token'],
        '12345678901234567890123456789012',
      );
      expect(deleteRequest.bodyFields['code'], '123456');
      expect(deleteRequest.bodyFields['captchaId'], 'captcha-1');
      expect(find.text('Account deletion requested'), findsOneWidget);
    },
  );

