  testWidgets('App checks for updates once per process automatically',
      (WidgetTester tester) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.windows;
    try {
      PackageInfo.setMockInitialValues(
        appName: 'Chessnut',
        packageName: 'com.chessnut.chessnutnext',
        version: '0.1.4',
        buildNumber: '6',
        buildSignature: '',
      );
      var versionChecks = 0;
      await tester.pumpWidget(
        _testApp(
          httpClient: MockClient((request) async {
            if (request.url.path == '/api/version') {
              versionChecks++;
              return http.Response(
                jsonEncode({
                  'ret': 1,
                  'code': 200,
                  'info': 'ok',
                  'data': {
                    'version': request.bodyFields['current_version'] ?? '0.1.4',
                    'platform':
                        int.tryParse(request.bodyFields['platform'] ?? '') ?? 0,
                    'download_url': 'https://www.chessnutech.com',
                    'change_log': '',
                    'update_available': false,
                    'force_update': false,
                    'update_method': 'download',
                  },
                }),
                200,
              );
            }
            return http.Response(
              jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': {}}),
              200,
            );
          }),
        ),
      );
      await tester.pump(const Duration(milliseconds: 200));

      expect(versionChecks, 1);

      tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.paused);
      tester.binding.handleAppLifecycleStateChanged(AppLifecycleState.resumed);
      await tester.pump(const Duration(milliseconds: 200));

      expect(versionChecks, 1);
      await tester.pump(const Duration(seconds: 2));
    } finally {
      debugDefaultTargetPlatformOverride = null;
    }
  });

