      _testApp(
        appPreferencesStore: preferencesStore,
        httpClient: MockClient((request) async {
          if (request.url.path == '/api/version') {
            versionChecks++;
            return http.Response(
              jsonEncode({
                'ret': 1,
                'code': 200,
                'info': 'ok',
                'data': {
                  'version': '1.4.0',
                  'platform':
                      int.tryParse(request.bodyFields['platform'] ?? '') ?? 0,
                  'download_url': 'https://www.chessnutech.com',
                  'change_log': 'Bug fixes',
                  'update_available': true,
                  'force_update': false,
                  'update_method': 'download',
                },
              }),
              200,
            );
          }
          return http.Response(
