  testWidgets('Android automatic Play update prompt starts immediate update', (
    WidgetTester tester,
  ) async {
    debugDefaultTargetPlatformOverride = TargetPlatform.android;
    PackageInfo.setMockInitialValues(
      appName: 'Chessnut',
      packageName: 'com.chessnut.newchessnut',
      version: '0.5.2',
      buildNumber: '5002',
      buildSignature: '',
    );
    const playChannel = MethodChannel('chessnut/play_in_app_update');
    final immediateCalls = <bool>[];
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(playChannel, (call) async {
      if (call.method == 'checkAvailability') {
        return {
          'available': true,
          'immediateAllowed': true,
          'flexibleAllowed': true,
          'availableVersionCode': 5005,
          'installerPackageName': 'com.android.vending',
          'installedFromGooglePlay': true,
        };
      }
      if (call.method == 'startUpdate') {
        final arguments = call.arguments as Map<Object?, Object?>;
        immediateCalls.add(arguments['immediate'] == true);
        return 'started';
      }
      fail('Unexpected Play update method: ${call.method}');
    });
    addTearDown(() {
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(playChannel, null);
    });
    var backendVersionChecks = 0;
    await tester.pumpWidget(
      _testApp(
        httpClient: MockClient((request) async {
          if (request.url.path == '/api/version') {
            backendVersionChecks++;
          }
          return http.Response(
            jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': {}}),
            200,
          );
        }),
      ),
    );
    await tester.pumpAndSettle();
    await tester.pump(const Duration(seconds: 2));

    expect(backendVersionChecks, 0);
    expect(find.text('Update available'), findsOneWidget);
    expect(find.text('Later'), findsNothing);
    expect(find.text('Remind me in 1 day'), findsOneWidget);
    expect(find.text("Don't remind me again for this update"), findsOneWidget);

    await tester.tap(find.text('Update with Google Play'));
    await tester.pump();

    expect(immediateCalls, <bool>[true]);
    debugDefaultTargetPlatformOverride = null;
  });

