        final page = int.tryParse(request.bodyFields['page'] ?? '') ?? 1;
        capturedPages.add(page.toString());
        final start = (page - 1) * 10;
        final records = start < personalEngines.length
            ? personalEngines.skip(start).take(10).toList(growable: false)
            : const <Map<String, Object?>>[];
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'page': page,
              'total_page': 2,
              'total': personalEngines.length,
              'list': records,
            },
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/train/official_shared_list') {
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': []}),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/train/subStatus') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'expire_time': '', 'expire_count': 0, 'sub_status': 0},
          }),
          200,
        );
      }
      return http.Response('not found', 404);
    });

    await tester.pumpWidget(_testApp(httpClient: client));
