    await tester.tap(lichessSpeedField);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Rapid').last);
    await tester.pumpAndSettle();
    await tester.ensureVisible(
      find.byKey(const ValueKey('engine-model-lichess-since')),
    );
    await tester.pumpAndSettle();
    await tester.enterText(
      find.byKey(const ValueKey('engine-model-lichess-since')),
      '2026-06-01',
    );
    await tester.ensureVisible(
      find.byKey(const ValueKey('engine-model-lichess-until')),
    );
    await tester.pumpAndSettle();
    await tester.enterText(
      find.byKey(const ValueKey('engine-model-lichess-until')),
      '2026-06-24',
    );
