    await tester.pumpAndSettle();
    await tester.tap(lichessRatedField);
    await tester.pumpAndSettle();
    await tester.tap(find.text('Rated only').last);
    await tester.pumpAndSettle();
    final lichessColorField =
        find.byKey(const ValueKey('engine-model-lichess-color'));
    await tester.ensureVisible(lichessColorField);
    await tester.pumpAndSettle();
    await tester.tap(lichessColorField);
    await tester.pumpAndSettle();
    await tester.tap(find.text('White games').last);
    await tester.pumpAndSettle();
    await tester.enterText(
      find.widgetWithText(TextField, 'Notes'),
      'Build from nightly games',
    );
    final lichessPreviewButton =
        find.byKey(const ValueKey('engine-model-lichess-preview'));
    await tester.drag(
        find.byType(SingleChildScrollView).last, const Offset(0, -240));
    await tester.pumpAndSettle();
    await tester.ensureVisible(lichessPreviewButton);
    await tester.pumpAndSettle();
    await tester.tap(
      find.descendant(
        of: lichessPreviewButton,
        matching: find.byType(OutlinedButton),
      ),
    );
    await tester.pumpAndSettle();

    final previewRequest = requests.singleWhere(
      (request) =>
          request.method == 'GET' &&
          request.url.host == 'lichess.org' &&
          request.url.path == '/api/games/user/storm123',
    );
    expect(previewRequest.url.queryParameters['max'], '80');
    expect(previewRequest.url.queryParameters['perfType'], 'rapid');
    expect(
      previewRequest.url.queryParameters['since'],
      DateTime.utc(2026, 6, 1).millisecondsSinceEpoch.toString(),
    );
    expect(
      previewRequest.url.queryParameters['until'],
      DateTime.utc(2026, 6, 24).millisecondsSinceEpoch.toString(),
    );
    expect(previewRequest.url.queryParameters['rated'], 'true');
    expect(previewRequest.url.queryParameters['color'], 'white');
    expect(find.text('Loaded 20 games'), findsOneWidget);
    final pgnPreviewButton =
        find.byKey(const ValueKey('engine-model-lichess-preview-pgn'));
    await tester.ensureVisible(pgnPreviewButton);
    await tester.pumpAndSettle();
    await tester.tap(
      find.descendant(
        of: pgnPreviewButton,
        matching: find.byType(OutlinedButton),
      ),
    );
    await tester.pumpAndSettle();

    expect(find.text('Preview found games'), findsWidgets);
    expect(find.byKey(const ValueKey('engine-model-preview-game-tile')),
        findsNWidgets(20));
    expect(
      find.text('White: storm123 / Black: lichessOpponent1'),
      findsOneWidget,
    );
    expect(find.text('Lichess / Time: 10+5'), findsWidgets);
    expect(find.text('Date: 2026-06-27'), findsOneWidget);
    expect(find.text('Location: https://lichess.org/sample1'), findsOneWidget);
    expect(find.textContaining('[Event "Lichess Rated Rapid"]'), findsNothing);
    expect(find.textContaining('[White "storm123"]'), findsNothing);

    await tester.tap(find.text('Done'));
    await tester.pumpAndSettle();

    final queueButton = find.widgetWithText(FilledButton, 'Start training');
    await tester.ensureVisible(queueButton);
    await tester.pumpAndSettle();
    await tester.tap(queueButton);
    await tester.pumpAndSettle();

    final pushRequest = requests.lastWhere(
      (request) => request.url.path == '/api/v3/modelBuild/push',
    );
    expect(pushRequest.bodyFields['title'], 'Queued Style Model');
    expect(pushRequest.bodyFields['remark'], 'Build from nightly games');
    expect(pushRequest.bodyFields['pgn'], contains('[White "storm123"]'));
    expect(
      RegExp(r'^\[Train "w"\]$', multiLine: true)
          .allMatches(pushRequest.bodyFields['pgn'] ?? ''),
      hasLength(20),
    );
    expect(pushRequest.bodyFields['pgn'], contains('lichessOpponent20'));
    expect(pushRequest.bodyFields.containsKey('player_id'), isFalse);
    expect(find.textContaining('Personal engine training started'),
        findsOneWidget);
  });

