          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {'expire_time': '', 'expire_count': 0, 'sub_status': 0},
          }),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/gameRecords/search') {
        final page = int.tryParse(request.bodyFields['page'] ?? '') ?? 1;
        final count = int.tryParse(request.bodyFields['count'] ?? '') ?? 20;
        final start = count <= 1 ? 0 : (page - 1) * count;
        final end = count <= 1 ? 0 : math.min(64, start + count);
        final records = [
          for (var game = start + 1; game <= end; game += 1)
            {
              'id': 9000 + game,
              'pgn': 'https://records.test/$game.pgn',
              'white_name':
                  game.isOdd ? 'Chessnut Player' : 'fullOpponent$game',
              'black_name':
                  game.isOdd ? 'fullOpponent$game' : 'Chessnut Player',
              'play_mode': 'lichess_blitz',
              'play_time': 1782000000 + game,
              'win_id': 0,
              'game_status': 2,
              'game_step': 4,
            },
        ];
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'total_page': (64 / count).ceil(),
              'total': 64,
              'records': records,
            },
          }),
          200,
        );
      }
      if (request.method == 'GET' && request.url.host == 'records.test') {
        final game =
            int.parse(request.url.pathSegments.single.split('.').first);
        return http.Response(
          '[Event "Full Game Record Preview $game"]\n'
          '[Site "Chessnut App"]\n'
          '[Date "2026.06.${(game % 28 + 1).toString().padLeft(2, '0')}"]\n'
          '[White "${game.isOdd ? 'Chessnut Player' : 'fullOpponent$game'}"]\n'
          '[Black "${game.isOdd ? 'fullOpponent$game' : 'Chessnut Player'}"]\n'
          '[TimeControl "3+2"]\n\n'
          '1. e4 e5 2. Nf3 Nc6 *',
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/modelBuild/status') {
        return http.Response(
          jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
          200,
        );
      }
      if (request.method == 'POST' &&
          request.url.path == '/api/v3/modelBuild/push') {
        return http.Response(
          jsonEncode({
            'ret': 1,
            'code': 200,
            'info': 'ok',
            'data': {
              'id': 77,
              'train_status': 0,
              'title': request.bodyFields['title'],
              'remark': request.bodyFields['remark'] ?? '',
            },
          }),
          200,
        );
      }
      return http.Response('not found', 404);
