                'pgn': '[Event "Queued Record $game"]\n'
                    '[Site "Chessnut App"]\n'
                    '[Date "2026.06.30"]\n'
                    '[White "storm123"]\n'
                    '[Black "queuedOpponent$game"]\n'
                    '[TimeControl "5+0"]\n\n'
                    '1. e4 e5 2. Nf3 Nc6 *',
                'white_name': 'storm123',
                'black_name': 'queuedOpponent$game',
                'play_mode': 'lichess_blitz',
                'play_time': 1782000000 + game,
                'win_id': 0,
                'game_status': 2,
                'game_step': 4,
              },
          ];
          return http.Response(
            jsonEncode({
              'ret': 1,
              'code': 200,
              'info': 'ok',
              'data': {
                'total_page': (48 / count).ceil(),
                'total': 48,
                'records': records,
              },
            }),
            200,
          );
        }
        if (request.method == 'POST' &&
            request.url.path == '/api/v3/modelBuild/status') {
          return http.Response(
            jsonEncode({'ret': 1, 'code': 200, 'info': 'ok', 'data': true}),
            200,
          );
        }
        if (request.method == 'POST' &&
            request.url.path == '/api/v3/modelBuild/push') {
          return http.Response(
            jsonEncode({
              'ret': 1,
              'code': 200,
              'info': 'ok',
              'data': {
                'id': 88,
                'train_status': 0,
                'title': request.bodyFields['title'],
                'remark': request.bodyFields['remark'] ?? '',
              },
            }),
            200,
          );
        }
        return http.Response('not found', 404);
      });

