  test('Dartchess rejects illegal moves and handles promotion', () {
    const game = dc.Chess.initial;

    expect(
      () => game.makeSan(dc.NormalMove.fromUci('e2e5')),
      throwsA(isA<dc.PlayException>()),
    );
    final (afterE4, _) = game.makeSan(dc.NormalMove.fromUci('e2e4'));
    expect(afterE4.turn, dc.Side.black);

    final promotion = dc.Chess.fromSetup(
      dc.Setup.parseFen('4k3/P7/8/8/8/8/8/4K3 w - - 0 1'),
    );
    final promotionTargets = dc.makeLegalMoves(promotion)[dc.Square.a7];
    expect(promotionTargets, isNotNull);
    final legalMoves = <dc.NormalMove>[
      for (final to in promotionTargets!)
        for (final role in const [
          dc.Role.queen,
          dc.Role.rook,
          dc.Role.bishop,
          dc.Role.knight,
        ])
          dc.NormalMove(from: dc.Square.a7, to: to, promotion: role),
    ].where(promotion.isLegal).toList();
    expect(legalMoves.length, 4);

    final (afterPromotion, _) = promotion.makeSan(
      dc.NormalMove.fromUci('a7a8q'),
    );
    expect(afterPromotion.board.pieceAt(dc.Square.a8)?.role, dc.Role.queen);
  });
}

MistakeBookEntry _mistakeEntryForFilterTest({
  required String id,
  required String pgn,
  required String move,
  bool mastered = false,
}) {
  final now = DateTime.now();
  return MistakeBookEntry(
    id: id,
    reportKey: '$id-report',
    pgn: pgn,
    sourceTitle: '$id game',
    ply: 1,
    moveSan: move,
    bestMoveSan: 'e4',
    classification: 'Mistake',
    summary: '$id summary',
    theme: 'Opening',
    fenBefore: standardStartFen,
    fenAfter: standardStartFen,
    engineLine: 'e4',
    createdAt: now,
    updatedAt: now,
    dueAt: now,
    mastered: mastered,
  );
}

void _expectNoLayoutOverflow(WidgetTester tester) {
  final exception = tester.takeException();
  expect(exception, isNull);
}

void _expectTextInsideButton(
  WidgetTester tester, {
  required String text,
  required Finder button,
}) {
  expect(button, findsOneWidget);
  final label = find.descendant(of: button, matching: find.text(text));
  expect(label, findsOneWidget);

  const tolerance = 0.5;
  final buttonRect = tester.getRect(button);
  final labelRect = tester.getRect(label);
  expect(labelRect.left, greaterThanOrEqualTo(buttonRect.left - tolerance));
  expect(labelRect.top, greaterThanOrEqualTo(buttonRect.top - tolerance));
  expect(labelRect.right, lessThanOrEqualTo(buttonRect.right + tolerance));
  expect(labelRect.bottom, lessThanOrEqualTo(buttonRect.bottom + tolerance));
}

double _normalizedEvalForTest(String label) {
  if (label.startsWith('#+')) return 1.0;
  if (label.startsWith('#-')) return 0.0;
  final cleaned = label.replaceAll('+', '').trim();
  final value = double.tryParse(cleaned);
  if (value == null) return 0.5;
  return ((value + 4) / 8).clamp(0.06, 0.94).toDouble();
}
